export const recipes: CountryRecipe[] = [{"country":"ph","id":"sisig","slug":"sisig","title":{"zh-TW":"正宗鐵板酥脆席西格 (Pork Sisig)","en":"Authentic Sizzling Pork Sisig","fil":"Sizzling Pork Sisig ng Pampanga","ja":"本場鉄板シシグ（豚肉とレバーのカリカリ炒め）","ko":"정통 지글지글 포크 시시그 (철판 돼지고기 볶음)"},"subtitle":{"zh-TW":"龐培歐美食之都傳奇・熱氣沸騰生蛋流心・金桔辛香酥脆狂潮","en":"Culinary Capital Legend with Runny Egg, Fresh Calamansi & Crispy Pork","fil":"Alamat ng Pampanga na may itlog, sariwang sili at kalamansi","ja":"パンパンガ州発祥・香ばしい豚肉と半熟卵、カラマンシーの爽快感","ko":"팜팡가 전통의 맛, 지글거리는 반숙 계란과 깔라만시의 바삭한 조화"},"tagline":{"zh-TW":"名廚安東尼波登盛讚「足以改變世界的靈魂下酒菜」，脆皮與酸香交織","en":"Praised by Anthony Bourdain as a world-changing dish: sizzling, crunchy, porky perfection","fil":"Ang pambansang pulutan at ulam na ipinagmamalaki sa buong mundo","ja":"アンソニー・ボーディンも絶賛したフィリピン最強の国民的ビールのお供","ko":"앤서니 보뎅이 극찬한 세계 최고의 맥주 안주이자 밥도둑"},"heroImage":"/images/ph/sisig.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":25,"defaultServings":3,"caloriesPerServing":520,"category":"sizzling","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"呂宋島・龐培歐省安赫勒斯市 (Angeles City, Pampanga)","en":"Angeles City, Pampanga (Culinary Capital)","fil":"Lungsod ng Angeles, Pampanga","ja":"パンパンガ州アンヘレス市","ko":"팜팡가주 앙헬레스 시"},"famousStreetMarkets":[{"zh-TW":"安赫勒斯 Aling Lucing Sisig 創始老街","en":"Aling Lucing Sisig Crossing","fil":"Aling Lucing Sisig Crossing","ja":"アリン・ルシン発祥地","ko":"알링 루싱 시시그 본점 거리"},{"zh-TW":"馬尼拉湯都 Ugbo 美食街","en":"Ugbo Street Food Strip, Manila","fil":"Ugbo St., Tondo Maynila","ja":"マニラ・ウグボ屋台街","ko":"마닐라 우그보 야시장"}],"historyStory":{"zh-TW":"Sisig 最早只是孕婦食用的酸味涼拌菜。1970 年代，位於安赫勒斯鐵路旁的攤販女主人 Lucia Cunanan（人稱 Aling Lucing）利用鄰近克拉克美軍基地廢棄的豬頭肉、豬耳朵與豬臉肉，先水煮去腥、炭火烤焦脆後切碎，再與洋蔥、肝醬和金桔高溫翻炒，誕生了震撼世界的現代鐵板 Sisig！","en":"Originally an ancient sour salad for expectant mothers, modern Sisig was revolutionized in the 1970s by Lucia Cunanan (\"Aling Lucing\") in Angeles City. She took surplus pig heads from the nearby US Clark Air Base, boiled, charred them over hot charcoal, minced, and tossed with chicken liver, onions, and calamansi on screaming-hot cast iron.","fil":"Pinauso ni Aling Lucing Cunanan sa Angeles, Pampanga noong 1970s gamit ang pisngi at tainga ng baboy na inihaw at tinadtad nang pino, hinaluan ng atay at kalamansi sa mainit na sizzling plate.","ja":"1970年代にパンパンガ州のアリン・ルシンさんが米軍基地から余剰となった豚頭肉を活かし、煮て炭火で香ばしく焼き、細かく刻んでレバーペーストや柑橘と炒め合わせたのが現代シシグの起源です。","ko":"1970년대 팜팡가의 알링 루싱이 미군 기지에서 나온 돼지머리 부위를 숯불에 구워 잘게 다진 후, 닭간과 양파, 깔라만시와 함께 뜨거운 철판에 볶아내며 전설이 시작되었습니다."},"filipinoScript":"Sizzling Sisig na Baboy","filipinoPhonetics":"See-zling See-sig nah Bah-boy","audioPronunciationText":"Pabili po ng isang sizzling pork sisig na may itlog at maanghang!"},"ingredients":[{"id":"pork-belly-ear","name":{"zh-TW":"帶皮豬五花與豬耳朵 (肥瘦脆兼具)","en":"Pork Belly & Pork Ears (Cooked & Minced)","fil":"Liempo at Tainga ng Baboy","ja":"豚バラ肉と豚耳（茹でて細切れ）","ko":"돼지 삼겹살 및 돼지 귀 (잘게 다짐)"},"amount":500,"unitMetric":"g","unitUS":"1.1 lb","isKeyFlavor":true,"filipinoName":"Liempo at Tainga ng Baboy","filipinoPronunciation":"Lee-yem-poh aht Tah-eeng-ah nang Bah-boy","substitute":{"substituteName":{"zh-TW":"純帶皮豬五花肉丁（若無豬耳可用炸豬皮碎增脆）","en":"Skin-on Pork Belly + Crushed Chicharon for crunch","fil":"Purong Liempo na may Chicharon","ja":"皮付き豚バラ肉 ＋ 砕いたチチャロン（豚皮揚げ）","ko":"껍질 있는 삼겹살 + 부순 치차론(돼지껍데기 튀김)"},"ratio":"1:1","explanation":{"zh-TW":"豬耳朵提供軟骨爽脆感，若買不到豬耳，可全用五花肉，起鍋前拌入壓碎的酥脆炸豬皮（Chicharon）！","en":"Pork ears give cartilage crunch. If unavailable, use pork belly and fold in crushed crispy chicharon right before serving.","fil":"Kung walang tainga, gumamit ng chicharon para sa malutong na texture.","ja":"豚耳の軟骨のコリコリ感の代わりに、豚皮スナック（チチャロン）を砕いて加えると完璧です。","ko":"돼지 귀의 오독오독한 식감 대신 바삭한 치차론 과자를 부수어 넣으면 훌륭하게 대체됩니다."},"whereToBuy":{"zh-TW":"傳統市場肉攤或亞洲超市肉品區","en":"Asian butcher, Seafood City, or Mexican carniceria","fil":"Palengke o butcher shop","ja":"アジア精肉店または通販","ko":"정육점 또는 아시안 마트"}}},{"id":"chicken-liver","name":{"zh-TW":"新鮮雞肝 (慢煎搗碎成天然濃醬)","en":"Chicken Liver (Cooked & Minced/Mashed)","fil":"Atay ng Manok","ja":"鶏レバー（ソテーして粗く潰す）","ko":"닭 간 (구워서 으깸)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","isKeyFlavor":true,"filipinoName":"Atay ng Manok","filipinoPronunciation":"Ah-tie nang Mah-nok","substitute":{"substituteName":{"zh-TW":"市售優質法式/菲式雞肝醬罐頭 (Liver Spread)","en":"Canned Liver Spread (Reno brand)","fil":"Reno Liver Spread","ja":"缶詰レバースプレッド（Reno）","ko":"레노(Reno) 캔 간 스프레드"},"ratio":"3 大匙 (3 tbsp)","explanation":{"zh-TW":"菲律賓人常用 Reno 雞肝醬罐頭代替新鮮雞肝，風味更濃醇帶有微甜，非常地道！","en":"Filipino households frequently use Reno Liver Spread canned paste for instant rich umami.","fil":"Pwedeng gumamit ng Reno liver spread para mas mabilis.","ja":"フィリピンの家庭では缶詰のRenoレバースプレッドを使うのが一般的です。","ko":"필리핀 현지 가정에서는 간편하게 레노 캔 간 스프레드를 애용합니다."},"whereToBuy":{"zh-TW":"東南亞超市或網購","en":"Southeast Asian aisles or Amazon","fil":"Sari-sari store o grocery","ja":"アジア食材店","ko":"아시안 식료품점 또는 온라인"}}},{"id":"red-onion","name":{"zh-TW":"紅洋蔥 (切細丁)","en":"Red Onion (Finely Chopped)","fil":"Pulang Sibuyas","ja":"赤玉ねぎ（みじん切り）","ko":"적양파 (잘게 다짐)"},"amount":1.5,"unitMetric":"piece","unitUS":"piece","filipinoName":"Pulang Sibuyas","filipinoPronunciation":"Poo-lang See-boo-yas"},{"id":"siling-labuyo","name":{"zh-TW":"菲律賓鳥眼小辣椒 (切碎)","en":"Philippine Bird's Eye Chilies (Siling Labuyo)","fil":"Siling Labuyo","ja":"フィリピン産 小唐辛子（シリン・ラブヨ）","ko":"필리핀 쥐똥고추 (실링 라부요)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Siling Labuyo","filipinoPronunciation":"See-leeng Lah-boo-yoh"},{"id":"calamansi","name":{"zh-TW":"新鮮四季柑桔 (對半切開擠汁)","en":"Fresh Calamansi (Halved for Squeezing)","fil":"Sariwang Kalamansi","ja":"新鮮なカラマンシー（果汁）","ko":"신선한 깔라만시 (반으로 자름)"},"amount":5,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Kalamansi","filipinoPronunciation":"Kah-lah-mahn-see"},{"id":"cane-vinegar","name":{"zh-TW":"大肚婆甘蔗白醋","en":"Philippine Cane Vinegar (Sukang Maasim)","fil":"Sukang Maasim","ja":"サトウキビ酢","ko":"사탕수수 식초"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Sukang Maasim","filipinoPronunciation":"Soo-kang Mah-ah-sim"},{"id":"soy-sauce","name":{"zh-TW":"菲律賓純釀造醬油 (Toyo)","en":"Philippine Soy Sauce (Toyo)","fil":"Toyo","ja":"フィリピン醤油（トヨ）","ko":"필리핀 양조간장 (토요)"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"mayonnaise","name":{"zh-TW":"美乃滋 (現代馬尼拉滑順流派)","en":"Mayonnaise (Manila Creamy Style)","fil":"Mayonesa","ja":"マヨネーズ（クリーミー派）","ko":"마요네즈 (현대 마닐라 스타일)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Mayonesa","filipinoPronunciation":"Mah-yoh-neh-sah"},{"id":"egg","name":{"zh-TW":"新鮮生雞蛋 (打在滾燙鐵板中央)","en":"Fresh Egg (Cracked onto Sizzling Plate)","fil":"Sariwang Itlog","ja":"生卵（熱々鉄板の真ん中に落とす）","ko":"신선한 생란 (뜨거운 철판 중앙에 올림)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Itlog","filipinoPronunciation":"Eet-log"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"水煮五花肉與豬耳熟透去腥","en":"Boil & Tenderize Pork Belly and Ears","fil":"Pakuluan ang Liempo at Tainga","ja":"豚肉と豚耳を下茹でして臭みを取る","ko":"돼지 삼겹살과 귀를 푹 삶아 잡내 제거"},"instruction":{"zh-TW":"大湯鍋中放入五花肉塊、洗淨豬耳，加入清水淹過，放入拍扁整顆蒜、2片月桂葉與 1 茶匙黑胡椒粒。大火煮沸後撈除浮沫，轉中小火燉煮 35-40 分鐘，直到筷子能輕易穿透豬皮，撈出徹底瀝乾水分晾涼。","en":"In a pot, submerge pork belly and cleaned ears in water with crushed garlic cloves, 2 bay leaves, and 1 tsp black peppercorns. Bring to a boil, skim scum, and simmer 35-40 mins until skin is tender. Drain thoroughly and pat dry with paper towels.","fil":"Pakuluan ang liempo at tainga kasama ang bawang, dahon ng laurel, at paminta nang 35-40 minuto hanggang lumambot. Patuyuin nang mabuti.","ja":"鍋に豚肉、豚耳、ニンニク、ローリエ2枚、黒胡椒を入れ、アクを取りながら弱火で約40分煮込みます。取り出したら水分をペーパーでしっかり拭き取ります。","ko":"냄비에 돼지고기와 귀, 통마늘, 월계수잎 2장, 통후추를 넣고 35~40분간 푹 삶아줍니다. 건져내어 키친타월로 물기를 완전히 제거합니다."},"durationSeconds":2400,"image":"/images/ph/sisig-step1.jpg","crucialTips":{"zh-TW":"肉皮表面的水分必須徹底吸乾，後續煎炸或氣炸才能爆出如爆米花般的大水泡酥脆外皮！","en":"The skin must be completely dry before roasting/frying to achieve maximum blistering crunch!","fil":"Kailangang tuyong-tuyo ang balat bago i-ihaw o iprito para lumutong nang husto.","ja":"皮表面の水分をしっかり拭き取ることが、後のカリカリ食感を生む最大の秘訣です。","ko":"껍질 표면의 물기를 완벽히 말려야 바삭하게 부풀어 오르는 크리스피 식감이 완성됩니다."}},{"stepNumber":2,"title":{"zh-TW":"高溫煎烤爆出金黃焦脆外皮","en":"Broil, Grill or Air Fry until Ultra-Crispy","fil":"Ihawin o I-Air Fry Hanggang Malutong","ja":"香ばしく焼き上げて皮をカリカリに","ko":"껍질을 노릇하고 극도로 바삭하게 굽기"},"instruction":{"zh-TW":"【傳統平底鍋/烤網法】平底鍋下少許油中大火煎五花肉塊，將肉皮朝下壓煎，爆出金黃脆皮；或置於木炭烤網翻烤至帶有誘人炭香與微焦。【氣炸鍋模式請參見切換】。煎脆後夾出，切成 0.5 公分的細小碎丁。","en":"Traditional method: Pan-sear the boiled pork belly in a hot skillet skin-side down until blistered and golden, or grill over hot charcoal for authentic smoky char. Once cool enough to handle, finely chop all meat and ears into small dice (approx. 0.5cm).","fil":"Iprito o ihawin ang liempo at tainga hanggang maging malutong at tustado ang balat. Hiwain nang pinong-pino pagkatapos.","ja":"フライパンまたは炭火で皮目を押し付けながらカリッと焼き上げます。粗熱が取れたら、肉と耳を5mm角の細切れに刻みます。","ko":"팬에 껍질을 아래로 눌러가며 바삭하게 굽거나 숯불에 노릇하게 직화합니다. 한 김 식힌 후 0.5cm 크기로 잘게 깍둑썰기합니다."},"durationSeconds":720,"image":"/images/ph/sisig-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (395°F) for 15-18 mins","instructionOverride":{"zh-TW":"氣炸鍋模式：將煮熟吸乾水分的五花肉塊皮朝上置於氣炸炸籃中，以 200°C 氣炸 15-18 分鐘，直見豬皮起細密酥脆水泡。零油煙，外皮如餅乾般香脆！出鍋後切細碎丁。","en":"Air Fryer Variation: Place dried pork skin-side UP into the basket. Air fry at 200°C (395°F) for 15-18 minutes until the skin is intensely blistered and golden brown. Let cool slightly, then finely mince.","fil":"Paraan sa Air Fryer: Ilagay ang liempo (pataas ang balat) sa 200°C nang 15-18 minuto hanggang pumutok at lumutong ang balat. Hiwain nang pino.","ja":"ノンフライヤー設定：皮を上にしてバスケットに並べ、200℃で15〜18分加熱。皮がプツプツと膨らんで最高の食感になります。取り出して刻みます。","ko":"에어프라이어 모드: 껍질이 위로 향하게 넣고 200°C에서 15~18분간 조리합니다. 껍질이 크래커처럼 바삭하게 튀겨지면 잘게 다져줍니다."}}]},{"stepNumber":3,"title":{"zh-TW":"香煎雞肝與爆炒洋蔥辛香料","en":"Sear Chicken Liver & Sauté Aromatics","fil":"Lutuin ang Atay at Ginisang Sibuyas","ja":"鶏レバーを焼き香辛野菜と炒め合わせる","ko":"닭 간을 볶아 으깬 뒤 양파와 함께 조리"},"instruction":{"zh-TW":"鍋中少許油下雞肝，雙面煎熟後用鍋鏟或研磨碗壓成濃稠細泥。加入切碎的紅洋蔥碎（留 1/3 生洋蔥出鍋備用）和朝天椒圈，大火快速煸炒出撲鼻香氣。","en":"In a hot skillet, sear chicken livers until cooked through, then mash with a fork/spatula into a paste. Add 2/3 of the chopped red onions and sliced bird’s eye chilies. Stir-fry vigorously for 1 minute until fragrant.","fil":"Iprito ang atay at durugin. Igisa kasama ang 2/3 ng sibuyas at siling labuyo.","ja":"レバーを香ばしく焼き、ヘラで潰してペースト状にします。刻み赤玉ねぎ（1/3は仕上げ用に残す）と唐辛子を加えて強火でサッと炒めます。","ko":"팬에 닭 간을 노릇하게 익힌 뒤 주걱으로 으깨어 페이스트로 만듭니다. 적양파의 2/3와 썬 고추를 넣고 센 불에 1분간 볶아 향을 냅니다."},"durationSeconds":240,"image":"/images/ph/sisig-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"混合脆肉丁、調味醬汁與美乃滋","en":"Toss Pork, Calamansi, Seasoning & Mayo","fil":"Haluin ang Baboy, Toyo, Suka at Mayonesa","ja":"刻み肉、調味料、マヨネーズを合わせる","ko":"다진 고기, 깔라만시 양념 및 마요네즈 버무리기"},"instruction":{"zh-TW":"將切碎的金黃五花肉丁倒入鍋中，淋入 2 大匙甘蔗白醋、1.5 大匙醬油、擠入 3 顆四季桔汁與適量研磨黑胡椒。大火翻拌均勻收汁 2 分鐘，關火，拌入美乃滋增加絲滑油潤感。","en":"Toss the minced crispy pork into the pan. Pour in 2 tbsp cane vinegar, 1.5 tbsp soy sauce, freshly squeezed juice of 3 calamansi, and cracked black pepper. Toss over high heat for 2 mins. Turn off heat and stir in mayonnaise until glossy.","fil":"Ihalo ang tinadtad na baboy, sukang maasim, toyo, katas ng kalamansi, at paminta. Haluin at patayin ang apoy bago ihalo ang mayonesa.","ja":"刻んだ豚肉を加え、サトウキビ酢、醤油、カラマンシー果汁、黒胡椒を投入。強火で手早く和えたら火を止め、マヨネーズを加えて全体に艶を出します。","ko":"다진 고기를 팬에 넣고 식초, 간장, 깔라만시 즙, 흑후추를 넣어 센 불에 2분간 볶습니다. 불을 끄고 마요네즈를 넣어 부드럽게 버무립니다."},"durationSeconds":180,"image":"/images/ph/sisig-step4.jpg"},{"stepNumber":5,"title":{"zh-TW":"鐵板燒紅滋滋盛盤，打入生蛋趁熱攪拌","en":"Transfer to Sizzling Plate, Top with Egg","fil":"Ihain sa Mainit na Sizzling Plate na may Itlog","ja":"アツアツの鉄板に盛り生卵を落とす","ko":"달군 철판에 담아 생계란을 올리고 서빙"},"instruction":{"zh-TW":"將鑄鐵烤盤放在爐火上燒至冒煙（若無鐵板可直接用原熱鍋熱到底）。趁熱盛入炒好的 Sisig，中央挖個小洞打入一顆新鮮生雞蛋，周圍撒上預留的生洋蔥丁與朝天椒圈，附上切半金桔。食用時趁鐵板滾燙將雞蛋與肉丁完全攪拌勻開！","en":"Heat a cast-iron sizzling platter over high burner until smoking hot. Heap the hot Sisig onto the platter, make a center well, and crack a fresh raw egg. Garnish with remaining crisp raw onions, chili slices, and halved calamansi. Stir the egg into the piping hot meat at the table!","fil":"Initin ang sizzling plate hanggang umusok. Ilagay ang sisig, basagin ang itlog sa gitna, budburan ng sariwang sibuyas at sili. Ihalo ang itlog habang kumukulo pa!","ja":"鉄板を煙が出るまで強火で熱します。シシグを山盛りに盛り、中央にくぼみを作って生卵を割り落とします。残りの生玉ねぎと柑橘を添え、熱いうちに全体を混ぜて召し上がれ！","ko":"무쇠 철판을 연기가 날 때까지 센 불에 달군 뒤 시시그를 듬뿍 올립니다. 가운데에 신선한 생란을 톡 깨트려 올리고 생양파와 고추를 곁들여 즉석에서 비벼 먹습니다."},"durationSeconds":120,"image":"/images/ph/sisig-step5.jpg","dangerWarnings":{"zh-TW":"鑄鐵板極其滾燙，移動時務必使用厚防燙手套與木托盤，小心油脂微濺！","en":"Cast-iron platters are scorching hot! Always use heavy heat-proof gloves and place on a wooden serving base.","fil":"Napakainit ng bakal na plato; gumamit ng gloves at kahoy na patungan.","ja":"鉄板は超高温です。火傷に注意し、必ず木製プレートにのせて運んでください。","ko":"철판이 매우 뜨거우니 반드시 오븐 장갑을 착용하고 나무 받침대에 올려 서빙하세요."}}],"troubleshooting":[{"id":"not-crispy","problem":{"zh-TW":"豬肉丁吃起來油膩軟爛，缺乏爽脆度","en":"Meat is soggy and oily instead of crispy","fil":"Malambot at mamantika ang sisig, hindi malutong","ja":"豚肉が油っぽくベチャッとしてカリカリ感がない","ko":"고기가 바삭하지 않고 눅눅하고 기름짐"},"cause":{"zh-TW":"水煮後豬皮水分未吸乾，或煎烤溫度過低、時間不足","en":"Pork skin had excess moisture, or frying oil/pan was not hot enough","fil":"Basa ang balat bago iprito o mahina ang apoy","ja":"下茹で後の水気が残っていたか、焼き温度が低すぎたため","ko":"삶은 후 물기를 충분히 닦지 않았거나 불이 약해 제대로 튀겨지지 않음"},"solution":{"zh-TW":"五花肉煮熟後必須用廚房紙巾壓乾，氣炸鍋以 200°C 高溫將豬皮油脂完全逼出至起大泡；起鍋前可額外拌入少許捏碎的炸豬皮（Chicharon）瞬間增加脆爽！","en":"Pat boiled meat completely dry. Air fry at 200°C to blow up crispy blisters. You can also fold in crushed chicharon right before plating.","fil":"Patuyuin ang balat bago lutuin. Magdagdag ng durog na chicharon bago ihain.","ja":"水分を完全に拭き取り、高温で皮を膨らませます。砕いたチチャロンを仕上げに混ぜる裏技も有効です。","ko":"물기를 완벽히 제거하고 200도 이상 고온에 구우며, 완성 직전 바삭한 치차론을 부숴 넣으면 식감이 살아납니다."}},{"id":"too-sour-or-salty","problem":{"zh-TW":"酸度過於刺激嗆口，或鹹度太高","en":"Too harshly sour or salty","fil":"Masyadong maasim o maalat","ja":"酸味が強すぎるか、塩辛い","ko":"신맛이 너무 쏘거나 너무 짬"},"cause":{"zh-TW":"醋過早加入冷鍋未完全揮發，或美乃滋與醬油比例失衡","en":"Vinegar was added without cooking off, or unbalanced soy sauce","fil":"Hindi naluto nang kusa ang suka","ja":"酢の酸味を飛ばす加熱が足りなかったため","ko":"식초를 넣고 불에 충분히 날리지 않았거나 간장 양 과다"},"solution":{"zh-TW":"醋倒入後切忌立即攪拌，讓其在高溫鍋底沸騰 30 秒至酒酸味自然轉為甘醇；若已過酸，可補拌 1 茶匙美乃滋或少許白糖中和。","en":"Do not stir immediately after pouring vinegar; let it bubble for 30s. Counter excess sourness with an extra dollop of mayo.","fil":"Hayaang kumulo ang suka nang hindi hinahalo. Magdagdag ng kaunting asukal o mayonesa.","ja":"酢を加えたらすぐに混ぜず、30秒ほど沸騰させて角を取ります。酸っぱすぎる場合はマヨネーズを少し足して整えます。","ko":"식초를 넣은 직후 젓지 말고 30초간 끓여 신미를 날려준 뒤 섞고, 마요네즈를 조금 더 넣어 부드럽게 조절합니다."}}],"proTips":[{"zh-TW":"【老饕吃法】：桌上的鮮切四季柑（Calamansi）一定要在即將入口前才現擠在肉上，熱氣烘出清新柑橘油香，是最極致的享受！","en":"Pro Tip: Always squeeze your fresh calamansi tableside right onto the sizzling meat. The heat unlocks the fragrant citrus rind oils instantly!","fil":"Tip ng Kusinero: Pigain ang kalamansi bago kainin habang umuusok pa para lumabas ang bango ng balat nito.","ja":"プロの技：カラマンシーは食べる直前に熱々の肉へ絞りかけると、果皮の精油が立ち上り最高の香りを放ちます。","ko":"셰프 팁: 서빙 직후 뜨거운 고기 위에 신선한 깔라만시를 즉석에서 짜주면 시트러스 에센스가 폭발하며 최상의 맛을 냅니다."},{"zh-TW":"搭配生啤酒（San Miguel Pale Pilsen）或大碗熱騰騰的蒜香大蒜飯（Sinangag），是菲律賓人最驕傲的國民靈魂搭配！","en":"Pairing: Best enjoyed with ice-cold San Miguel Pale Pilsen beer or a massive bowl of toasted garlic fried rice (Sinangag)!","fil":"Pinakamasarap kasabay ng malamig na San Miguel beer o mainit na sinangag na kanin.","ja":"ペアリング：キンキンに冷えたサンミゲルビール、または山盛りのガーリックライス（シナガグ）と合わせるのが王道です！","ko":"페어링: 시원한 산미구엘 맥주 또는 고소한 마늘 볶음밥(시낭악)과 함께 먹으면 그 어떤 요리도 부럽지 않습니다."}]},{"country":"ph","id":"adobo","slug":"adobo","title":{"zh-TW":"正宗菲律賓國菜雙拼阿多波 (Chicken & Pork Adobo)","en":"Classic Chicken & Pork Adobo (Adobong Puti/Pula)","fil":"Klasikong Adobong Manok at Baboy","ja":"本場フィリピンの国民食アドボ（鶏肉と豚肉の酢醤油煮込み）","ko":"필리핀 국민 요리 아도보 (치킨 & 포크 식초 간장 조림)"},"subtitle":{"zh-TW":"百年白甘蔗醋・整頭大蒜黑胡椒爆炒・越陳越香白飯殺手","en":"Slow-Simmered Garlic, Cane Vinegar, Bay Leaves & Caramelized Glaze","fil":"Lutong bahay na may bawang, dahon ng laurel, toyo at sukang maasim","ja":"サトウキビ酢、丸ごとにんにく、ローリエの芳醇な旨味が染み渡る逸品","ko":"사탕수수 식초, 통마늘, 월계수 잎으로 졸여낸 감칠맛의 정점"},"tagline":{"zh-TW":"每個菲律賓家庭永遠的驕傲，肉質酥嫩、醬汁拌飯天下第一","en":"The undisputed national dish: tender meat braised in savory vinegar, soy, and garlic","fil":"Ang paboritong lutong-ina ng bawat Pilipino, mas masarap habang tumatagal","ja":"フィリピン人の誰もが愛するおふくろの味。一晩寝かせると旨味がさらに倍増","ko":"모든 필리핀인이 사랑하는 소울 푸드. 다음 날 먹으면 더 깊어지는 풍미"},"heroImage":"/images/ph/adobo.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":40,"defaultServings":4,"caloriesPerServing":480,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot","airFryer"],"culture":{"originRegion":{"zh-TW":"全菲律賓群島（西班牙殖民前已存在的古老土著原味烹調法）","en":"Indigenous Philippine Islands (Pre-colonial origin)","fil":"Buong Kapuluan ng Pilipinas","ja":"フィリピン全土（スペイン植民地以前の先住民伝統料理）","ko":"필리핀 전역 (식민지 이전부터 전해 내려온 전통 조리법)"},"famousStreetMarkets":[{"zh-TW":"馬尼拉 Carriedo 街邊平價熱炒食堂 (Carinderia)","en":"Carinderia food stalls across Manila","fil":"Mga Karinderya sa Maynila","ja":"マニラ庶民の大衆食堂カリンデリア","ko":"마닐라 로컬 카린데리아 식당가"},{"zh-TW":"奎松市 Maginhawa 美食街","en":"Maginhawa Food District, Quezon City","fil":"Maginhawa St., Quezon City","ja":"ケソン市マギンハワ通り","ko":"퀘존 시티 마긴하와 거리"}],"historyStory":{"zh-TW":"在西班牙人踏上菲律賓之前，島民為了在炎熱熱帶保存肉品，便利用天然發酵的甘蔗白醋與海鹽、野生大蒜慢燉肉塊。16世紀西班牙人到來時，借用了西語「Adobar（醃製）」一詞稱呼它。如今 Adobo 演變為加入醬油、大量蒜瓣、黑胡椒粒與乾燥月桂葉的國寶燉肉，也是菲律賓宇航員與海外遊子的心靈寄託！","en":"Long before Ferdinand Magellan arrived in 1521, indigenous Filipinos cooked meat with wild vinegar and salt to preserve it in the tropical climate. Spanish colonizers noted this technique and labeled it \"Adobo\" (from Spanish adobar, meaning marinade). Over centuries, dark soy sauce and bay leaves transformed it into the beloved national classic.","fil":"Bago pa man dumating ang mga Espanyol, nagluluto na ang mga katutubong Pilipino ng karne sa suka at asin upang hindi mapanis sa init. Tinawag itong \"adobo\" ng mga Kastila at ngayon ay naging pambansang ulam.","ja":"16世紀のスペイン来訪以前から、熱帯の気候で肉を保存するためサトウキビ酢で煮込む先住民族の知恵がありました。スペイン人がこれを「アドバル（マリネする）」と名付け、現在の国民食へと発展しました。","ko":"16세기 스페인 정복 이전부터 열대 기후에서 고기를 보존하기 위해 식초와 마늘로 졸여먹던 원주민의 지혜에서 출발하여, 간장과 월계수 잎이 더해져 필리핀 최고의 대표 요리가 되었습니다."},"filipinoScript":"Adobong Manok at Baboy","filipinoPhonetics":"Ah-doh-bong Mah-nok aht Bah-boy","audioPronunciationText":"Pabili po ng kanin at isang order ng Adobong Manok at Baboy!"},"ingredients":[{"id":"pork-belly","name":{"zh-TW":"五花肉塊 (切 3 公分大塊)","en":"Pork Belly (Cut into 1.5-inch cubes)","fil":"Liempo ng Baboy","ja":"豚バラ角切り肉（3cm角）","ko":"돼지 삼겹살 (3cm 깍둑썰기)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Liempo ng Baboy","filipinoPronunciation":"Lee-yem-poh nang Bah-boy"},{"id":"chicken-thighs","name":{"zh-TW":"帶骨帶皮雞腿塊 (切大塊)","en":"Bone-in Chicken Thighs / Drumsticks (Cut into pieces)","fil":"Paa o Hita ng Manok","ja":"骨付き鶏もも肉（ぶつ切り）","ko":"토막 닭다리살/넓적다리 (뼈 있는 것)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Hita ng Manok","filipinoPronunciation":"Hee-tah nang Mah-nok"},{"id":"garlic-whole-head","name":{"zh-TW":"新鮮大蒜 (整頭拍扁，保留少許蒜皮)","en":"Fresh Garlic (1 whole head, crushed)","fil":"Bawang (Isang buong ulo)","ja":"にんにく（丸ごと1株、包丁の腹で潰す）","ko":"신선한 통마늘 (1통 통째로 칼등으로 으깸)"},"amount":10,"unitMetric":"clove","unitUS":"clove","isKeyFlavor":true,"filipinoName":"Bawang","filipinoPronunciation":"Bah-wang"},{"id":"cane-vinegar","name":{"zh-TW":"菲律賓大肚婆白甘蔗醋","en":"Philippine Cane Vinegar (Sukang Maasim)","fil":"Sukang Maasim (Datu Puti)","ja":"フィリピン産 サトウキビ酢","ko":"필리핀 사탕수수 식초"},"amount":80,"unitMetric":"ml","unitUS":"0.33 cup","isKeyFlavor":true,"filipinoName":"Sukang Maasim","filipinoPronunciation":"Soo-kang Mah-ah-sim","substitute":{"substituteName":{"zh-TW":"無糖純米醋或白醋 + 蘋果醋 (2:1)","en":"Rice Vinegar or White Distilled + Apple Cider (2:1)","fil":"Puting Suka na may Apple Cider","ja":"米酢または穀物酢＋リンゴ酢（2:1）","ko":"쌀식초 또는 양조식초 + 사과식초 (2:1)"},"ratio":"1:1","explanation":{"zh-TW":"純甘蔗醋酸度約 4.5%，溫和且有蔗糖發酵底蘊；若使用一般 5% 白醋，可加一小撮糖調和。","en":"Cane vinegar is mellow with subtle cane sweetness. If using white vinegar, add a pinch of sugar.","fil":"Magdagdag ng kurot ng asukal kung regular na suka ang gagamitin.","ja":"日本の穀物酢を使う場合は、砂糖をひとつまみ加えて酸味をまろやかにします。","ko":"사탕수수 식초는 산미가 부드러우므로 일반 식초 사용 시 설탕 한 꼬집을 더해줍니다."},"whereToBuy":{"zh-TW":"東南亞超市或網購","en":"Asian markets or Weee!","fil":"Supermarket o sari-sari store","ja":"アジア食材店","ko":"아시안 식료품점 또는 온라인"}}},{"id":"soy-sauce","name":{"zh-TW":"菲律賓純釀醬油 (Silver Swan 或 Datu Puti)","en":"Philippine Soy Sauce (Toyo)","fil":"Toyo","ja":"フィリピン濃口醤油（トヨ）","ko":"필리핀 양조간장 (Silver Swan 또는 Datu Puti)"},"amount":60,"unitMetric":"ml","unitUS":"0.25 cup","isKeyFlavor":true,"filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"bay-leaves","name":{"zh-TW":"乾燥月桂葉","en":"Dried Laurel / Bay Leaves","fil":"Dahon ng Laurel","ja":"ローリエ（月桂樹の葉）","ko":"말린 월계수 잎"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Dahon ng Laurel","filipinoPronunciation":"Dah-hon nang Lah-oo-rel"},{"id":"black-peppercorn","name":{"zh-TW":"整顆原粒黑胡椒 (部分用刀背壓碎)","en":"Whole Black Peppercorns (lightly cracked)","fil":"Buong Paminta","ja":"粒黒胡椒（軽く潰す）","ko":"통흑후추 (칼등으로 살짝 으깸)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","isKeyFlavor":true,"filipinoName":"Paminta","filipinoPronunciation":"Pah-meen-tah"},{"id":"brown-sugar","name":{"zh-TW":"二砂或黑糖 (平衡酸鹹)","en":"Brown Sugar (to balance & glaze)","fil":"Pulang Asukal","ja":"黒糖または三温糖","ko":"흑설탕 또는 황설탕"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","filipinoName":"Asukal","filipinoPronunciation":"Ah-soo-kal"},{"id":"water","name":{"zh-TW":"清水或清高湯","en":"Water or light broth","fil":"Tubig","ja":"水または薄い出汁","ko":"물 또는 맑은 육수"},"amount":180,"unitMetric":"ml","unitUS":"0.75 cup","filipinoName":"Tubig","filipinoPronunciation":"Too-beeg"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"醃漬肉塊入味","en":"Marinate Meat in Soy, Garlic & Pepper","fil":"Ibabad ang Karne sa Toyo, Bawang at Paminta","ja":"肉に下味を揉み込む","ko":"고기에 간장, 마늘, 후추로 밑간하기"},"instruction":{"zh-TW":"取大碗放入切塊五花肉與雞腿塊，加入拍碎大蒜、醬油、壓破黑胡椒粒與月桂葉，抓勻醃漬至少 20-30 分鐘（冷藏醃漬隔夜風味更醇厚）。注意此步驟先不要加入醋。","en":"Combine pork belly and chicken pieces in a bowl. Add crushed garlic, soy sauce, cracked black peppercorns, and bay leaves. Toss thoroughly and let marinate for at least 20-30 mins (or overnight in the fridge). Do NOT add vinegar yet.","fil":"Pagsamahin ang baboy at manok sa mangkok kasama ang toyo, bawang, paminta, at dahon ng laurel. Ibabad nang 20-30 minuto. Huwag munang ilagay ang suka.","ja":"ボウルに豚肉、鶏肉、潰したニンニク、醤油、粒黒胡椒、ローリエを入れ、手でよく揉み込んで20〜30分置きます。※この段階ではまだお酢は入れません。","ko":"볼에 돼지고기와 닭고기, 으깬 마늘, 간장, 통후추, 월계수 잎을 넣고 골고루 버무려 20~30분간 재워둡니다. (식초는 아직 넣지 않습니다)."},"durationSeconds":1200,"image":"/images/ph/adobo-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"高溫煎肉至表面金黃微焦","en":"Brown Pork & Chicken in Hot Skillet","fil":"Iprito ang Karne Hanggang Mamula","ja":"肉の表面を香ばしく焼き付ける","ko":"팬에 고기 겉면을 노릇하게 시어링"},"instruction":{"zh-TW":"厚底鍋中倒 1 大匙油中大火燒熱，夾出醃好的肉塊（醃汁與蒜粒留在碗中備用），放入鍋中雙面煎至金黃微焦、釋出誘人肉香（約 6-8 分鐘）。煎出焦糖化褐變是頂級 Adobo 醬汁香氣的根基。","en":"Heat 1 tbsp oil in a heavy pot over medium-high heat. Remove meat from marinade (save the liquid and garlic). Sear the pork and chicken pieces until beautifully browned on all sides (6-8 mins). Browning creates essential caramelized fond on the pan bottom.","fil":"Painitin ang mantika sa kaldero. Iprito ang karne hanggang maging mamula-mula at masarap tingnan (itabi ang pinagbabaran).","ja":"鍋に油大さじ1を熱し、漬けダレから取り出した肉を中強火で表面がこんがりするまで6〜8分焼き付けます（残りのタレとニンニクは取っておく）。","ko":"냄비에 기름을 두르고 재워둔 고기만 건져내어 겉면이 노릇해질 때까지 6~8분간 구워줍니다 (남은 양념장과 마늘은 보관)."},"durationSeconds":480,"image":"/images/ph/adobo-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"注入甘蔗醋烹煮（關鍵：先不攪拌！）","en":"Pour Cane Vinegar & Simmer UNTOUCHED","fil":"Ilagay ang Suka (Bawal Haluin Muna!)","ja":"サトウキビ酢を注ぎ、混ぜずに沸騰させる","ko":"식초를 붓고 젓지 않고 끓이기 (핵심 비법!)"},"instruction":{"zh-TW":"將碗中剩餘的蒜瓣、月桂葉與醬油汁倒回鍋中，接著沿鍋邊淋入 80ml 白甘蔗醋與 180ml 清水。大火煮沸後【切記絕對不要用鏟子攪拌！】，保持敞開鍋蓋沸騰 3-4 分鐘，讓醋的生澀酸嗆味充分揮發，轉化為溫潤甘酸。","en":"Pour the reserved marinade, garlic, and bay leaves back in. Pour in 80ml cane vinegar and 180ml water. Bring to a rapid rolling boil UNCOVERED. [CRUCIAL RULE: DO NOT STIR!] Let it bubble vigorously untouched for 3-4 minutes so raw harsh vinegar acidity cooks off.","fil":"Ibalik ang pinagbabaran at ibuhos ang suka at tubig. Pakuluan nang HINDI HINAHALO nang 3-4 minuto upang mawala ang tapang ng hilaw na suka.","ja":"残りのタレ、ニンニク、ローリエを鍋に戻し、サトウキビ酢と水を加えます。沸騰したら【絶対に混ぜないこと！】。フタをせず3〜4分グツグツ沸かして酢のツンとした刺激を飛ばします。","ko":"남은 양념, 마늘, 월계수 잎을 넣고 식초 80ml와 물 180ml를 붓습니다. 끓어오르면 【절대로 젓지 마세요!】 뚜껑을 열고 3~4분간 그대로 끓여 톡 쏘는 생식초 향을 날려줍니다."},"durationSeconds":240,"image":"/images/ph/adobo-step3.jpg","crucialTips":{"zh-TW":"加醋後立即攪拌會破壞酸味的醇化，使湯汁變濁發澀。靜置沸騰是每位菲籍媽媽代代相傳的美味黃金鐵則！","en":"Stirring raw vinegar immediately results in harsh, chalky sourness. Letting it boil undisturbed transforms it into sweet, mellow umami.","fil":"Kapag hinalo agad ang suka, magiging mapait o matapang ang asim. Hayaan itong kusa kumulo.","ja":"酢を入れてすぐかき混ぜると酸味がトゲトゲしくなります。じっと沸騰を待つのが本場の掟です。","ko":"식초를 넣자마자 저으면 거칠고 떫은 신맛이 남습니다. 손대지 않고 끓이는 것이 필리핀 어머니들의 불문율입니다."}},{"stepNumber":4,"title":{"zh-TW":"加蓋慢燉至五花肉酥軟酥爛","en":"Cover & Simmer on Low Heat until Tender","fil":"Takpan at Pakuluan sa Mahinang Apoy","ja":"フタをして弱火でじっくり煮込む","ko":"뚜껑 덮고 뭉근한 약불에 부드럽게 조리기"},"instruction":{"zh-TW":"加入 1 茶匙二砂，拌勻。蓋上鍋蓋，轉小火慢燉 25-30 分鐘，直到五花肉軟嫩化口，雞肉酥軟多汁，湯汁呈現琥珀透亮色。","en":"Stir in 1 tsp brown sugar. Cover with lid, turn heat down to low, and simmer gently for 25-30 minutes until the pork belly is meltingly tender and chicken absorbs the dark savory sauce.","fil":"Ihalo ang 1 kutsaritang asukal. Takpan at hinaan ang apoy nang 25-30 minuto hanggang lumambot ang karne.","ja":"黒糖小さじ1を加えて全体を混ぜます。フタをして弱火で25〜30分、豚肉が箸で崩れるほど柔らかくなるまで煮込みます。","ko":"흑설탕 1작은술을 넣고 섞은 뒤 뚜껑을 덮고 약불에서 25~30분간 뭉근하게 졸여 고기를 부드럽게 익힙니다."},"durationSeconds":1800,"image":"/images/ph/adobo-step4.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Meat/Stew Mode (High Pressure) for 15 mins","instructionOverride":{"zh-TW":"壓力鍋模式：使用 Sauté（煎炒）檔將肉塊與蒜粒煎香，注入醬油、醋與水（水份減少至 120ml），加蓋選 Meat/Stew 高壓 15 分鐘，自然洩壓 10 分鐘。開蓋後開 Sauté 檔大火收汁 5 分鐘至油亮起稠。","en":"Instant Pot Variation: Use Sauté mode to brown meat and garlic. Add marinade, vinegar, and water (reduce water to 120ml). Lock lid and cook on High Pressure for 15 mins, followed by 10 mins natural release. Open lid and switch back to Sauté for 5 mins to reduce glaze.","fil":"Instant Pot: Gamitin ang Sauté mode para iprito ang karne. Ilagay ang sabaw (bawasan ang tubig sa 120ml). Isara at i-set sa High Pressure nang 15 minuto. I-sauté nang 5 minuto para lumapot ang sarsa.","ja":"電気圧力鍋設定：Sautéモードで肉を焼き、調味料と水（120mlに減量）を加えます。高圧で15分加圧調理後、10分蒸らして減圧。フタを開けてSautéで5分煮詰めてツヤを出します。","ko":"인스턴트팟 설정: 볶음(Sauté) 모드로 고기를 굽고, 양념과 물(120ml로 감소)을 넣은 뒤 고압 15분 조리 후 10분 자연 감압합니다. 뚜껑을 열고 볶음 모드로 5분간 국물을 졸여줍니다."}},{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (395°F) for 5-6 mins (Crispy Adobo Finish)","instructionOverride":{"en":"For Crispy Air Fryer Finish: Transfer braised tender pork and chicken pieces into air fryer basket. Air fry at 200°C (395°F) for 5-6 mins until edges turn crunchy and caramelized, then ladle sauce over.","zh-TW":"若使用氣炸鍋增脆：將燉至軟嫩的阿多波雞肉與五花肉撈出排入炸籃，以 200°C 氣炸 5-6 分鐘至表皮微焦金黃香脆，淋上濃縮醬汁享用！","ja":"ノンフライヤー仕上げ：煮込んだ肉をバスケットに移し、200℃で5〜6分加熱して表面をカリッと香ばしく焼き上げ、濃厚な煮汁をかけます。","ko":"에어프라이어 마무리: 부드럽게 익은 고기를 바스켓에 옮겨 200도에서 5~6분간 구워 겉을 바삭하게 만든 후 조린 양념을 끼얹습니다.","th":"สำหรับหม้อทอดไร้น้ำมัน: นำเนื้อที่ตุ๋นเปื่อยแล้วใส่หม้อทอด อบที่ 200°C นาน 5-6 นาทีจนผิวเกรียมกรอบ แล้วราดน้ำซอส"}}]},{"stepNumber":5,"title":{"zh-TW":"開蓋大火收汁，形成油亮焦糖光澤","en":"Uncover & Reduce to a Glossy Caramelized Glaze","fil":"Patuyuin nang Kaunti Hanggang Kumintab ang Sarsa","ja":"フタを開けて煮詰め、照り焼き状のツヤを出す","ko":"뚜껑 열고 센 불에 졸여 윤기 나는 글레이즈 완성"},"instruction":{"zh-TW":"揭開鍋蓋，轉中大火收汁 5-6 分鐘，同時用湯勺將濃郁油亮的蒜香醬汁不斷淋在肉塊上，直到湯汁變濃縮成油亮膠質（若喜歡焦脆口感，可將肉塊放進氣炸鍋 200°C 氣炸 3 分鐘回烤）。盛盤配熱呼呼的白飯！","en":"Remove lid, turn heat to medium-high, and simmer for 5-6 mins. Spoon the glossy garlic-vinegar oil over the meat continuously until the sauce reduces into a rich, lip-smacking lacquer. Serve over massive mounds of steaming white rice!","fil":"Buksan ang takip at pakuluan sa katamtamang lakas ng apoy nang 5-6 minuto hanggang kumintab at lumapot ang sarsa. Ihain kasama ng mainit na kanin!","ja":"フタを取り、中強火で5〜6分煮詰めます。スプーンで濃厚な煮汁を肉に何度も回しかけ、美しい照りが出たら完成。炊きたてのご飯の上にたっぷりかけてどうぞ！","ko":"뚜껑을 열고 중강불에서 5~6분간 국물을 끼얹어가며 졸여줍니다. 소스가 자작하게 농축되어 고기에 윤기가 돌면 완성입니다. 따뜻한 밥 위에 듬뿍 얹어 즐기세요!"},"durationSeconds":360,"image":"/images/ph/adobo-step5.jpg"}],"troubleshooting":[{"id":"vinegar-too-sharp","problem":{"zh-TW":"酸味嗆鼻刺口，不夠柔和醇香","en":"Harsh and piercing vinegar taste","fil":"Masyadong matapang ang asim ng suka","ja":"酢の酸味が強すぎて喉にツンとくる","ko":"식초 맛이 너무 강하고 톡 쏨"},"cause":{"zh-TW":"加醋後立即攪動，或加蓋過早，酸氣被悶在鍋中無法揮發","en":"Stirred the vinegar immediately or covered the pot before raw fumes could escape","fil":"Hinalo agad ang suka o tinakpan agad ang kaldero","ja":"酢を入れた直後にかき混ぜたか、早々にフタをして酸気を閉じ込めたため","ko":"식초를 붓고 바로 저었거나 뚜껑을 너무 일찍 닫아 신미가 증발하지 못함"},"solution":{"zh-TW":"加醋後務必大火沸騰 3 分鐘且不攪拌。若已過酸，可補加 1/2 茶匙黑糖及 2 大匙清水，開蓋微收汁即可挽救。","en":"Let boil uncovered without stirring for 3 mins. Salvage by adding 1/2 tsp brown sugar and 2 tbsp water, then reduce gently.","fil":"Pakuluan nang walang takip nang hindi hinahalo. Magdagdag ng kaunting asukal kung maasim pa rin.","ja":"酢を入れたらフタを開けたまま強火で3分放置。酸味が残る場合は黒糖小さじ半分と水を足して調整します。","ko":"식초를 넣고 뚜껑을 연 채 3분간 젓지 마세요. 이미 시다면 흑설탕 반 티스푼과 물 2큰술을 넣고 살짝 더 졸여줍니다."}}],"proTips":[{"zh-TW":"【隔夜阿多波更美味定律】：Adobo 煮好的當天很美味，但放在冰箱冷藏一夜後，肉脂與醋、蒜香徹底融為一體，隔天加熱吃風味直接躍升 200%！","en":"The Overnight Adobo Rule: Adobo is incredible today, but after resting overnight in the fridge, the pork fat, vinegar, and garlic harmonize into an out-of-this-world depth of flavor. Always make extra!","fil":"Batas ng Adobo: Mas masarap ang adobo kapag pinalipas ang magdamag dahil sumisipsip ang sarsa sa laman ng karne.","ja":"アドボの黄金律：作ってすぐも美味ですが、冷蔵庫で一晩寝かせると肉汁と酢とニンニクが奇跡的な調和を遂げ、翌日は格段に美味しくなります。","ko":"아도보의 법칙: 당일도 맛있지만 냉장고에 하룻밤 재운 뒤 다음 날 데워 먹으면 고기와 소스의 감칠맛이 2배 이상 깊어집니다."}]},{"country":"ph","id":"sinigang","slug":"sinigang","title":{"zh-TW":"正宗羅望子排骨酸湯 (Sinigang na Baboy)","en":"Tamarind Pork Rib Sour Soup (Sinigang na Baboy)","fil":"Sinigang na Baboy sa Sampalok","ja":"本場タマリンドポーク酸味スープ（シニガン・ナ・バボイ）","ko":"정통 타마린드 돼지갈비 신맛 탕 (시니강 나 바보이)"},"subtitle":{"zh-TW":"世界最佳湯品榜首・熟成羅望子開胃果酸・空心菜番茄鮮嫩燉排骨","en":"World’s #1 Ranked Soup: Tangy Tamarind Broth, Pork Ribs & Fresh Water Spinach","fil":"Paboritong sabaw ng pamilya na may maasim na sampalok, kangkong at labanos","ja":"世界スープランキング世界一！爽快なタマリンドの酸味と骨付き肉の旨味","ko":"세계 최고 수프 1위에 빛나는 시원하고 상큼한 타마린드 갈비탕"},"tagline":{"zh-TW":"風靡全球的菲律賓國寶酸湯，酸爽開胃、肉香四溢，喝一口暑氣全消","en":"TasteAtlas World’s Best Soup: irresistible mouthwatering sourness that warms the soul","fil":"Ang pampagana at mainit na sabaw na laging hinahanap-hanap ng bawat Pilipino","ja":"一口飲むとやみつきになる絶妙な酸味。脂っこい料理もスッキリ洗い流す魔法のスープ","ko":"한 입 먹자마자 입맛을 돋우는 깊은 산미와 구수한 고기 국물의 완벽한 조화"},"heroImage":"/images/ph/sinigang.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":45,"defaultServings":4,"caloriesPerServing":380,"category":"soups","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"他加祿原鄉與全菲群島（Tagalog Region）","en":"Tagalog Region & Across the Philippines","fil":"Katagalugan at Buong Pilipinas","ja":"タガログ地方およびフィリピン全域","ko":"타갈로그 지역 및 필리핀 전역"},"famousStreetMarkets":[{"zh-TW":"奎阿坡大市場生鮮食攤","en":"Quiapo Wet Market Food Stalls","fil":"Palengke ng Quiapo","ja":"キアポ市場食堂","ko":"퀴아포 수산시장 식당"},{"zh-TW":"宿霧卡爾邦老市場","en":"Carbon Market Eateries, Cebu","fil":"Carbon Market sa Cebu","ja":"セブ・カルボン市場","ko":"세부 카르본 시장"}],"historyStory":{"zh-TW":"Sinigang 源自他加祿語「Sigang」（慢火煨燉）。菲律賓人在熱帶島嶼氣候中，利用野生的羅望子（Sampalok）、青芒果或卡米亞斯（Kamias）的天然果酸來烹煮肉類與海鮮。其微酸帶鮮的清爽滋味，在 2021 與 2022 年連續被國際美食權威指南 TasteAtlas 評選為「全球最佳湯品第一名」！","en":"Derived from the Tagalog root \"sigang\" (to stew), indigenous Filipinos turned to local souring fruits like tamarind (sampalok), green mango, and kamias to create clean, revitalizing broths. It was voted the #1 Best Soup in the World by TasteAtlas multiple years in a row!","fil":"Mula sa salitang \"sigang\" na ibig sabihin ay ilaga. Ginagamitan ng maasim na prutas tulad ng sampalok, kamias, o bayabas. Ginawaran bilang pinakamasarap na sabaw sa buong mundo ng TasteAtlas.","ja":"タガログ語の「煮る（シガン）」が語源。熱帯で食欲を刺激するため、自生するタマリンドの果実の酸味を活かして作られました。世界グルメガイド「TasteAtlas」で世界一のスープに選出された名作です。","ko":"타갈로그어로 \"끓이다\"라는 뜻에서 유래했으며, 야생 타마린드의 상큼한 산미를 활용해 고기와 채소를 시원하게 끓여낸 국물 요리로 세계 최고 수프 1위에 선정되었습니다."},"filipinoScript":"Sinigang na Baboy sa Sampalok","filipinoPhonetics":"See-nee-gang nah Bah-boy sah Sahm-pah-lok","audioPronunciationText":"Pahingi po ng mainit na sabaw ng Sinigang na Baboy!"},"ingredients":[{"id":"pork-ribs","name":{"zh-TW":"豬小排或帶骨軟骨 (切塊)","en":"Pork Spare Ribs or Pork Belly (Cut into chunks)","fil":"Buto-buto o Liempo ng Baboy","ja":"豚スペアリブ（一口大）","ko":"돼지 등갈비 또는 삼겹살 (한입 크기)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lb","isKeyFlavor":true,"filipinoName":"Buto-buto ng Baboy","filipinoPronunciation":"Boo-toh Boo-toh nang Bah-boy"},{"id":"tamarind-soup-mix","name":{"zh-TW":"天然羅望子酸湯粉 (Knorr Sinigang Mix) 或新鮮羅望子泥","en":"Tamarind Soup Base Mix (Knorr Sinigang) or Fresh Tamarind Pulp","fil":"Sinigang sa Sampalok Mix","ja":"タマリンドスープの素（クノール・シニガン）","ko":"타마린드 수프 베이스 믹스 (Knorr 시니강 믹스)"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","isKeyFlavor":true,"filipinoName":"Sampalok Mix","filipinoPronunciation":"Sahm-pah-lok Mix","substitute":{"substituteName":{"zh-TW":"純無糖羅望子濃縮膏 2 大匙 + 檸檬汁 1 大匙","en":"Pure Tamarind Paste (2 tbsp) + Fresh Lemon Juice (1 tbsp)","fil":"Purong Katas ng Sampalok at Lemon","ja":"タマリンドペースト大さじ2 ＋ レモン果汁大さじ1","ko":"순수 타마린드 페이스트 2큰술 + 레몬즙 1큰술"},"ratio":"1:1","explanation":{"zh-TW":"若買不到 Knorr 菲律賓專用羅望子粉包，可用東南亞純羅望子膏調水，加少許洋蔥與魚露調配。","en":"Tamarind paste delivers authentic botanical sourness. Whisk with warm water and a splash of fish sauce.","fil":"Tunawin ang purong sampalok sa maligamgam na tubig.","ja":"市販のタマリンドペーストをお湯で溶かし、ナンプラーで塩気を整えて代用できます。","ko":"타마린드 페이스트를 따뜻한 물에 풀고 피시소스로 간을 맞추면 정통 맛이 납니다."},"whereToBuy":{"zh-TW":"各大亞洲超市調味區或網購","en":"Asian markets, Seafood City, Amazon","fil":"Supermarket o sari-sari store","ja":"アジア食材店・通販","ko":"아시안 마트 또는 온라인"}}},{"id":"kangkong","name":{"zh-TW":"新鮮空心菜 (摘段，留下鮮嫩菜葉與嫩莖)","en":"Fresh Water Spinach (Kangkong, trimmed)","fil":"Kangkong","ja":"空芯菜（クウシンサイ）","ko":"신선한 공심채 (모닝글로리)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","isKeyFlavor":true,"filipinoName":"Kangkong","filipinoPronunciation":"Kahng-kong"},{"id":"radish","name":{"zh-TW":"白蘿蔔 (去皮切厚圓片)","en":"White Daikon Radish (Sliced)","fil":"Labanos","ja":"大根（厚めの輪切り）","ko":"무 (두툼하게 반달썰기)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Labanos","filipinoPronunciation":"Lah-bah-nos"},{"id":"tomatoes","name":{"zh-TW":"熟番茄 (切大塊)","en":"Ripe Tomatoes (Quartered)","fil":"Kamatis","ja":"完熟トマト（くし切り）","ko":"완숙 토마토 (큼직하게 깍둑썰기)"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Kamatis","filipinoPronunciation":"Kah-mah-tees"},{"id":"onion","name":{"zh-TW":"洋蔥 (切塊)","en":"Yellow or Red Onion (Wedges)","fil":"Sibuyas","ja":"玉ねぎ（くし切り）","ko":"양파 (큼직하게 썰기)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Sibuyas","filipinoPronunciation":"See-boo-yas"},{"id":"siling-haba","name":{"zh-TW":"長青椒 (不切斷，提供清幽椒香)","en":"Long Green Chili (Siling Haba, whole)","fil":"Siling Haba (Pansigang)","ja":"青唐辛子（シリン・ハバ、丸ごと）","ko":"풋고추/청양고추 (자르지 않고 통으로)"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Siling Haba","filipinoPronunciation":"See-leeng Hah-bah"},{"id":"patis","name":{"zh-TW":"菲律賓純魚露 (Patis)","en":"Philippine Fish Sauce (Patis)","fil":"Patis","ja":"フィリピン魚醤（パティス）","ko":"필리핀 피시소스 (파티스)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"filipinoName":"Patis","filipinoPronunciation":"Pah-tees"},{"id":"taro","name":{"zh-TW":"小芋頭 (去皮切塊，煮至融化使湯汁微稠)","en":"Small Taro Root / Gabi (Quartered to thicken broth)","fil":"Gabi (Bahagyang pampalapot)","ja":"サトイモ（タロイモ、スープにとろみをつける）","ko":"토란 (국물을 걸쭉하게 만드는 비결)"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Gabi","filipinoPronunciation":"Gah-bee"},{"id":"water","name":{"zh-TW":"淘米水或清水 (淘米水能增添米香甘醇)","en":"Rice-washing water or plain water","fil":"Hugas-bigas o Tubig","ja":"米のとぎ汁または水","ko":"쌀뜨물 또는 물"},"amount":1200,"unitMetric":"ml","unitUS":"5 cups","filipinoName":"Hugas-bigas","filipinoPronunciation":"Hoo-gahs Bee-gahs"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"水煮排骨去血水並慢燉清湯","en":"Boil Ribs, Skim Scum & Simmer Base Broth","fil":"Pakuluan ang Karne at Tanggalin ang Bula","ja":"排骨（リブ）を茹でアクを取り出汁をとる","ko":"갈비를 끓여 불순물을 걷어내고 육수 내기"},"instruction":{"zh-TW":"將排骨放入大湯鍋中，倒入 1200ml 淘米水或清水。大火煮滾後，用湯勺徹底撇去浮沫直到湯水澄清。放入切塊洋蔥、切瓣番茄與去皮芋頭塊，轉小火加蓋慢燉 30-35 分鐘，直到排骨軟嫩、芋頭表面微化。","en":"Place pork ribs into a large pot with 1200ml rice wash or water. Bring to a rapid boil, continuously skimming off all brown foam and scum for a pristine broth. Add chopped onions, tomatoes, and taro pieces. Lower heat to gentle simmer, cover, and cook 30-35 mins until pork is tender and taro begins to soften.","fil":"Pakuluan ang buto-buto sa tubig o hugas-bigas. Tanggalin ang bula. Ilagay ang sibuyas, kamatis, at gabi. Takpan at pakuluan nang 30-35 minuto.","ja":"鍋に排骨と米のとぎ汁（または水）を入れ強火にかけます。アクを丁寧にすくい取り、玉ねぎ、トマト、サトイモを加えます。弱火にしてフタをし、肉が柔らかくなるまで30〜35分煮ます。","ko":"냄비에 갈비와 쌀뜨물을 붓고 센 불에 끓입니다. 떠오르는 거품을 말끔히 걷어낸 뒤 양파, 토마토, 토란을 넣고 약불에서 30~35분간 뭉근하게 끓여줍니다."},"durationSeconds":2100,"image":"/images/ph/sinigang-step1.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Soup Mode (High Pressure) for 18 mins","instructionOverride":{"zh-TW":"壓力鍋模式：將排骨、清水、番茄、洋蔥與芋頭全放入內膽，蓋緊閥門選 Soup 高壓 18 分鐘，自然洩壓 10 分鐘。開蓋後排骨肉已入口即化，芋頭融化起沙！","en":"Instant Pot Variation: Put ribs, water, tomatoes, onions, and taro into inner pot. Cook on High Pressure (Soup setting) for 18 mins, then 10 mins natural pressure release. Tender ribs and creamy broth in record time!","fil":"Instant Pot: Ilagay ang karne, tubig, kamatis, sibuyas, at gabi. I-set sa High Pressure nang 18 minuto.","ja":"電気圧力鍋設定：肉、水、トマト、玉ねぎ、サトイモを入れ高圧で18分加圧調理。10分蒸らして減圧します。肉がホロホロになります。","ko":"인스턴트팟 설정: 고기, 물, 토마토, 양파, 토란을 넣고 고압(Soup)으로 18분 조리 후 10분 자연 감압합니다."}}]},{"stepNumber":2,"title":{"zh-TW":"加入白蘿蔔與長青椒燉煮","en":"Add Daikon Radish & Green Chilies","fil":"Ilagay ang Labanos at Siling Haba","ja":"大根と青唐辛子を加えて煮る","ko":"무와 통 풋고추를 넣고 익히기"},"instruction":{"zh-TW":"加入切片白蘿蔔和整條完整的長青椒（Siling Haba）。調入 2 大匙魚露（Patis）。繼續加蓋燉煮 6-8 分鐘，直到白蘿蔔呈現半透明清亮熟透。","en":"Add the sliced radish and whole long green chilies (keep whole so they perfume the broth without overwhelming spicy heat). Season with 2 tbsp fish sauce (Patis). Simmer 6-8 mins until daikon is translucent.","fil":"Ihalo ang labanos, siling haba, at patis. Pakuluan nang 6-8 minuto hanggang lumambot ang labanos.","ja":"大根、丸ごとの青唐辛子（切らないことで香りのみを移す）、魚醤大さじ2を加えます。フタをして大根が透き通るまで6〜8分煮ます。","ko":"무와 통 풋고추(자르지 않아야 맵지 않고 향긋함), 피시소스 2큰술을 넣고 무가 투명해질 때까지 6~8분간 더 끓입니다."},"durationSeconds":480,"image":"/images/ph/sinigang-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"下羅望子酸湯粉，調出黃金酸度","en":"Stir in Tamarind Base & Adjust Tartness","fil":"Ihalo ang Sinigang sa Sampalok Mix","ja":"タマリンドの素を加え酸味のバランスを整える","ko":"타마린드 파우더를 넣고 황금 산미 맞추기"},"instruction":{"zh-TW":"轉中大火，撒入羅望子酸湯粉（可依個人嗜酸程度分次添加），攪拌至完全融化。試嚐湯頭，應當呈現明亮醒腦、令人生津的天然果酸與肉湯旨味交織。","en":"Turn heat up to medium-high. Gradually pour in the tamarind soup mix, stirring well until fully dissolved. Taste the broth—it should hit you with a bright, mouth-watering, punchy tartness balanced by savory pork broth.","fil":"Ibuhos ang sampalok mix habang hinahalo. Tikman ang sabaw kung sapat na ang asim.","ja":"火を強め、タマリンドの素を少しずつ加えながら溶かします。スープを味見し、キュッと心地よい果実の酸味と旨味が調和しているか確認します。","ko":"불을 올리고 타마린드 믹스를 골고루 풀어 넣습니다. 입안 가득 침이 고이는 상쾌한 산미가 퍼지도록 간을 조절합니다."},"durationSeconds":120,"image":"/images/ph/sinigang-step3.jpg"},{"stepNumber":4,"title":{"zh-TW":"下鮮嫩空心菜，關火餘溫燙熟","en":"Add Fresh Kangkong & Kill Heat to Wilt","fil":"Ilagay ang Kangkong at Patayin ang Apoy","ja":"空芯菜を入れ、余熱でサッと火を通す","ko":"신선한 공심채를 넣고 불을 끄고 잔열로 익히기"},"instruction":{"zh-TW":"將洗淨摘好的空心菜全部放入滾湯中，用勺子輕輕壓入湯內，立即關火！蓋上鍋蓋燜 1 分鐘，利用湯頭餘溫將空心菜燙至翠綠脆嫩。趁熱大碗盛出，附上一小碟純魚露加碎辣椒供蘸排骨！","en":"Submerge the fresh water spinach (kangkong) into the bubbling soup, then IMMEDIATELY turn off the burner! Cover pot and let sit for 1 minute so greens wilt into brilliant crisp emerald green. Serve piping hot with extra fish sauce and chili on the side!","fil":"Ilubog ang kangkong sa sabaw at patayin AGAD ang apoy. Takpan nang 1 minuto bago ihain kasama ng patis at sili.","ja":"空芯菜を熱いスープに沈めたら【即座に火を止めます！】。フタをして1分蒸らし、シャキシャキの鮮やかな緑色に仕上げます。小皿の魚醤と唐辛子を添えて熱々をどうぞ！","ko":"공심채를 국물에 밀어 넣은 뒤 【즉시 불을 끕니다!】 뚜껑을 덮고 1분간 잔열로 숨을 죽여 아삭하고 푸른빛을 살립니다. 피시소스와 고추를 곁들여 완성합니다."},"durationSeconds":90,"image":"/images/ph/sinigang-step4.jpg","crucialTips":{"zh-TW":"空心菜切忌在滾沸火上久煮，否則會發黑變軟爛失去靈魂！關火餘溫浸熟才能保持青翠爽脆。","en":"Never boil kangkong over high heat or it turns brown and slimy. Residual heat wilts it to perfect tenderness.","fil":"Huwag pakuluan ang kangkong nang matagal para hindi mangitim.","ja":"空芯菜は煮込みすぎると黒ずんでドロドロになります。火を止めた後の余熱調理が最大のコツです。","ko":"공심채는 펄펄 끓는 불에서 오래 익히면 까맣게 변하고 물러집니다. 불을 끄고 잔열로 익혀야 합니다."}}],"troubleshooting":[{"id":"too-sour","problem":{"zh-TW":"羅望子粉加太多，湯頭過酸令人皺眉","en":"Broth is overpoweringly sour","fil":"Masyadong maasim ang sabaw","ja":"酸味が強すぎて酸っぱすぎる","ko":"수프가 너무 셔서 먹기 부담스러움"},"cause":{"zh-TW":"一次性倒入整大包酸湯粉，水量不足","en":"Poured entire packet at once or evaporated too much water","fil":"Napasobra ang lagay ng sinigang mix","ja":"粉末を一度に入れすぎたか、水分が蒸発しすぎたため","ko":"믹스를 한 번에 너무 많이 넣었거나 물이 졸아듦"},"solution":{"zh-TW":"加入半碗熱開水或清水稀釋，並多放兩片白蘿蔔或半顆熟番茄，微煮 3 分鐘即可平衡酸度。","en":"Add 1/2 cup hot water, along with extra tomato wedges or daikon slices to balance the acidity.","fil":"Magdagdag ng kaunting mainit na tubig o dagdag na kamatis.","ja":"お湯を半カップ足し、トマトや大根を少し加えて3分ほど弱火で煮ると酸味が落ち着きます。","ko":"따뜻한 물 반 컵을 붓고 토마토를 반 개 더 넣어 3분간 끓여주면 산미가 부드러워집니다."}}],"proTips":[{"zh-TW":"【淘米水魔法】：煮菲律賓酸湯強烈推薦使用洗米時的第二遍「淘米水（Hugas-bigas）」代替清水，天然澱粉能讓湯體更溫潤甘滑，與羅望子酸味完美融合！","en":"Pro Tip: Using \"Hugas-bigas\" (the second rinse water from washing your rice) creates an authentic silky body that binds the tamarind tartness to the pork fat.","fil":"Tip ng Kusinero: Gamitin ang ikalawang hugas-bigas bilang sabaw upang maging malinamnam at malapot ang sabaw.","ja":"秘伝の技：水のかわりに米の2番目の研ぎ汁を使うと、でんぷんが酸味の角を丸め、極上のまろやかさを生み出します。","ko":"비법: 쌀을 씻은 두 번째 쌀뜨물을 육수로 사용하면 전분질이 타마린드의 산미를 감싸주어 한층 부드럽고 깊은 맛이 납니다."}]},{"country":"ph","id":"lumpia-shanghai","slug":"lumpia-shanghai","title":{"zh-TW":"正宗酥脆菲式炸春捲 (Lumpia Shanghai)","en":"Crispy Filipino Spring Rolls (Lumpia Shanghai)","fil":"Lumpia Shanghai (Malutong na Paborito)","ja":"サクサク本場ルンピア（フィリピン風一口揚げ春巻き）","ko":"바삭한 필리핀식 튀김 춘권 룸피아 상하이"},"subtitle":{"zh-TW":"家庭慶典秒殺第一名・皮脆如紙爆汁肉餡・酸甜辣醬絕佳拍檔","en":"Fiesta Crowdfavorite: Ultra-Thin Shatteringly Crisp Skin, Juicy Pork Filling & Sweet Chili Dip","fil":"Laging nauubos sa handaan; napakaraming sahog at sobrang lutong","ja":"パーティーで真っ先に消える超人気フィンガーフード！薄皮パリパリの極み","ko":"필리핀 잔칫상의 부동의 인기 1위, 얇고 바삭한 피에 육즙 가득한 소"},"tagline":{"zh-TW":"一上桌瞬間被搶光的菲式聚會靈魂，氣炸鍋輕鬆做出薄脆酥香","en":"The ultimate party snack that vanishes in seconds—golden, crispy, and addictive","fil":"Ang pinakahinahanap sa bawat handaan sa Pilipinas, laging bitbit sa salo-salo","ja":"誰もが手を伸ばす黄金色のスナック。ノンフライヤーでも完璧なサクサク感","ko":"모두가 가장 먼저 손을 뻗는 파티의 주인공. 에어프라이어로도 손쉽게 완성"},"heroImage":"/images/ph/lumpia-shanghai.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":15,"defaultServings":6,"caloriesPerServing":320,"category":"streetFood","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"馬尼拉華人移民融合料理 (Binondo, Manila)","en":"Binondo, Manila (Chinatown fusion)","fil":"Binondo, Maynila (Impluwensyang Tsino)","ja":"マニラ・チャイナタウン（ビノンド）発祥","ko":"마닐라 비논도 차이나타운"},"famousStreetMarkets":[{"zh-TW":"岷倫洛老街 (Binondo, Manila)","en":"Binondo Heritage Alleys","fil":"Binondo Maynila","ja":"ビノンド中華街","ko":"비논도 차이나타운 거리"},{"zh-TW":"全菲各式家庭生日派對與 Fiesta 慶典","en":"Fiesta buffets & street fairs","fil":"Kahit saang handaan sa Pilipinas","ja":"全比フィエスタ屋台","ko":"필리핀 전역 파티 뷔페"}],"historyStory":{"zh-TW":"閩南華人移民在數百年前將潤餅（Lumpia）帶到馬尼拉，菲律賓人將其改造成細長、精緻、一口咬下爽脆爆汁的「Lumpia Shanghai」。在任何菲律賓人生日、洗禮或婚禮慶典上，若餐桌上沒有這道金黃炸春捲，派對就稱不上完整！","en":"Fujian Chinese traders brought spring rolls to Manila centuries ago. Filipinos transformed them into slender, cigar-sized rolls packed with seasoned minced pork, carrots, and aromatics. Today, no Filipino fiesta is complete without an overflowing mountain of golden Lumpia!","fil":"Dinala ng mga mangangalakal na Tsino sa Pilipinas at naging paboritong pagkain sa bawat selebrasyon tulad ng Pasko at kaarawan.","ja":"福建の移民が伝えた春巻きが、フィリピンで細身の一口サイズに進化。細かく刻んだ野菜とひき肉を極薄の皮で巻き、カリッと揚げる国民的フィンガーフードとなりました。","ko":"중국 푸젠성 상인들이 전파한 춘권이 필리핀에서 한입에 먹기 좋은 가늘고 바삭한 형태로 발전하였으며, 모든 축제와 잔치에 절대 빠지지 않습니다."},"filipinoScript":"Lumpia Shanghai na Baboy","filipinoPhonetics":"Loom-pyah Shang-high nah Bah-boy","audioPronunciationText":"Pabili po ng sampung pirasong malutong na Lumpia Shanghai!"},"ingredients":[{"id":"minced-pork","name":{"zh-TW":"豬細絞肉 (肥瘦比 2:8)","en":"Ground Pork (80% lean)","fil":"Giniling na Baboy","ja":"豚ひき肉（赤身8：脂身2）","ko":"돼지고기 다짐육 (목살/앞다리살)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Giniling na Baboy","filipinoPronunciation":"Gee-nee-leeng nang Bah-boy"},{"id":"lumpia-wrappers","name":{"zh-TW":"薄春捲皮 (超薄春捲皮)","en":"Thin Spring Roll Wrappers (Lumpia Wrappers)","fil":"Pabalat ng Lumpia","ja":"春巻きの皮（薄手）","ko":"춘권피 (얇은 것)"},"amount":25,"unitMetric":"sheet","unitUS":"sheet","isKeyFlavor":true,"filipinoName":"Pabalat ng Lumpia","filipinoPronunciation":"Pah-bah-laht nang Loom-pyah"},{"id":"carrots","name":{"zh-TW":"胡蘿蔔 (切超細碎碎丁)","en":"Carrots (Finely minced)","fil":"Karot (Pinong-pino)","ja":"人参（極細みじん切り）","ko":"당근 (매우 잘게 다짐)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Karot","filipinoPronunciation":"Kah-rot"},{"id":"onion","name":{"zh-TW":"洋蔥 (切極細丁)","en":"Yellow Onion (Finely minced)","fil":"Sibuyas","ja":"玉ねぎ（極細みじん切り）","ko":"양파 (잘게 다짐)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Sibuyas","filipinoPronunciation":"See-boo-yas"},{"id":"garlic","name":{"zh-TW":"大蒜末","en":"Garlic (Finely minced)","fil":"Bawang","ja":"にんにく（みじん切り）","ko":"다진 마늘"},"amount":4,"unitMetric":"clove","unitUS":"clove","filipinoName":"Bawang","filipinoPronunciation":"Bah-wang"},{"id":"scallions","name":{"zh-TW":"青蔥花","en":"Green Onions (Finely chopped)","fil":"Dahon ng Sibuyas","ja":"万能ねぎ（小口切り）","ko":"송송 썬 쪽파"},"amount":3,"unitMetric":"stalk","unitUS":"stalk","filipinoName":"Dahon ng Sibuyas","filipinoPronunciation":"Dah-hon nang See-boo-yas"},{"id":"egg","name":{"zh-TW":"雞蛋 (作為肉餡黏著劑)","en":"Egg (as binder for filling)","fil":"Itlog (Pang-bind)","ja":"卵（つなぎ用）","ko":"달걀 (반죽 점성용)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Itlog","filipinoPronunciation":"Eet-log"},{"id":"soy-sauce","name":{"zh-TW":"純釀造醬油","en":"Soy Sauce","fil":"Toyo","ja":"醤油","ko":"간장"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"sesame-oil","name":{"zh-TW":"純芝麻香油","en":"Sesame Oil","fil":"Mantika ng Linga","ja":"ごま油","ko":"참기름"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","filipinoName":"Linga Oil","filipinoPronunciation":"Leeng-ah Oil"},{"id":"sweet-chili-sauce","name":{"zh-TW":"甜辣醬 (沾醬必備)","en":"Sweet Chili Sauce (for dipping)","fil":"Sweet Chili Sauce","ja":"スイートチリソース（ディップ用）","ko":"스위트 칠리소스 (찍먹용)"},"amount":4,"unitMetric":"tbsp","unitUS":"4 tbsp","isKeyFlavor":true,"filipinoName":"Sweet Chili Sauce","filipinoPronunciation":"Sweet Chee-lee Sauce"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製多汁鮮香肉餡","en":"Mix Seasoned Pork Filling","fil":"Ihanda at Haluin ang Palaman","ja":"ひき肉と野菜の具材をよく混ぜる","ko":"다진 돼지고기와 채소 반죽 치대기"},"instruction":{"zh-TW":"在大碗中放入絞肉、碎胡蘿蔔、洋蔥丁、蒜末、蔥花，打入一顆雞蛋，加入醬油、芝麻香油、半茶匙鹽與黑胡椒粉。用手或筷子順著同一方向攪拌約 2 分鐘，直到肉餡起膠帶有黏性。","en":"Combine ground pork, minced carrots, onions, garlic, green onions, and egg in a bowl. Season with soy sauce, sesame oil, 1/2 tsp salt, and pepper. Mix vigorously in one direction for 2 minutes until sticky and homogenous.","fil":"Pagsamahin ang giniling na baboy, karot, sibuyas, bawang, dahon ng sibuyas, itlog, toyo, mantika ng linga, asin at paminta sa isang mangkok.","ja":"ボウルに豚ひき肉、人参、玉ねぎ、ニンニク、ネギ、卵、醤油、ごま油、塩胡椒を入れ、粘りが出るまで手早く練り合わせます。","ko":"볼에 다진 돼지고기, 당근, 양파, 마늘, 파, 달걀, 간장, 참기름, 소금 후추를 넣고 찰기가 생길 때까지 한 방향으로 치대줍니다."},"durationSeconds":180,"image":"/images/ph/lumpia-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"緊密包裹細長春捲雪茄狀","en":"Wrap into Slender Cigar Rolls","fil":"Balutin nang Mahigpit ang Lumpia","ja":"細長くきっちりと春巻きを巻く","ko":"시가 모양으로 얇고 단단하게 말기"},"instruction":{"zh-TW":"攤開一張薄春捲皮，在一側鋪上約 1.5 大匙細長條肉餡。將底邊緊緊往上翻折包裹肉餡，兩側折入，緊密向前捲成均勻的細雪茄狀。封口處抹少許水或水澱粉黏緊。用乾淨剪刀剪成約 5-6 公分一口大小長度。","en":"Lay a wrapper flat. Place 1.5 tbsp of meat filling along one edge in a thin, pencil-thick log. Roll tightly from bottom, tucking sides inward, rolling forward into a slender cigar. Dab edge with water to seal. Cut each roll into 2-3 bite-sized pieces with clean kitchen scissors.","fil":"Maglagay ng 1.5 kutsarang palaman sa pabalat. Irolyo nang mahigpit at lagyan ng kaunting tubig sa dulo para dumikit. Gupitin sa tamang haba.","ja":"春巻きの皮を広げ、手前に細長く具を置きます。空気が入らないようきつめに巻き、両端を折ってスティック状に丸め、水で糊付けします。ハサミで一口大に切り分けます。","ko":"춘권피 위에 반죽을 얇고 길게 올린 뒤 공기가 들어가지 않게 단단히 말아줍니다. 끝부분에 물을 묻혀 붙인 뒤 가위로 먹기 좋은 크기로 자릅니다."},"durationSeconds":900,"image":"/images/ph/lumpia-step2.jpg","crucialTips":{"zh-TW":"肉餡切忌包太粗，否則炸時皮焦了內部還沒熟！細長形狀能確保肉餡 3-4 分鐘內快速熟透多汁。","en":"Keep the rolls slender (pencil thickness). If rolled too thick, the outside will burn before the raw pork inside cooks through!","fil":"Huwag gawing masyadong mataba ang lumpia para maluto nang husto ang loob nang hindi nasusunog ang balat.","ja":"太く巻きすぎないこと！細身に巻くことで、短時間で中まで火が通り、外側が焦げるのを防ぎます。","ko":"너무 두껍게 말면 껍질은 타고 속은 안 익을 수 있으니, 연필 굵기로 얇고 가늘게 마는 것이 핵심입니다."}},{"stepNumber":3,"title":{"zh-TW":"油炸至金黃酥脆或氣炸出鍋","en":"Deep Fry or Air Fry to Golden Crunch","fil":"Iprito sa Mainit na Mantika o Air Fryer","ja":"カリッと黄金色に揚げる（またはノンフライヤー）","ko":"황금빛으로 바삭하게 튀기기 (또는 에어프라이어)"},"instruction":{"zh-TW":"【傳統炸法】油鍋倒油燒至 175°C（筷子插入冒細密小泡），下春捲中火炸 3-4 分鐘至表面呈現均勻金黃酥脆，撈出立起瀝油。【氣炸鍋模式請參見切換】。趁熱蘸甜辣醬大口享用！","en":"Traditional Fry: Heat oil to 175°C (350°F). Deep-fry lumpia in batches for 3-4 mins until dazzling golden and crackly crisp. Drain vertically on paper towels. Serve piping hot with sweet chili sauce!","fil":"Iprito sa katamtamang lakas ng mantika nang 3-4 minuto hanggang maging ginintuang dilaw at malutong.","ja":"揚げ油を175℃に熱し、重ならないように入れて3〜4分、キツネ色になるまで揚げます。油を切ってスイートチリソースを添えます。","ko":"175도로 달군 기름에 3~4분간 노릇노릇하고 바삭하게 튀겨냅니다. 기름을 빼고 스위트 칠리소스와 함께 서빙합니다."},"durationSeconds":300,"image":"/images/ph/lumpia-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 195°C (385°F) for 8-10 mins (brush with oil)","instructionOverride":{"zh-TW":"氣炸鍋模式：將包好的春捲單層平鋪在氣炸籃中，表面刷上薄薄一層食用油。以 195°C 氣炸 8-10 分鐘，中途翻面一次，直到整根春捲金黃爆脆，零殘油超級清爽！","en":"Air Fryer Variation: Arrange lumpia in a single layer in the basket without overlapping. Brush or spray generously with cooking oil. Air fry at 195°C (385°F) for 8-10 mins, shaking basket halfway through, until shatteringly crisp!","fil":"Paraan sa Air Fryer: Pahiran ng mantika ang ibabaw. I-air fry sa 195°C nang 8-10 minuto, baligtarin sa kalahating oras.","ja":"ノンフライヤー設定：重ならないよう並べ、油をハケで全体に塗ります。195℃で8〜10分、途中で一度裏返しながらキツネ色に焼き上げます。","ko":"에어프라이어 설정: 겹치지 않게 넣고 오일을 골고루 발라줍니다. 195°C에서 8~10분간 중간에 한 번 뒤집어가며 바삭하게 튀겨냅니다."}}]}],"troubleshooting":[{"id":"wrapper-burst","problem":{"zh-TW":"春捲在油炸時外皮爆裂破洞，肉餡流出","en":"Wrappers burst open while frying","fil":"Pumutok ang pabalat habang piniprito","ja":"揚げている最中に皮が破れて中身が出てしまう","ko":"튀길 때 춘권피가 터져 내용물이 흘러나옴"},"cause":{"zh-TW":"肉餡含有過多蔬菜水分，或捲得太鬆殘留過多空氣受熱膨脹","en":"Filling was too watery or rolls were wrapped loosely with trapped air pockets","fil":"Masyadong maluwag ang pagkakabalot o may natirang hangin sa loob","ja":"具材の水分が多いか、巻き方が緩く内部の空気が膨張したため","ko":"반죽에 수분이 너무 많거나 헐겁게 말아 내부 공기가 팽창함"},"solution":{"zh-TW":"切碎的洋蔥與胡蘿蔔務必吸乾水分；包春捲時務必緊實向前捲，擠出所有空氣，封口用水徹底黏緊。","en":"Pat minced vegetables dry before mixing. Wrap firmly to expel all air pockets.","fil":"Patuyuin ang gulay at higpitan ang pagkakabalot.","ja":"野菜の水気をしっかり切り、空気が入らないようキュッと硬めに巻くのがコツです。","ko":"다진 채소의 물기를 제거하고, 공기를 빼내며 단단히 말아주세요."}}],"proTips":[{"zh-TW":"【冷凍隨吃大法】：菲律賓家庭常一次包上一百條春捲，整齊排在烤盤上冷凍定型後裝入密封袋。要吃時「無需退冰」，直接放進氣炸鍋或油鍋炸熟，是家中最完美的隨叫隨到深夜美食！","en":"Pro Freezer Hack: Filipinos make lumpia in batches of 100! Freeze them flat on trays, then bag them. Fry directly from frozen WITHOUT thawing for instant late-night crispy magic!","fil":"Tip sa Freezer: Pwedeng i-freeze ang hilaw na lumpia at iprito nang direkta mula sa freezer nang hindi na kailangang i-defrost.","ja":"冷凍保存の知恵：一度にたくさん巻いて冷凍庫に常備。解凍せず凍ったまま揚げるだけで、いつでも揚げたてサクサクが楽しめます！","ko":"냉동 꿀팁: 한 번에 대량으로 만들어 트레이에 얼린 뒤 지퍼백에 보관하세요. 해동 없이 냉동 상태 그대로 에어프라이어나 기름에 튀기면 언제든 완벽합니다."}]},{"country":"ph","id":"kwek-kwek","slug":"kwek-kwek","title":{"zh-TW":"街頭金黃脆皮炸鵪鶉蛋 (Kwek-Kwek & Tokneneng)","en":"Street-Style Crispy Orange Battered Quail Eggs (Kwek-Kwek)","fil":"Kwek-Kwek at Tokneneng ng Kanto","ja":"名物屋台グルメ クワクワ（揚げウズラ卵のオレンジ衣揚げ）","ko":"필리핀 국민 길거리 간식 퀘크퀘크 (주황색 옷을 입은 튀김 메추리알)"},"subtitle":{"zh-TW":"馬尼拉街頭手推車第一霸主・天然胭脂樹橙色脆殼・辛辣洋蔥蒜醋蘸醬","en":"The #1 Philippine Street Cart Snack: Neon Orange Annatto Batter, Crispy Shell & Spiced Sinamak Vinegar","fil":"Pambansang merienda sa kanto na isinasawsaw sa maanghang na suka at matamis na sarsa","ja":"マニラの街角で必ず出会う鮮やかなオレンジ色の屋台フード！特製スパイシー酢で","ko":"마닐라 노점 어디서나 볼 수 있는 주황빛 바삭한 튀김옷과 매콤새콤 식초 소스"},"tagline":{"zh-TW":"每一支竹籤串起 4 顆滾燙金黃小蛋，放進老爹特調醬汁大罐浸透才是精髓","en":"Crispy outside, tender egg inside—the quintessential Philippine street food ritual","fil":"Napakasarap tuhugin at isawsaw sa baso ng masarap na sukang may sili at sibuyas","ja":"外はサクサク中はホクホク！甘辛ソースと辛口酢のダブルディップが現地流","ko":"겉은 크런치하고 속은 담백한 메추리알. 매콤한 양파 식초에 푹 찍어 먹는 묘미"},"heroImage":"/images/ph/kwek-kwek.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":10,"defaultServings":4,"caloriesPerServing":260,"category":"streetFood","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"大馬尼拉地區街頭流動小吃攤 (Manila Street Carts)","en":"Street food carts of Metro Manila","fil":"Mga Kariton ng Street Food sa Maynila","ja":"マニラ市街地の屋台街発祥","ko":"마닐라 길거리 포장마차"},"famousStreetMarkets":[{"zh-TW":"奎阿坡教堂周邊街巷","en":"Quiapo Plaza Miranda","fil":"Plaza Miranda, Quiapo","ja":"キアポ広場屋台群","ko":"퀴아포 플라자 미란다 노점"},{"zh-TW":"聖托馬斯大學周邊美食街 (UST Dapitan)","en":"UST Dapitan & Noval Student Food Street","fil":"Dapitan St., UST Maynila","ja":"サント・トマス大学前屋台通り","ko":"UST 대학가 길거리 음식 거리"}],"historyStory":{"zh-TW":"傳說 Kwek-Kwek 起源於大馬尼拉一位街邊攤販，在煮剝鵪鶉蛋時不小心弄破了蛋白，為了不浪費，便將破蛋裹上加了天然胭脂樹（Atsuete）紅木橙色麵糊下油鍋炸得酥脆，意外創造出風靡全菲半個世紀的「Kwek-Kwek」（若是用大顆雞蛋裹粉炸，則被稱為 Tokneneng）！","en":"Legend has it that a Manila street hawker accidentally dropped peeled boiled quail eggs, damaging their whites. Not wanting to waste them, she whipped up a quick tempura-style batter tinted vibrant sunset orange with annatto (atsuete) seeds and deep-fried them. The name mimics bird chirping (\"kwek-kwek\")! (When made with regular chicken eggs, it is called \"Tokneneng\".)","fil":"Ayon sa kwento, nagsimula ito nang aksidenteng mapunit ang puti ng itlog ng pugo ng isang tindera, kaya binalot niya ito sa kulay kahel na harina gamit ang atsuete at ipinirito. Kapag itlog ng manok ang gamit, tinatawag itong Tokneneng.","ja":"マニラの屋台店主が茹で卵の白身を崩してしまい、無駄にしないようアチュエテでオレンジ色に着色した衣をまとわせて揚げたのが始まりとされています。大きな鶏卵で作るものは「トクネネン」と呼ばれます。","ko":"마닐라의 한 노점상이 껍질을 벗기다 깨진 메추리알을 버리지 않고 아나토 천연 색소를 넣은 주황색 튀김옷에 튀겨 팔기 시작하면서 탄생했습니다. 달걀로 만든 것은 \"톡네넹\"이라 부릅니다."},"filipinoScript":"Kwek-Kwek at Tokneneng","filipinoPhonetics":"Kwek Kwek aht Tok-neh-neng","audioPronunciationText":"Manong, pabili pong sampung kwek-kwek, pakilagyan ng maraming suka!"},"ingredients":[{"id":"quail-eggs","name":{"zh-TW":"鵪鶉蛋 (水煮熟、剝殼洗淨瀝乾)","en":"Quail Eggs (Hard-boiled & peeled)","fil":"Itlog ng Pugo (Nilaga at binalatan)","ja":"ウズラの卵（固茹でして殻を剥く）","ko":"메추리알 (완숙으로 삶아 껍질을 벗김)"},"amount":20,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Itlog ng Pugo","filipinoPronunciation":"Eet-log nang Poo-goh"},{"id":"flour","name":{"zh-TW":"中筋麵粉","en":"All-Purpose Flour","fil":"Harina","ja":"薄力粉または中力粉","ko":"중력분 밀가루"},"amount":120,"unitMetric":"g","unitUS":"1 cup","filipinoName":"Harina","filipinoPronunciation":"Hah-ree-nah"},{"id":"cornstarch","name":{"zh-TW":"玉米澱粉 (使炸皮薄脆硬挺不回軟)","en":"Cornstarch (for shatteringly crisp shell)","fil":"Cornstarch","ja":"コーンスターチ（カリカリの秘訣）","ko":"옥수수 전분 (바삭한 식감용)"},"amount":30,"unitMetric":"g","unitUS":"0.25 cup","isKeyFlavor":true,"filipinoName":"Cornstarch","filipinoPronunciation":"Corn-starch"},{"id":"annatto-powder","name":{"zh-TW":"胭脂樹紅木籽粉 (Atsuete Powder) 或天然橙色素","en":"Annatto Powder (Atsuete) or Food Color","fil":"Atsuete Powder","ja":"アチュエテ粉末（紅木天然着色）","ko":"아추에테 파우더 (아나토 천연 오렌지 파우더)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","isKeyFlavor":true,"filipinoName":"Atsuete","filipinoPronunciation":"Ah-choo-weh-teh"},{"id":"water","name":{"zh-TW":"冰水 (調麵糊必用冰水)","en":"Ice-cold Water","fil":"Malamig na Tubig","ja":"冷水","ko":"얼음물"},"amount":160,"unitMetric":"ml","unitUS":"0.67 cup","filipinoName":"Malamig na Tubig","filipinoPronunciation":"Mah-lah-meeg nah Too-beeg"},{"id":"cane-vinegar","name":{"zh-TW":"大肚婆甘蔗醋 (調製辣蒜洋蔥醋汁)","en":"Philippine Cane Vinegar (for dipping sauce)","fil":"Sukang Maasim","ja":"サトウキビ酢（つけダレ用）","ko":"사탕수수 식초 (디핑 소스용)"},"amount":100,"unitMetric":"ml","unitUS":"0.4 cup","isKeyFlavor":true,"filipinoName":"Sukang Maasim","filipinoPronunciation":"Soo-kang Mah-ah-sim"},{"id":"red-onion-minced","name":{"zh-TW":"紅洋蔥碎 (醋汁配料)","en":"Red Onion (Finely chopped for sauce)","fil":"Tinadtad na Pulang Sibuyas","ja":"刻み赤玉ねぎ","ko":"다진 적양파"},"amount":0.5,"unitMetric":"piece","unitUS":"piece","filipinoName":"Sibuyas","filipinoPronunciation":"See-boo-yas"},{"id":"chili","name":{"zh-TW":"朝天椒 (剪碎)","en":"Bird's Eye Chilies (Chopped)","fil":"Siling Labuyo","ja":"刻み唐辛子","ko":"송송 썬 고추"},"amount":3,"unitMetric":"piece","unitUS":"piece","filipinoName":"Sili","filipinoPronunciation":"See-lee"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製招牌落日橙色脆皮粉漿","en":"Whisk Vibrant Orange Annatto Batter","fil":"Gawin ang Kulay Kahel na Harina Gamit ang Atsuete","ja":"アチュエテで鮮やかなオレンジ色の衣を作る","ko":"아추에테로 화려한 주황빛 튀김 반죽 만들기"},"instruction":{"zh-TW":"碗中先用 2 大匙溫水將胭脂樹粉（Atsuete）完全化開，顯現艷麗橙紅色。加入中筋麵粉、玉米澱粉、半茶匙鹽與少許胡椒粉，緩緩倒入冰水，用打蛋器攪拌成無顆粒、稍微濃稠能掛住筷子的均勻麵糊（如同厚可麗餅粉漿質地）。","en":"Dissolve annatto powder in 2 tbsp warm water until bright orange. In a mixing bowl, combine flour, cornstarch, 1/2 tsp salt, and pepper. Gradually whisk in the orange water and ice-cold water until a smooth, velvety batter forms (pancake batter consistency).","fil":"Tunawin ang atsuete sa maligamgam na tubig. Ihalo ang harina, cornstarch, asin, at malamig na tubig hanggang maging makinis at malapot na batter.","ja":"アチュエテ粉をぬるま湯大さじ2で溶かし鮮やかに発色させます。薄力粉、コーンスターチ、塩、冷水を混ぜ、ダマのない滑らかなとろみ衣を作ります。","ko":"아추에테 파우더를 따뜻한 물 2큰술에 풀어 오렌지빛을 냅니다. 밀가루, 전분, 소금, 얼음물을 넣고 멍울 없이 부드러운 반죽을 만듭니다."},"durationSeconds":240,"image":"/images/ph/kwek-kwek-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"調製街頭神仙靈魂沾醬 (Sinamak Suka)","en":"Prepare Spiced Vinegar Dipping Sauce","fil":"Ihanda ang Maanghang na Sukang Sawsawan","ja":"屋台名物のスパイシー酢ダレを合わせる","ko":"필리핀 길거리 특제 고추 양파 식초 소스 만들기"},"instruction":{"zh-TW":"小碗中倒入 100ml 甘蔗醋，加入切碎的紅洋蔥、拍碎大蒜末、剪碎的朝天椒圈、半茶匙鹽與 1 茶匙白糖，攪拌均勻靜置 10 分鐘讓洋蔥甜味與椒香釋入醋中。這就是馬尼拉老街頭最令人魂牽夢縈的靈魂解膩沾醬！","en":"In a sauce bowl, combine cane vinegar, finely chopped red onions, minced garlic, chopped bird’s eye chilies, 1/2 tsp salt, and 1 tsp sugar. Stir and let sit 10 mins so aromatics infuse. This is the legendary Sinamak street vinegar dip!","fil":"Paghaluin ang sukang maasim, sibuyas, bawang, sili, asin, at asukal sa isang mangkok.","ja":"サトウキビ酢に刻み赤玉ねぎ、おろしニンニク、刻み唐辛子、塩、砂糖を合わせ、10分置いて風味をなじませます。","ko":"사탕수수 식초에 다진 적양파, 마늘, 고추, 소금, 설탕을 섞어 10분간 숙성시켜 매콤상큼한 시나막 식초장을 완성합니다."},"durationSeconds":180,"image":"/images/ph/kwek-kwek-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"蛋裹乾粉後均勻掛糊炸至酥脆","en":"Dredge, Dip in Orange Batter & Deep Fry","fil":"Pahiran ng Harina, Isawsaw sa Batter at Iprito","ja":"粉をまぶしてオレンジ衣を絡め、カリッと揚げる","ko":"덧가루를 묻혀 반죽에 퐁당 담근 뒤 바삭하게 튀기기"},"instruction":{"zh-TW":"【關鍵秘訣】：剝好的熟鵪鶉蛋先在乾玉米粉中滾上一層薄粉（這樣麵糊才抓得牢不脫皮！）。接著放入橙色麵糊中滾勻。油鍋燒熱至 180°C，用湯匙一粒粒舀入滾油中，中火炸約 2.5-3 分鐘，至外殼鼓起金黃硬脆，撈出瀝油。用竹籤串起 4 顆一串盛盤！","en":"CRUCIAL STEP: Lightly dust the peeled boiled quail eggs in dry cornstarch first (this ensures the wet batter clings firmly without peeling off!). Drop eggs into the orange batter. Lower into 180°C (350°F) hot oil and fry for 2.5-3 mins until the outer shell is puffy and crisp. Skewer onto bamboo sticks!","fil":"Pagulungin muna ang itlog sa tuyong cornstarch bago isawsaw sa batter. Iprito sa mainit na mantika nang 2-3 minuto hanggang lumutong.","ja":"【最重要のコツ】茹で卵にまず薄くコーンスターチ（乾粉）をまぶします（これで衣が滑り落ちなくなります）。オレンジ衣をたっぷり絡め、180℃の油で2.5〜3分カラッと揚げます。","ko":"【핵심 비법】 먼저 메추리알에 마른 전분을 살짝 묻혀줍니다 (반죽이 벗겨지지 않음). 주황색 반죽에 푹 담근 뒤 180도 기름에 2.5~3분간 바삭하게 튀겨 꼬치에 뀁니다."},"durationSeconds":180,"image":"/images/ph/kwek-kwek-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (395°F) for 6-8 mins (Spray with oil)","instructionOverride":{"zh-TW":"氣炸鍋模式：在氣炸鍋烘焙紙上噴上一層油，將裹滿橙色麵糊的鵪鶉蛋間隔擺放，表面噴食用油。以 200°C 氣炸 6-8 分鐘，外殼迅速硬化定型成脆皮，免開油鍋超方便！","en":"Air Fryer Variation: Line basket with parchment and spray with oil. Place battered eggs with spacing. Generously spray tops with cooking oil. Air fry at 200°C (395°F) for 6-8 mins until shells set crunchy and golden!","fil":"Paraan sa Air Fryer: Lagyan ng mantika ang parchment paper, ayusin ang mga itlog at i-spray ng mantika. Lutuin sa 200°C nang 6-8 minuto.","ja":"ノンフライヤー設定：バスケットにクッキングシートを敷き油をスプレーします。衣をつけた卵を並べ、上からも油を吹き付けて200℃で6〜8分加熱します。","ko":"에어프라이어 설정: 종이호일에 오일을 뿌리고 반죽을 입힌 메추리알을 얹은 뒤 위에도 오일을 충분히 뿌려 200°C에서 6~8분간 튀깁니다."}}]}],"troubleshooting":[{"id":"batter-slips-off","problem":{"zh-TW":"下油鍋後，橙色外皮脫落，露出光禿禿的蛋","en":"Batter slides off in the oil leaving bare eggs","fil":"Natatanggal ang balat ng harina habang piniprito","ja":"油に入れた瞬間に衣が剥がれ落ちてしまう","ko":"기름에 넣자마자 튀김옷이 껍질처럼 벗겨짐"},"cause":{"zh-TW":"水煮蛋表面光滑潮濕，未先拍上一層乾玉米澱粉","en":"Eggs were wet and slippery without a dry starch dusting","fil":"Basa ang itlog at walang tuyong harina bago isawsaw sa batter","ja":"卵の表面が濡れたままで、事前の打ち粉（粉まぶし）をしなかったため","ko":"메추리알 표면에 수분이 남았거나 마른 전분을 덧바르지 않아 반죽이 미끄러짐"},"solution":{"zh-TW":"熟蛋擦乾後，務必先丟在乾澱粉盤裡徹底滾勻一層白粉，再丟入濕麵糊，粉漿便如磁鐵般緊密貼合！","en":"Dry eggs completely with paper towels, dredge thoroughly in dry cornstarch, then plunge into wet batter.","fil":"Patuyuin ang itlog at balutin sa tuyong cornstarch bago isawsaw sa batter.","ja":"ペーパーで水分を拭き取り、乾いたコーンスターチを満遍なくまとわせてから衣液にくぐらせます。","ko":"물기를 닦고 마른 전분 가루를 꼼꼼히 묻힌 다음 반죽을 입혀주면 절대 벗겨지지 않습니다."}}],"proTips":[{"zh-TW":"【雙醬合壁頂級吃法】：馬尼拉街頭老饕必備秘訣——竹籤串好熱騰騰的 Kwek-Kwek，先伸進甜辣醬大罐浸裹一層甜甘，再迅速在蒜辣洋蔥白醋罐裡點蘸，酸、甜、辛、香四味在舌尖連環爆炸！","en":"Double Dip Street Hack: The authentic way to eat kwek-kwek is the \"Double Dip\"—first swirl your skewer in the sweet brown gravy, then immediately tap it in the spiced garlic vinegar for an explosion of flavors!","fil":"Tip sa Kanto: Isawsaw muna sa matamis na sarsa bago isawsaw sa maasim na suka para sa perpektong sarap!","ja":"現地の裏ワザ：まず甘いタレに串をくぐらせ、そのあとピリ辛酢にチョンとつける「ダブルディップ」で食べると最高の味わいになります！","ko":"노점 고수의 비법: 달콤한 브라운 소스에 먼저 푹 찍은 뒤, 매콤한 고추 식초에 살짝 담가 먹는 \"더블 딥\"으로 즐기면 단짠과 산미가 폭발합니다."}]},{"country":"ph","id":"pork-bbq","slug":"pork-bbq","title":{"zh-TW":"街頭焦糖菲式炭烤豬肉串 (Filipino Pork BBQ)","en":"Street-Style Filipino Pork BBQ Skewers","fil":"Inihaw na Pork BBQ sa Kanto","ja":"本場屋台の甘辛ポークバーベキュー串（イニハウ・ナ・バボイ）","ko":"필리핀 길거리 숯불 돼지 바베큐 꼬치 (이니하우 나 바보이)"},"subtitle":{"zh-TW":"香蕉番茄醬靈魂秘汁・雪碧汽水醃漬嫩化・紅木籽油焦糖炭香油亮","en":"Glazed in Sweet Banana Ketchup, 7-Up & Garlic with Smoky Caramelized Char","fil":"Malambot at malinamnam na inihaw na may banana ketchup at kalamansi","ja":"バナナケチャップと炭酸飲料で極限まで柔らかくした魅惑のテリヤキ風BBQ","ko":"바나나 케첩과 사이다로 부드럽게 재워 숯불에 구워낸 달콤짭짤 꼬치구이"},"tagline":{"zh-TW":"路邊攤炭煙裊裊的最迷人香氣，肉質軟嫩爆汁、甜香微酸讓人一串接一串","en":"The irresistible aroma of Philippine street corners: sweet, savory, garlicky, and smoky","fil":"Paboritong pulutan at ulam sa gabi na may sawsawan na maasim na suka","ja":"夕暮れのマニラを包み込む炭火の甘い煙。冷えたビールが何杯でも進む屋台の主役","ko":"저녁 무렵 노점가를 가득 채우는 달콤하고 고소한 숯불 연기, 맥주와 영혼의 단짝"},"heroImage":"/images/ph/pork-bbq.jpg","difficulty":"easy","prepTimeMinutes":25,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":420,"category":"streetFood","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"全菲律賓街角手推車與露天燒烤排檔 (Street Inihaw Stalls)","en":"Across street corners & night stalls of the Philippines","fil":"Bawat Kanto at Palengke sa Pilipinas","ja":"フィリピン全土の街角炭火焼きスタンド","ko":"필리핀 전역 길거리 숯불 구이 노점"},"famousStreetMarkets":[{"zh-TW":"宿霧拉爾西安燒烤一條街","en":"Larsian BBQ Strip, Cebu","fil":"Larsian sa Cebu","ja":"セブ島ラルシアン通り","ko":"세부 라르시안 바베큐 골목"},{"zh-TW":"馬卡蒂波布拉辛美食巷","en":"Poblacion Night Alley, Makati","fil":"Poblacion Makati","ja":"マカティ・ポブラシオン","ko":"마카티 포블라시온 거리"}],"historyStory":{"zh-TW":"菲律賓的炭烤文化統稱為「Inihaw」。美軍進駐時期帶來了西式 BBQ 概念，但菲律賓攤販發揮無窮創意，將本地特有的香蕉番茄醬（Banana Ketchup）、甘蔗醋、大蒜、黑胡椒，以及檸檬汽水（Sprite 或 7-Up）調和成獨步全球的神秘醃肉汁。汽水中的碳酸能瞬間軟化豬肉纖維，糖分在炭火上焦糖化，造就了菲式烤串無人能抗拒的魅力！","en":"The Filipino grilling tradition is called \"Inihaw\". Street vendors invented a uniquely Pinoy marinade using local Banana Ketchup, cane vinegar, heavy garlic, and citrus soda (7-Up or Sprite). The soda acids tenderize the pork while sugars create a lacquered mahogany caramel crust over glowing charcoal!","fil":"Ang inihaw na pork BBQ ay paborito ng mga Pilipino. Ang sikreto sa lambot ay ang pagbabad sa 7-Up o Sprite at banana ketchup para sa manamis-namis na sarsa.","ja":"「イニハウ」と呼ばれる伝統の炭火焼き。屋台の店主たちが編み出した秘伝のマリネ液には、バナナケチャップやサトウキビ酢のほか、スプライト等の炭酸飲料が使われ、驚くほどの柔らかさと照りを生み出します。","ko":"필리핀식 숯불구이 \"이니하우\"의 꽃. 사이다나 7-Up의 탄산으로 고기를 극도로 연하게 만들고, 바나나 케첩과 마늘 양념으로 붉은 윤기를 내며 굽는 것이 독보적인 비법입니다."},"filipinoScript":"Inihaw na Pork Barbecue","filipinoPhonetics":"Ee-nee-haw nah Pork Bar-beh-kyoo","audioPronunciationText":"Manong, pabili pong limang tuhog ng Pork BBQ, paki-init sa uling!"},"ingredients":[{"id":"pork-shoulder-belly","name":{"zh-TW":"豬梅花肉或五花肉 (切薄長肉片)","en":"Pork Shoulder or Pork Belly (Sliced thin into ribbons)","fil":"Kasim o Liempo ng Baboy","ja":"豚肩ロースまたは豚バラ（薄切り短冊）","ko":"돼지 목살 또는 삼겹살 (얇고 길게 저민 것)"},"amount":600,"unitMetric":"g","unitUS":"1.3 lb","isKeyFlavor":true,"filipinoName":"Kasim ng Baboy","filipinoPronunciation":"Kah-seem nang Bah-boy"},{"id":"banana-ketchup","name":{"zh-TW":"菲式香蕉番茄醬 (Jufran 或 UFC)","en":"Jufran Banana Ketchup (Sweet & Tangy)","fil":"Banana Ketchup (Jufran)","ja":"バナナケチャップ（ジュフラン）","ko":"바나나 케첩 (Jufran)"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Banana Ketchup","filipinoPronunciation":"Bah-nah-nah Ketchup"},{"id":"citrus-soda","name":{"zh-TW":"雪碧或七喜汽水 (Sprite / 7-Up 軟化肉質秘密)","en":"Lemon-Lime Soda (7-Up or Sprite)","fil":"Sprite o 7-Up","ja":"スプライトまたは7-UP（炭酸飲料）","ko":"스프라이트 또는 사이다 (연육 작용)"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Sprite / 7-Up","filipinoPronunciation":"Sprite"},{"id":"soy-sauce","name":{"zh-TW":"純釀造醬油","en":"Philippine Soy Sauce (Toyo)","fil":"Toyo","ja":"フィリピン醤油","ko":"간장"},"amount":60,"unitMetric":"ml","unitUS":"0.25 cup","filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"calamansi-juice","name":{"zh-TW":"新鮮四季柑桔汁 (或檸檬汁)","en":"Fresh Calamansi Juice (or Lemon/Lime)","fil":"Katas ng Kalamansi","ja":"カラマンシー果汁（またはレモン汁）","ko":"깔라만시 즙 (또는 레몬/라임즙)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"filipinoName":"Katas ng Kalamansi","filipinoPronunciation":"Kah-tahs nang Kah-lah-mahn-see"},{"id":"brown-sugar","name":{"zh-TW":"黑糖或二砂糖","en":"Dark Brown Sugar","fil":"Pulang Asukal","ja":"黒糖","ko":"흑설탕"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Asukal","filipinoPronunciation":"Ah-soo-kal"},{"id":"garlic","name":{"zh-TW":"大蒜 (壓成蒜泥)","en":"Garlic (Finely grated or crushed)","fil":"Bawang","ja":"にんにく（すりおろし）","ko":"다진 마늘"},"amount":8,"unitMetric":"clove","unitUS":"clove","filipinoName":"Bawang","filipinoPronunciation":"Bah-wang"},{"id":"bamboo-skewers","name":{"zh-TW":"竹籤 (提前泡水 30 分鐘防烤焦)","en":"Bamboo Skewers (soaked in water 30 mins)","fil":"Tuhog na Kawayan","ja":"竹串（水に30分浸しておく）","ko":"대나무 꼬치 (물에 30분 불림)"},"amount":12,"unitMetric":"piece","unitUS":"piece","filipinoName":"Tuhog","filipinoPronunciation":"Too-hog"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"調製黃金比例秘醬醃肉","en":"Mix Soda Banana Marinade & Marinate Pork","fil":"Ibabad ang Karne sa Sprite, Ketchup at Bawang","ja":"秘伝タレを作り、肉を一晩じっくり漬け込む","ko":"사이다 바나나 양념에 고기 재우기"},"instruction":{"zh-TW":"在大碗中混合香蕉番茄醬、雪碧汽水、醬油、金桔汁、蒜泥、黑糖與 1 茶匙現磨黑胡椒。將切薄的豬肉片放入碗中徹底抓勻按摩，冷藏醃漬至少 4 小時（最好醃漬隔夜）。取出肉片前，將碗中剩餘的醃汁留下煮滾做為後續刷醬！","en":"In a large bowl, whisk together banana ketchup, Sprite, soy sauce, calamansi juice, grated garlic, brown sugar, and cracked black pepper. Add sliced pork, massage thoroughly, and marinate in the fridge for at least 4 hours (overnight preferred). Reserve leftover marinade for basting glaze!","fil":"Paghaluin ang banana ketchup, Sprite, toyo, kalamansi, bawang, asukal, at paminta. Ibabad ang karne nang hindi bababa sa 4 na oras o magdamag sa ref.","ja":"ボウルにバナナケチャップ、スプライト、醤油、カラマンシー果汁、おろしニンニク、黒糖、黒胡椒を混ぜます。肉を入れてよく揉み込み、冷蔵庫で4時間以上（一晩推奨）寝かせます。漬け汁は仕上げのタレ用に取っておきます。","ko":"볼에 바나나 케첩, 사이다, 간장, 깔라만시 즙, 다진 마늘, 흑설탕, 흑후추를 섞습니다. 얇게 썬 고기를 넣고 골고루 주물러 최소 4시간(하룻밤 권장) 재워둡니다."},"durationSeconds":14400,"image":"/images/ph/pork-bbq-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"串肉並慢熬濃稠焦糖刷醬","en":"Thread onto Skewers & Simmer Basting Glaze","fil":"Tuhugin ang Karne at Lutuin ang Pamahid","ja":"肉を串に波打たせて刺し、ハケ塗りタレを煮詰める","ko":"꼬치에 고기를 꿰고 바를 소스 졸이기"},"instruction":{"zh-TW":"將泡透水的竹籤以「S型波浪摺疊方式」穿入肉片，肥瘦相間，每串約穿 4-5 折。將剩餘的醃肉汁倒入小鍋中，加 1 大匙油與少許黑糖，小火慢熬 3-4 分鐘至濃稠有光澤，做為烤肉時的厚刷醬。","en":"Thread meat onto pre-soaked bamboo skewers like an accordion (ribbon style), interleaving lean and fat. Pour leftover marinade into a small saucepan with 1 tbsp oil, simmer for 3-4 mins until reduced into a thick glossy glaze for brushing.","fil":"Ituhog ang karne sa kawayan nang pa-alon. Pakuluan ang natirang pinagbabaran kasama ang kaunting mantika para gawing pamahid.","ja":"水に浸した竹串に、肉をアコーディオン状に波打たせて刺します。残った漬けダレに油大さじ1を加え、小鍋で3〜4分煮詰めてツヤのある塗りタレを作ります。","ko":"물에 불린 꼬치에 고기를 물결 모양으로 주름잡아 꿰어줍니다. 남은 양념에 기름 1큰술을 넣고 냄비에 3~4분간 졸여 발라줄 글레이즈 소스를 만듭니다."},"durationSeconds":300,"image":"/images/ph/pork-bbq-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"炭火翻烤或氣炸，多遍厚刷醬汁出爐","en":"Grill over Coals or Air Fry, Basting Constantly","fil":"Ihawin sa Uling o Air Fryer at Pahiran ng Sarsa","ja":"炭火またはノンフライヤーで焼き、タレを重ね塗りする","ko":"숯불 또는 에어프라이어에 구우며 소스 덧바르기"},"instruction":{"zh-TW":"【炭火烤架法】置於紅熱木炭烤架上，每面烤 3-4 分鐘。翻面時厚厚刷上濃縮香蕉醬汁，翻烤 3-4 次，直到肉邊緣帶有迷人的微焦炭斑（約 10-12 分鐘）。【氣炸鍋模式請參見切換】。趁熱蘸蒜辣洋蔥白醋開動！","en":"Traditional Grill: Cook over glowing coals for 3-4 mins per side. Continually brush generously with the sweet basting glaze every time you flip, grilling 10-12 mins total until beautifully charred on the edges. Serve hot with spiced garlic vinegar dip!","fil":"Ihawin sa uling nang 3-4 minuto bawat gilid. Pahiran nang paulit-ulit ng sarsa hanggang magkaroon ng sunog-sunog na gilid. Isawsaw sa suka!","ja":"炭火で両面を3〜4分ずつ焼き、裏返すたびに刷毛でタレをたっぷり塗り重ねます。縁に香ばしい焦げ目がついたら完成。ピリ辛酢ダレをつけて熱々を頬張ります！","ko":"숯불에 앞뒤로 3~4분씩 굽고 뒤집을 때마다 소스를 듬뿍 덧발라 가장자리가 살짝 그을릴 때까지 10~12분간 구워냅니다. 매콤한 고추 식초에 찍어 먹습니다."},"durationSeconds":600,"image":"/images/ph/pork-bbq-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (395°F) for 10-12 mins (flip & baste at 6 mins)","instructionOverride":{"zh-TW":"氣炸鍋模式：將串好的肉串放入氣炸籃（若竹籤過長可剪短），以 200°C 烤 6 分鐘。取出翻面並厚厚刷上一層焦糖刷醬，繼續氣炸 4-5 分鐘，表面起微焦糖化紅斑，肉汁四溢！","en":"Air Fryer Variation: Place skewers in basket (trim sticks if needed). Air fry at 200°C (395°F) for 6 mins. Open basket, flip, brush generously with basting glaze, and air fry for another 4-5 mins until beautifully caramelized and sizzling.","fil":"Paraan sa Air Fryer: I-air fry sa 200°C nang 6 minuto, baligtarin, pahiran ng sarsa at lutuin pa nang 4-5 minuto.","ja":"ノンフライヤー設定：バスケットに並べ200℃で6分加熱。裏返してタレをたっぷり塗り、さらに4〜5分香ばしく焼き上げます。","ko":"에어프라이어 설정: 200°C에서 6분간 구운 뒤 뒤집어 글레이즈 소스를 듬뿍 바르고 4~5분간 더 구워 노릇한 캐러멜 크러스트를 완성합니다."}}]}],"troubleshooting":[{"id":"meat-too-tough","problem":{"zh-TW":"烤肉串吃起來肉質乾柴發硬","en":"Meat is dry, tough, and chewy","fil":"Matigas at tuyo ang karne","ja":"肉がパサついて固くなってしまった","ko":"고기가 퍽퍽하고 질김"},"cause":{"zh-TW":"醃漬時間過短，未加汽水，或使用了全瘦肉且烤太久","en":"Skipped the soda, marinated less than 2 hours, or used lean pork","fil":"Kulang sa babad o walang taba ang karne","ja":"炭酸水を使わなかったか、漬け込み時間が短すぎたため","ko":"사이다를 넣지 않았거나 재우는 시간이 너무 짧았음"},"solution":{"zh-TW":"務必選用帶有少許油脂的梅花肉（Kasim），加入雪碧汽水至少冷藏醃漬 4 小時以上，碳酸與果酸會讓肉質入口柔嫩多汁！","en":"Always use pork shoulder with marbling. Let the carbonation and calamansi acid break down muscle fibers for at least 4 hours.","fil":"Gumamit ng kasim na may kaunting taba at ibabad nang matagal sa Sprite.","ja":"適度に脂の乗った豚肩ロースを使い、スプライト入りのタレに4時間以上漬け込むことで劇的に柔らかくなります。","ko":"지방이 적당한 목살 부위를 사용하고, 사이다 양념에 최소 4시간 이상 충분히 재워주세요."}}],"proTips":[{"zh-TW":"【竹籤泡水救命指南】：竹籤在穿肉前務必在冷水中浸泡至少 30 分鐘，吸飽水分的竹子在高溫炭火或氣炸鍋中才不會被直接燒斷炭化！","en":"Never Skip Soaking: Always soak wooden skewers in water for 30 minutes before threading meat. Waterlogged bamboo will never catch fire or snap on hot grates!","fil":"Huwag kalimutang ibabad ang tuhog sa tubig nang 30 minuto para hindi masunog sa ihawan.","ja":"竹串の水漬けは必須：串を水に30分浸しておくだけで、炭火やノンフライヤーで串が燃えたり折れたりするのを防げます。","ko":"대나무 꼬치는 고기를 꿰기 전 반드시 찬물에 30분 이상 불려두어야 숯불이나 에어프라이어에서 타지 않습니다."}]},{"country":"ph","id":"chicken-inasal","slug":"chicken-inasal","title":{"zh-TW":"巴科洛德香茅烤雞 (Chicken Inasal)","en":"Bacolod Chicken Inasal (Lemongrass Calamansi Roast)","fil":"Inasal na Manok ng Bacolod","ja":"バコロド名物チキン・イナサル（レモングラス香る黄金炭火焼き鶏）","ko":"바콜로드 치킨 이나살 (레몬그라스 깔라만시 황금 숯불 통닭)"},"subtitle":{"zh-TW":"微笑之都巴科洛德神作・新鮮香茅四季柑・紅木雞油蒜香飯靈魂天花板","en":"City of Smiles Legend: Fresh Lemongrass, Calamansi, Sinamak & Golden Annatto Chicken Oil","fil":"Sikat na inihaw na manok mula sa Negros na may tanglad at dilaw na mantika","ja":"ネグロス島バコロドの至宝！アチュエテ鶏油をかけたガーリックライスと共に","ko":"레몬그라스와 깔라만시로 숙성해 아추에테 치킨 오일 밥과 함께 먹는 전설의 통닭"},"tagline":{"zh-TW":"菲律賓烤雞的極致巔峰，酸香草本直擊靈魂，金黃紅木雞油拌飯百吃不厭","en":"The crowned king of Philippine roast chicken: citrusy, herbal, smoky, and golden","fil":"Ang pambansang paboritong inihaw na manok na laging may kasamang unli-rice at chicken oil","ja":"爽快なハーブの酸味とスモーキーな皮。黄金のチキンオイルご飯との相性は異次元","ko":"새콤한 허브 향과 숯불 향의 환상적인 조화, 황금빛 치킨 오일 밥과 무한 흡입"},"heroImage":"/images/ph/chicken-inasal.jpg","difficulty":"medium","prepTimeMinutes":25,"cookTimeMinutes":30,"defaultServings":4,"caloriesPerServing":450,"category":"mains","dietaryTags":["classic","halal","glutenFree"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"西內格羅省・微笑之都巴科洛德 (Bacolod City, Western Visayas)","en":"Bacolod City, Negros Occidental (City of Smiles)","fil":"Lungsod ng Bacolod, Negros Occidental","ja":"ネグロス島バコロド市","ko":"바콜로드 시티 (네그로스 옥시덴탈)"},"famousStreetMarkets":[{"zh-TW":"巴科洛德 Manokan Country 烤雞一條街","en":"Manokan Country Open-Air Strip, Bacolod","fil":"Manokan Country sa Bacolod","ja":"バコロド・マノカンカントリー屋台街","ko":"바콜로드 마노칸 컨트리 야외 식당가"},{"zh-TW":"馬尼拉各大 Inasal 炭烤餐館","en":"Metro Manila Inasal Houses","fil":"Mga Inasal Stalls sa Maynila","ja":"マニラ各所のイナサル専門店","ko":"마닐라 이나살 전문점 거리"}],"historyStory":{"zh-TW":"Inasal 源自怡朗與巴科洛德的希利蓋農語（Hiligaynon），意為「炭火炙烤」。不同於美式甜烤雞，正宗 Inasal 不加糖，而是使用大量新鮮香茅、生薑、大蒜、四季桔汁與椰子白醋醃漬。在炙烤時，不斷刷上以雞脂肪和紅木籽（Atsuete）熬出的「黃金紅木雞油（Chicken Oil）」，烤出落日般燦爛油亮的脆皮！","en":"Inasal means \"cooked over charcoal\" in Hiligaynon. Unlike sweet barbecue, Bacolod Inasal is decidedly tangy and aromatic—marinated in bruised lemongrass stalks, calamansi, ginger, and coconut vinegar. While grilling, it is continually basted with rendered chicken fat infused with annatto seeds (Chicken Oil), giving it that legendary golden sunset sheen!","fil":"Galing sa salitang Hiligaynon na ang ibig sabihin ay inihaw sa baga. Pinasikat sa Manokan Country sa Bacolod gamit ang tanglad, luya, kalamansi, at ang tanyag na dilaw na chicken oil.","ja":"バコロドの方言で「炭火焼き」を意味するイナサル。甘いBBQとは一線を画し、レモングラス、生姜、カラマンシー、ココナッツ酢で漬け込みます。アチュエテで黄金色にした鶏油をハケで塗りながら焼き上げるのが伝統です。","ko":"힐리가이논 어로 \"숯불에 굽다\"라는 뜻. 달지 않고 레몬그라스, 생강, 깔라만시, 식초의 상쾌한 향이 닭고기에 깊숙이 배어들며, 아추에테 치킨 오일을 덧발라가며 구워냅니다."},"filipinoScript":"Inasal na Manok ng Bacolod","filipinoPhonetics":"Ee-nah-sal nah Mah-nok nang Bah-koh-lod","audioPronunciationText":"Isang Pecho-Pak po na Inasal at may extra chicken oil sa kanin!"},"ingredients":[{"id":"chicken-quarters","name":{"zh-TW":"全雞腿連骨帶大腿 (Chicken Leg Quarters)","en":"Chicken Leg Quarters or Bone-in Thighs","fil":"Paa at Hita ng Manok (Paa-Pak)","ja":"骨付きチキンレッグ（モモ＆サイ）","ko":"장각 (넓적다리가 붙은 통닭다리)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Hita at Paa ng Manok","filipinoPronunciation":"Hee-tah aht Pah-ah nang Mah-nok"},{"id":"lemongrass","name":{"zh-TW":"新鮮香茅 (拍扁切碎，香氣靈魂)","en":"Fresh Lemongrass (Bruised & finely minced)","fil":"Sariwang Tanglad","ja":"生レモングラス（根元を叩いて刻む）","ko":"신선한 레몬그라스 (칼등으로 으깬 뒤 다짐)"},"amount":3,"unitMetric":"stalk","unitUS":"stalk","isKeyFlavor":true,"filipinoName":"Tanglad","filipinoPronunciation":"Tang-lad"},{"id":"ginger","name":{"zh-TW":"老薑 (去皮磨泥)","en":"Fresh Ginger (Peeled & grated)","fil":"Luya","ja":"生姜（すりおろし）","ko":"다진 생강"},"amount":30,"unitMetric":"g","unitUS":"1 oz","filipinoName":"Luya","filipinoPronunciation":"Loo-yah"},{"id":"garlic","name":{"zh-TW":"新鮮蒜末","en":"Fresh Garlic (Minced)","fil":"Bawang","ja":"にんにく（みじん切り）","ko":"다진 마늘"},"amount":8,"unitMetric":"clove","unitUS":"clove","filipinoName":"Bawang","filipinoPronunciation":"Bah-wang"},{"id":"calamansi-juice","name":{"zh-TW":"新鮮四季柑桔汁","en":"Fresh Calamansi Juice","fil":"Katas ng Kalamansi","ja":"カラマンシー生果汁","ko":"신선한 깔라만시 즙"},"amount":60,"unitMetric":"ml","unitUS":"0.25 cup","isKeyFlavor":true,"filipinoName":"Kalamansi","filipinoPronunciation":"Kah-lah-mahn-see"},{"id":"coconut-vinegar","name":{"zh-TW":"菲律賓椰子白醋或甘蔗醋","en":"Coconut Vinegar (Sukang Tuba) or Cane Vinegar","fil":"Sukang Paombong o Suka","ja":"ココナッツ天然酢またはサトウキビ酢","ko":"코코넛 식초 또는 사탕수수 식초"},"amount":60,"unitMetric":"ml","unitUS":"0.25 cup","filipinoName":"Sukang Suka","filipinoPronunciation":"Soo-kang Soo-kah"},{"id":"brown-sugar","name":{"zh-TW":"黑糖 (微量提味)","en":"Brown Sugar (a touch to balance)","fil":"Asukal na Pula","ja":"黒糖（隠し味程度）","ko":"흑설탕 (감칠맛용 소량)"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","filipinoName":"Asukal","filipinoPronunciation":"Ah-soo-kal"},{"id":"annatto-chicken-oil","name":{"zh-TW":"自製紅木雞油 (雞油炸紅木籽提取)","en":"Rendered Annatto Chicken Oil (for basting & rice)","fil":"Chicken Oil na may Atsuete","ja":"黄金アチュエテチキンオイル（ハケ塗り＆ご飯用）","ko":"아추에테 치킨 오일 (바르는 오일 & 밥 비빔용)"},"amount":80,"unitMetric":"ml","unitUS":"0.33 cup","isKeyFlavor":true,"filipinoName":"Chicken Oil","filipinoPronunciation":"Chee-ken Oil"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"草本柑橘秘汁深度醃漬雞腿","en":"Bruise Aromatics & Marinate Chicken","fil":"Ibabad ang Manok sa Tanglad, Luya at Kalamansi","ja":"ハーブと柑橘の特製ダレに鶏肉をじっくり漬け込む","ko":"허브와 깔라만시 특제 양념에 닭고기 재우기"},"instruction":{"zh-TW":"將雞腿肉厚處劃開 2 刀以便入味。在大碗中用力揉捏拍碎的香茅、生薑泥、大蒜末，釋放草本精油，加入四季柑桔汁、椰子醋、黑糖、2茶匙粗鹽與黑胡椒碎。將雞腿放入深情按摩，加蓋冷藏醃漬至少 6 小時或隔夜。","en":"Score deep slits into the thickest parts of the chicken legs. In a bowl, crush bruised lemongrass, ginger, and garlic to release botanical oils. Whisk in calamansi juice, coconut vinegar, brown sugar, 2 tsp coarse salt, and black pepper. Submerge chicken, massage well, and marinate chilled for at least 6 hours or overnight.","fil":"Hiwain nang bahagya ang laman ng manok. Pagsamahin ang tanglad, luya, bawang, kalamansi, suka, asukal, asin at paminta. Ibabad ang manok nang hindi bababa sa 6 na oras.","ja":"チキンレッグの厚い部分に隠し包丁を入れます。叩いたレモングラス、生姜、ニンニク、カラマンシー果汁、ココナッツ酢、塩胡椒を揉み込み、冷蔵庫で6時間以上漬け込みます。","ko":"닭다리 살이 두꺼운 부위에 칼집을 냅니다. 으깬 레몬그라스, 생강, 마늘, 깔라만시 즙, 식초, 설탕, 소금, 후추를 섞어 닭고기에 버무린 뒤 냉장고에 6시간 이상 재웁니다."},"durationSeconds":21600,"image":"/images/ph/chicken-inasal-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"熬製落日金黃「紅木蒜香雞油」","en":"Render Golden Annatto Chicken Basting Oil","fil":"Gawin ang Dilaw na Mantika (Chicken Oil)","ja":"黄金の「アチュエテチキンオイル」を煮出す","ko":"황금빛 아추에테 치킨 오일 만들기"},"instruction":{"zh-TW":"小鍋中放入雞皮/雞肥油（或植物油加黃油 80ml），放入 2 大匙紅木籽（Atsuete）與 3 瓣拍扁蒜頭。用極小火慢煸 5-6 分鐘，直到油脂被染成無比燦爛的落日橘紅色，過濾掉紅木籽備用。此油就是 Inasal 焦脆外皮與拌飯的萬能神油！","en":"In a small saucepan, gently warm 80ml chicken fat/oil with 2 tbsp annatto seeds (atsuete) and 3 crushed garlic cloves over low heat for 5-6 mins until glowing sunset orange. Strain out the seeds. This liquid gold is the secret to the crispy glaze and famous garlic rice!","fil":"Painitin ang mantika o taba ng manok kasama ang atsuete at bawang sa mahinang apoy nang 5-6 minuto hanggang maging kulay kahel. Salain.","ja":"小鍋に鶏油（またはサラダ油とバター）80ml、アチュエテシード大さじ2、潰しニンニクを入れ、極弱火で5分熱して鮮やかなオレンジ色を抽出します。種を濾して完成。","ko":"작은 냄비에 닭기름(또는 식용유와 버터) 80ml, 아추에테 씨앗 2큰술, 마늘을 넣고 약불에서 5~6분간 끓여 붉은 오렌지빛 기름을 우려낸 뒤 체에 걸러줍니다."},"durationSeconds":360,"image":"/images/ph/chicken-inasal-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"炭火炙烤或氣炸，反覆厚刷雞油","en":"Grill over Charcoal or Air Fry, Basting with Chicken Oil","fil":"Ihawin sa Uling o Air Fryer at Pahiran ng Chicken Oil","ja":"炭火またはノンフライヤーで焼き、チキンオイルを塗り重ねる","ko":"숯불 또는 에어프라이어에 구우며 치킨 오일 덧바르기"},"instruction":{"zh-TW":"【炭火烤爐法】將雞腿放上木炭烤網中火烤，每 4-5 分鐘翻面一次，每次翻面都用毛刷厚厚塗抹自製紅木雞油。烤約 20-25 分鐘至骨邊肉熟透、外皮焦香金黃。【氣炸鍋模式請參見切換】。盛盤配上大蒜飯，淋上雞油與金桔辣椒醬油！","en":"Grill over medium coals, turning every 4-5 mins. Continually baste generously with the golden annatto chicken oil every single flip! Grill 20-25 mins until juices run clear and skin is blistering crisp. Serve over Sinangag (garlic rice), drizzling extra chicken oil and toyomansi on top!","fil":"Ihawin sa uling nang 20-25 minuto. Pahiran ng chicken oil sa bawat pagbaligtad hanggang maluto nang husto at lumutong ang balat.","ja":"炭火にのせ、4〜5分ごとに返しながらアチュエテチキンオイルを贅沢に塗り重ねます。20〜25分で中まで火を通し皮をパリッと焼き上げます。ガーリックライスにチキンオイルを垂らして豪快に！","ko":"중간 불의 숯불에 얹어 4~5분마다 뒤집으며 아추에테 치킨 오일을 듬뿍 발라줍니다. 20~25분간 속까지 완벽히 익히고 껍질을 바삭하게 굽습니다. 마늘밥 위에 치킨 오일을 뿌려 함께 즐기세요."},"durationSeconds":1500,"image":"/images/ph/chicken-inasal-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 190°C (375°F) for 22-25 mins (brush with chicken oil)","instructionOverride":{"zh-TW":"氣炸鍋模式：將雞腿皮朝上放入氣炸籃，表面刷滿紅木雞油。以 190°C 氣炸 12 分鐘，翻面刷油氣炸 8 分鐘，最後翻回雞皮朝上刷油以 200°C 氣炸 3 分鐘，烤出無比金黃爆脆的極致脆皮！","en":"Air Fryer Variation: Place chicken leg skin-side UP into basket. Brush generously with annatto chicken oil. Air fry at 190°C (375°F) for 12 mins. Flip, brush oil, air fry 8 mins. Flip skin-side back UP, brush extra oil, and crisp at 200°C (395°F) for 3 mins until blistered and golden!","fil":"Paraan sa Air Fryer: Ilagay ang manok sa 190°C nang 12 minuto, baligtarin at pahiran ng mantika nang 8 minuto, ibalik ang balat sa itaas at i-200°C nang 3 minuto para lumutong.","ja":"ノンフライヤー設定：皮を上にして油を塗り190℃で12分。裏返して油を塗り8分。再度皮を上にして200℃で3分加熱し、皮をパリッと黄金色に仕上げます。","ko":"에어프라이어 설정: 껍질이 위로 향하게 넣고 오일을 발라 190°C에서 12분 굽습니다. 뒤집어 오일을 바르고 8분 구운 뒤, 다시 껍질 쪽으로 돌려 200°C에서 3분간 바삭하게 구워냅니다."}}]}],"troubleshooting":[{"id":"skin-burned-raw-inside","problem":{"zh-TW":"外皮已經焦黑，但雞骨深處仍有血絲未熟","en":"Skin chars black before the bone is cooked through","fil":"Sunog ang balat ngunit may dugo pa sa loob ng buto","ja":"皮が真っ黒に焦げたのに、骨の周りがまだ生焼け","ko":"껍질은 검게 타는데 뼈 부근 속살이 덜 익음"},"cause":{"zh-TW":"炭火太旺，或雞腿最厚處未先劃刀劃透","en":"Direct fire too intense or skipped scoring thickest parts of the thigh","fil":"Masyadong malakas ang apoy o hindi nahiwa ang makakapal na parte","ja":"火力が強すぎたか、肉の厚い部分に切り込みを入れなかったため","ko":"불이 너무 세거나 두꺼운 살 부위에 칼집을 내지 않음"},"solution":{"zh-TW":"醃肉前務必沿著大骨深劃兩刀；炭烤時若火苗竄起，移至間接微炭區慢烘，最後才移回強火刷油上色。","en":"Always score deep cuts down to the bone before marinating. Move chicken to cooler indirect heat if grease flares up.","fil":"Hiwain hanggang buto bago ibabad at iwasan ang malaking apoy.","ja":"骨に達するまで深めの切れ目を入れます。炎が上がったら火の弱い端に避難させ、じっくり遠火で火を通します。","ko":"뼈에 닿을 정도로 깊게 칼집을 내고, 불꽃이 튀면 간접 열 부위로 옮겨 천천히 속까지 익혀주세요."}}],"proTips":[{"zh-TW":"【巴科洛德靈魂吃法】：大蒜炒飯（Sinangag）端上桌，豪爽地淋上一大勺黃金紅木雞油，撒上炸蒜酥，拿手抓著香脆烤雞配著吃，是當地最地道的極致狂歡！","en":"The Bacolod Ritual: Drizzle a generous ladle of golden annatto chicken oil directly over hot garlic rice (Sinangag), sprinkle crispy toasted garlic, and eat with your bare hands (Kamayan style)!","fil":"Gawain sa Bacolod: Buhusan ng maraming dilaw na chicken oil ang mainit na sinangag at kumain nang nakakamay!","ja":"バコロド流の極意：炊きたてのガーリックライスに黄金のチキンオイルをたっぷり垂らし、手づかみ（カマヤンスタイル）で鶏肉と一緒に頬張るのが本場の掟です！","ko":"바콜로드 정통 방식: 뜨거운 마늘 볶음밥 위에 황금빛 치킨 오일을 듬뿍 끼얹고, 바삭한 닭고기를 손으로 뜯어 함께 먹는 \"카마얀\" 스타일이 최고입니다."}]},{"country":"ph","id":"kare-kare","slug":"kare-kare","title":{"zh-TW":"濃郁花生牛尾蔬菜煲 (Kare-Kare with Bagoong)","en":"Rich Oxtail Peanut Stew with Bagoong (Kare-Kare)","fil":"Kare-Kareng Buntot ng Baka na may Bagoong","ja":"本場カレカレ（牛テールと野菜の濃厚ピーナッツ煮込み）","ko":"정통 소꼬리 땅콩 스튜 카레카레 (새우 발효장 바고옹 곁들임)"},"subtitle":{"zh-TW":"皇家慶典金黃御膳・慢熬牛尾膠質豐厚・烘烤研磨花生醬與甘香蝦醬","en":"Royal Fiesta Centerpiece: Gelatinous Braised Oxtail in Velvety Annatto Peanut Sauce","fil":"Pang-kapistahang ulam na may makapal na sarsa ng mani, talong, at sitaw","ja":"宮廷の宴から生まれた黄金のシチュー。アチュエテ色に染まった極上ピーナッツソース","ko":"필리핀 축제의 정수, 콜라겐 가득한 소꼬리와 부드러운 땅콩 소스의 하모니"},"tagline":{"zh-TW":"每一口都充滿堅果馥郁與牛肉膠質，搭配自炒鹹甜蝦醬是人間絕配","en":"Nutty, rich, and deeply comforting—elevated to culinary art when paired with sautéed bagoong","fil":"Hindi kumpleto ang kare-kare kung walang ginisang bagoong alamang sa tabi","ja":"芳醇なピーナッツと牛テールの旨味。小エビの塩辛（バゴオン）を添えて完成する芸術品","ko":"고소한 땅콩소스와 쫀득한 소꼬리. 짭짤달콤한 바고옹 새우장을 얹어 먹는 극상의 풍미"},"heroImage":"/images/ph/kare-kare.jpg","difficulty":"hard","prepTimeMinutes":20,"cookTimeMinutes":60,"defaultServings":5,"caloriesPerServing":560,"category":"mains","dietaryTags":["classic"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"中呂宋・龐培歐省 (Pampanga / Southern Tagalog)","en":"Pampanga & Southern Tagalog","fil":"Pampanga at Katimugang Katagalugan","ja":"パンパンガ州および南部タガログ地方","ko":"팜팡가주 및 남부 타갈로그"},"famousStreetMarkets":[{"zh-TW":"聖費爾南多老街市場 (San Fernando, Pampanga)","en":"San Fernando Heritage Market","fil":"Palengke ng San Fernando","ja":"サンフェルナンド市場","ko":"산페르난도 전통 시장"},{"zh-TW":"馬尼拉各老字號傳統食堂","en":"Heritage Aristocrat Restaurant, Manila","fil":"The Aristocrat Restaurant, Maynila","ja":"マニラ伝統レストラン","ko":"마닐라 전통 식당가"}],"historyStory":{"zh-TW":"Kare-Kare 的起源有兩大說法：一是源自莫洛穆斯林（Moro）料理的印度香料燉肉演變；另一說則是 1762 年英軍佔領馬尼拉時，隨軍而來的印度士兵（Sepoys）在卡因塔（Cainta）定居，因缺少咖哩香料，遂改用本地烤花生、炒米粉與胭脂樹紅木籽調配出濃郁金黃的燉肉。配上慢火炒熟的蝦醬（Bagoong），成為菲律賓最受尊崇的國宴菜餚。","en":"Kare-Kare originated either from pre-colonial Moro stewing methods or from 18th-century Indian Sepoy soldiers stationed in Cainta, Rizal. Missing their homeland curry, they adapted local roasted peanuts, toasted ground rice, and annatto for a golden gravy. The stew is deliberately mild, designed to be seasoned bite-by-bite with salty-sweet sautéed shrimp paste (Bagoong Alamang).","fil":"Nagmula sa mga sundalong Sepoy mula sa India na nanirahan sa Cainta noong panahon ng digmaan. Dahil walang curry, ginamit nila ang dinurog na mani at atsuete.","ja":"18世紀に駐留したセポイ（インド兵）が故郷のカレーを再現しようと、手に入ったピーナッツ、米粉、アチュエテを使って作り上げたのが始まりと言われています。","ko":"18세기 필리핀에 주둔한 인도 병사들이 커리 대신 현지의 볶은 땅콩과 쌀가루, 아나토로 소스를 만들어 소꼬리를 졸여낸 것에서 시작되었습니다."},"filipinoScript":"Kare-Kareng Buntot ng Baka","filipinoPhonetics":"Kah-reh Kah-rehng Boon-tot nang Bah-kah","audioPronunciationText":"Pabili po ng isang mangkok ng Kare-Kare at dagdagan ng bagoong!"},"ingredients":[{"id":"oxtail-beef-shank","name":{"zh-TW":"牛尾塊或牛腱肉 (切厚塊)","en":"Oxtail (cut into segments) or Beef Shank","fil":"Buntot ng Baka","ja":"牛テール（または牛すね肉）","ko":"소꼬리 또는 아롱사태 (토막 낸 것)"},"amount":800,"unitMetric":"g","unitUS":"1.75 lb","isKeyFlavor":true,"filipinoName":"Buntot ng Baka","filipinoPronunciation":"Boon-tot nang Bah-kah"},{"id":"peanut-butter","name":{"zh-TW":"純研磨無糖粗粒花生醬 (或烘烤花生現磨)","en":"Creamy Natural Peanut Butter (Unsweetened preferred)","fil":"Palaman na Mani (Peanut Butter)","ja":"無糖ピーナッツバター（または炒り落花生ペースト）","ko":"땅콩버터 (무가당 크리미 또는 크런치)"},"amount":150,"unitMetric":"g","unitUS":"0.67 cup","isKeyFlavor":true,"filipinoName":"Peanut Butter","filipinoPronunciation":"Pee-nat Bah-ter"},{"id":"atsuete-oil","name":{"zh-TW":"紅木籽油 (Annatto Oil 染出日落金黃)","en":"Annatto Oil (Atsuete Oil for golden amber glow)","fil":"Mantika ng Atsuete","ja":"アチュエテオイル（鮮やかな黄金色に染める）","ko":"아추에테 오일 (황금빛 색감용)"},"amount":3,"unitMetric":"tbsp","unitUS":"3 tbsp","isKeyFlavor":true,"filipinoName":"Atsuete Oil","filipinoPronunciation":"Ah-choo-weh-teh Oil"},{"id":"toasted-rice-flour","name":{"zh-TW":"烘烤糯米粉 (乾鍋慢炒至金黃，天然增稠米香)","en":"Toasted Glutinous Rice Flour (Toasted ground rice for thickening)","fil":"Kinamatisang Bigas / Toasted Rice Flour","ja":"炒り米粉（フライパンで乾煎りしてとろみをつける）","ko":"볶은 찹쌀가루 (구수한 풍미와 걸쭉한 농도 조절)"},"amount":40,"unitMetric":"g","unitUS":"0.33 cup","isKeyFlavor":true,"filipinoName":"Harina ng Bigas","filipinoPronunciation":"Hah-ree-nah nang Bee-gahs"},{"id":"eggplant","name":{"zh-TW":"長紫茄子 (切斜滾刀塊)","en":"Asian Eggplant (Sliced diagonally)","fil":"Talong","ja":"ナス（乱切り）","ko":"가지 (어슷썰기)"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Talong","filipinoPronunciation":"Tah-long"},{"id":"string-beans","name":{"zh-TW":"長豇豆 / 長四季豆 (切段)","en":"Yardlong String Beans (Sitaw, cut into 3-inch batons)","fil":"Sitaw","ja":"十六ささげ（またはインゲン豆）","ko":"롱빈 / 줄기 콩 (7cm 길이로 썰기)"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","filipinoName":"Sitaw","filipinoPronunciation":"See-taw"},{"id":"bok-choy","name":{"zh-TW":"青江菜或白菜","en":"Bok Choy (trimmed)","fil":"Pechay","ja":"青梗菜（チンゲンサイ）","ko":"청경채"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Pechay","filipinoPronunciation":"Peh-tsay"},{"id":"ginisang-bagoong","name":{"zh-TW":"炒熟細蝦醬 (食用時佐搭靈魂，不可缺少！)","en":"Sautéed Shrimp Paste (Ginisang Bagoong Alamang)","fil":"Ginisang Bagoong Alamang","ja":"炒めアミエビ塩辛（バゴオン）","ko":"볶음 새우 발효장 (바고옹 알라망)"},"amount":4,"unitMetric":"tbsp","unitUS":"4 tbsp","isKeyFlavor":true,"filipinoName":"Bagoong Alamang","filipinoPronunciation":"Bah-goh-ong Ah-lah-mang"},{"id":"onion-garlic","name":{"zh-TW":"洋蔥與大蒜 (爆香底料)","en":"Yellow Onion & Garlic (Minced for base)","fil":"Sibuyas at Bawang","ja":"玉ねぎとにんにく","ko":"양파와 마늘"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Sibuyas at Bawang","filipinoPronunciation":"See-boo-yas at Bah-wang"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢燉牛尾至膠質軟爛融化","en":"Boil & Simmer Oxtail until Fork-Tender","fil":"Pakuluan ang Buntot ng Baka Hanggang Lumambot","ja":"牛テールをトロトロになるまでじっくり煮込む","ko":"소꼬리를 푹 삶아 부드럽고 쫀득하게 만들기"},"instruction":{"zh-TW":"牛尾段冷水入鍋大火煮滾，汆燙 5 分鐘撈出沖洗乾淨。換一鍋乾淨清水（約 1500ml），放入牛尾塊、拍扁蒜瓣、洋蔥塊與少許黑胡椒粒。大火煮沸轉小火加蓋燉煮 1.5 - 2 小時（或使用壓力鍋 35 分鐘），直到牛尾軟爛、筷子能輕鬆插透骨肉。保留濃郁牛尾高湯備用！","en":"Parboil oxtail pieces for 5 mins, drain and rinse. In a clean pot with 1500ml water, simmer oxtail with garlic, onions, and peppercorns on low heat for 1.5 - 2 hours (or 35 mins in an Instant Pot) until meltingly tender and rich in collagen. Strain and reserve the golden broth!","fil":"Pakuluan ang buntot ng baka nang 1.5 hanggang 2 oras hanggang lumambot nang husto ang litid at laman. Itabi ang masarap na sabaw.","ja":"牛テールを一度茹でこぼして洗い、新しい水1500ml、ニンニク、玉ねぎと共に弱火で1.5〜2時間（圧力鍋なら35分）煮込みます。旨味の溶け出したスープは取っておきます。","ko":"소꼬리를 끓는 물에 5분간 데쳐 불순물을 씻어냅니다. 새 물 1500ml에 마늘, 양파와 함께 넣고 약불에서 1.5~2시간(압력솥은 35분) 푹 끓여줍니다. 우러난 육수는 보관합니다."},"durationSeconds":5400,"image":"/images/ph/kare-kare-step1.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Meat/Stew High Pressure for 35 mins (natural release)","instructionOverride":{"zh-TW":"壓力鍋模式：汆燙洗淨的牛尾段放入內膽，加水 1000ml、洋蔥蒜頭，選 Meat/Stew 高壓 35 分鐘，自然洩壓 15 分鐘。牛尾膠質全部釋出，軟嫩多汁，省下 70% 瓦斯時間！","en":"Instant Pot Variation: Place blanched oxtail into inner pot with 1000ml water and aromatics. Pressure cook on High for 35 mins, then allow 15 mins natural pressure release. Fall-off-the-bone tender!","fil":"Instant Pot: Ilagay ang buntot ng baka sa 1000ml tubig. I-set sa High Pressure nang 35 minuto.","ja":"電気圧力鍋設定：内鍋に牛テールと水1000mlを入れ、高圧で35分加圧調理。15分蒸らして減圧します。驚くほどホロホロに！","ko":"인스턴트팟 설정: 소꼬리와 물 1000ml, 향신채를 넣고 고압 35분 조리 후 15분 자연 감압합니다. 뼈에서 살이 쏙 빠질 정도로 부드러워집니다."}}]},{"stepNumber":2,"title":{"zh-TW":"炒出紅木金香底油，融化濃醇花生醬","en":"Sauté Aromatics in Annatto Oil & Whisk Peanut Butter","fil":"Igisa sa Atsuete Oil at Ilagay ang Peanut Butter","ja":"アチュエテ油で炒め、ピーナッツバターを溶かし合わせる","ko":"아추에테 오일에 양파 마늘을 볶고 땅콩버터 풀기"},"instruction":{"zh-TW":"深鍋中倒入 3 大匙紅木籽油（Atsuete Oil），中火爆香切碎洋蔥與蒜泥。倒入煮好的牛尾塊翻炒均勻裹上亮橙色。倒入約 600ml 牛尾高湯煮滾，轉小火，加入 150g 花生醬，用打蛋器或湯勺攪拌均勻至醬汁完全乳化、呈現絲絨般金色濃湯質地。","en":"In a large heavy pot, heat 3 tbsp annatto oil. Sauté onions and garlic until fragrant. Add cooked oxtail and stir until coated in glowing orange oil. Pour in 600ml reserved beef broth, bring to simmer, and whisk in 150g peanut butter until silky, creamy, and golden.","fil":"Painitin ang atsuete oil, igisa ang sibuyas at bawang. Ilagay ang buntot ng baka at sabaw, tapos ihalo ang peanut butter hanggang lumapot.","ja":"大鍋にアチュエテオイル大さじ3を熱し、玉ねぎとニンニクを炒めます。牛テールを加えて色を絡め、牛テールスープ600mlを注ぎます。ピーナッツバターを溶かし入れ、滑らかな黄金色のソースにします。","ko":"냄비에 아추에테 오일 3큰술을 두르고 양파와 마늘을 볶습니다. 소꼬리를 넣어 코팅한 뒤 육수 600ml를 붓고, 땅콩버터를 넣어 멍울 없이 부드럽게 풀어줍니다."},"durationSeconds":300,"image":"/images/ph/kare-kare-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"調入炒米粉水勾出厚芡，加入蔬菜煨熟","en":"Thicken with Toasted Rice & Simmer Veggies","fil":"Palaputin Gamit ang Harina ng Bigas at Ilagay ang Gulay","ja":"炒り米粉でとろみをつけ、野菜を加えて煮込む","ko":"볶은 찹쌀가루 물로 농도를 잡고 채소 익히기"},"instruction":{"zh-TW":"將烘烤糯米粉加少許冷水調勻成米漿，邊攪拌邊淋入鍋中，小火慢煮 3 分鐘，醬汁會變得如絲絨般濃稠油亮。放入長豇豆段、茄子塊與青江菜，加蓋小火燜煮 5 分鐘直到蔬菜鮮甜脆嫩。大碗盛出，旁邊必定搭配一大勺香炒蝦醬（Ginisang Bagoong）！","en":"Slurry toasted rice flour with 4 tbsp cold water. Drizzle into bubbling stew while stirring; cook 3 mins until the sauce thickens into luxurious velvet. Add string beans, eggplant slices, and bok choy; simmer 5 mins until tender-crisp. Serve in a clay pot accompanied by a generous dish of sautéed bagoong!","fil":"Tunawin ang toasted rice flour sa tubig at ihalo sa sarsa. Ilagay ang sitaw, talong, at pechay nang 5 minuto. Ihain na may kasamang bagoong alamang!","ja":"炒り米粉を水で溶いて加え、とろみが出るまで3分煮ます。インゲン、ナス、青梗菜を加え5分ほど煮て野菜に火を通します。小皿にたっぷりのバゴオン（エビ味噌）を添えて完成です！","ko":"볶은 찹쌀가루를 찬물에 개어 국물에 둘러 넣고 3분간 저어가며 걸쭉하게 농도를 맞춥니다. 콩, 가지, 청경채를 넣고 5분간 익혀줍니다. 볶음 바고옹 새우장을 곁들여 상에 올립니다."},"durationSeconds":480,"image":"/images/ph/kare-kare-step3.jpg"}],"troubleshooting":[{"id":"sauce-too-bland","problem":{"zh-TW":"花生醬汁喝起來淡而無味，缺少鹹香","en":"Sauce tastes flat and lacks saltiness","fil":"Matabang ang sarsa ng kare-kare","ja":"ピーナッツソースの味が薄く、塩気が足りない","ko":"스튜 맛이 밋밋하고 간이 안 된 느낌"},"cause":{"zh-TW":"傳統 Kare-Kare 在燉煮時故意不加過多鹽分，風味完全依賴食用時搭配的炒蝦醬（Bagoong）！","en":"Traditional Kare-Kare is intentionally left lightly salted because it is meant to be seasoned at the table with the salty-sweet bagoong!","fil":"Sadya itong matabang dahil ang ginisang bagoong ang nagbibigay ng alat at lasa habang kumakain.","ja":"伝統的なカレカレは意図的に薄味に仕上げられています。添えられたエビ塩辛（バゴオン）と混ぜて初めて完成する料理です。","ko":"전통 카레카레는 짭조름한 바고옹 새우장과 비벼 먹도록 원래 간을 세게 하지 않는 것이 정석입니다."},"solution":{"zh-TW":"千萬不要在鍋裡狂加鹽！舀一勺濃稠花生醬汁與燉軟的牛尾肉，配上一小抹鹹甜香辣的 Ginisang Bagoong 蝦醬與白飯一同入口，滋味瞬間昇華圓滿！","en":"Do not oversalt the pot! Spoon some peanut gravy over rice, dollop a bit of savory Bagoong on top, and eat together.","fil":"Kumuha ng kanin, lagyan ng sarsa at karne, at lagyan ng bagoong alamang bago isubo.","ja":"鍋に塩を足しすぎないこと！ご飯の上にカレカレをかけ、スプーンの先にバゴオンを少し乗せて一緒に食べると感動的な美味しさになります。","ko":"냄비에 소금을 더 넣지 마세요! 밥 위에 스튜를 얹고 바고옹 새우장을 조금 얹어 함께 드시면 완벽한 감칠맛을 느낄 수 있습니다."}}],"proTips":[{"zh-TW":"【烘烤炒米粉增香】：不要省略炒米粉步驟！將白糯米放在乾平底鍋中不放油小火乾煸至微焦黃，研磨成粉加入煲中，不僅提供厚實濃稠度，更有爆米花般的獨特堅果穀物香！","en":"Toasted Rice Secret: Dry-toasting rice in a skillet until golden brown before grinding yields a distinct roasted aroma and velvet mouthfeel that regular cornstarch can never replicate!","fil":"Tip ng Kusinero: Isangag muna ang bigas sa kawali bago durugin para sa mabangong sarsa.","ja":"炒り米の極意：米を油を引かずにフライパンでキツネ色になるまで乾煎りしてから粉砕すると、コーンスターチでは出せない香ばしさと奥深いとろみが生まれます。","ko":"볶은 쌀가루 비법: 마른 팬에 찹쌀을 노릇하게 볶아 갈아 넣으면 전분과는 비교할 수 없는 구수한 팝콘 풍미와 환상적인 농도가 완성됩니다."}]},{"country":"ph","id":"halo-halo","slug":"halo-halo","title":{"zh-TW":"菲律賓國寶彩虹八寶雪花冰 (Halo-Halo Especial)","en":"The Ultimate Halo-Halo Especial (Rainbow Shaved Ice)","fil":"Espesyal na Halo-Halo ng Pilipinas","ja":"本場最高峰ハロハロ（七色具材の極上かき氷パフェ）","ko":"필리핀 국보급 레인보우 빙수 할로할로 에스페셜"},"subtitle":{"zh-TW":"群島甜品至尊・紫薯泥焦糖布丁・椰果蜜蕉西米露・烘烤青糯米粒頂級冠冕","en":"The King of Tropical Sweets: Layered Shaved Ice, Ube Halaya, Leche Flan & Crispy Pinipig","fil":"Pambansang panghimagas na may ube, leche flan, saging, sago at sorbetes sa ibabaw","ja":"彩り豊かな名物トッピングが重なり合う南国フィリピンの象徴的スイーツ","ko":"우베 보라잼, 캐러멜 푸딩, 코코넛 젤리가 층층이 쌓인 남국의 시원한 보물"},"tagline":{"zh-TW":"「Halo-Halo」在菲語意為「攪拌混合」！五彩斑斕的大玻璃杯，攪勻吃最道地","en":"\"Halo-Halo\" literally means \"mix-mix\"—the vibrant national cooler you stir and savor","fil":"Haluin nang mabuti mula ilalim hanggang ibabaw upang maranasan ang tunay na sarap","ja":"タガログ語で「混ぜこぜ」を意味する国民的氷菓子。底から豪快に混ぜて食べるのが流儀","ko":"타갈로그어로 \"섞고 섞는다\"는 뜻! 유리잔 바닥부터 시원하게 비벼 먹는 최고의 여름 디저트"},"heroImage":"/images/ph/halo-halo.jpg","difficulty":"easy","prepTimeMinutes":20,"cookTimeMinutes":5,"defaultServings":2,"caloriesPerServing":420,"category":"desserts","dietaryTags":["classic","vegetarian"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"全菲律賓（起源於二戰前奎阿坡與岷倫洛的日裔日式紅豆刨冰 Kakigori）","en":"Pre-WWII Manila (Evolution of Japanese Kakigori & Mitsumame)","fil":"Maynila at Buong Pilipinas","ja":"マニラ発祥（戦前の日本人移民のかき氷「かき氷・ぜんざい」が現地で進化）","ko":"마닐라 (제2차 세계대전 이전 일본식 빙수에서 현지화되어 발전)"},"famousStreetMarkets":[{"zh-TW":"奎阿坡老教堂周邊甜品冷飲排檔","en":"Quiapo Halo-Halo Carts","fil":"Halo-Halo sa Quiapo","ja":"キアポ屋台通り","ko":"퀴아포 디저트 노점"},{"zh-TW":"邦板牙省 Guagua 知名老字號 (Razon’s Halo-Halo)","en":"Razon’s Heritage of Guagua, Pampanga","fil":"Guagua, Pampanga","ja":"パンパンガ州グアグア","ko":"팜팡가 구아구아 전통점"}],"historyStory":{"zh-TW":"20世紀初，許多日本移民在馬尼拉奎阿坡市場開設日式刨冰店（Mongo-ya），售賣加入甜紅豆的碎冰甜點。菲律賓人隨後發揮無與倫比的熱帶創意，陸續加入了本地盛產的糖煮芭蕉、紫薯泥（Ube）、椰果、亞答子，以及西班牙殖民留下來的皇家焦糖布丁（Leche Flan）。這杯兼具多國文化融合的甜品，成為菲國不可動搖的國寶！","en":"In the early 1900s, Japanese immigrants in Manila operated refreshment parlors serving shaved ice with sweetened beans (kakigori). Filipinos enthusiastically adopted the concept, expanding it with indigenous sweet plantains, ube halaya, nata de coco, macapuno, and crowning it with a decadent slice of Spanish Leche Flan and ube ice cream!","fil":"Nagsimula noong bago ang digmaan mula sa Japanese kakigori na may monggo. Dinagdagan ito ng mga Pilipino ng ube, leche flan, langka, at saging na saba hanggang maging sikat na halo-halo.","ja":"戦前マニラで日本人移民が営んでいた甘味処のかき氷（小豆ぜんざい）が起源。フィリピンの人々が自生の熱帯果実やウベ、スペイン由来のプリンを合わせ、世界に誇る豪華なハロハロへと完成させました。","ko":"1900년대 초 마닐라의 일본 이민자들이 팔던 팥빙수에서 유래하여, 필리핀인들이 우베, 코코넛, 바나나, 스페인식 푸딩을 더해 세계에서 가장 화려한 무지개 빙수로 발전시켰습니다."},"filipinoScript":"Espesyal na Halo-Halo","filipinoPhonetics":"Es-peh-syal nah Hah-loh Hah-loh","audioPronunciationText":"Pabili po ng dalawang baso ng Special Halo-Halo, may Leche Flan at Ube!"},"ingredients":[{"id":"shaved-ice","name":{"zh-TW":"細緻綿密刨冰","en":"Fine Shaved Ice","fil":"Kiskis na Yelo","ja":"きめ細かい削り氷","ko":"고운 눈꽃/샤베트 얼음"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Yelo","filipinoPronunciation":"Yeh-loh"},{"id":"evaporated-milk","name":{"zh-TW":"經典三花淡奶 (Evaporated Milk)","en":"Evaporated Milk (Gatas Evaporada)","fil":"Gatas Evaporada","ja":"エバミルク（無糖練乳）","ko":"무가당 연유 (에바포레이티드 밀크)"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Gatas Evaporada","filipinoPronunciation":"Gah-tahs Eh-vah-poh-rah-dah"},{"id":"ube-halaya","name":{"zh-TW":"自製香濃紫薯泥 (Ube Halaya)","en":"Ube Halaya (Purple Yam Jam)","fil":"Ube Halaya","ja":"ウベ紫芋ペースト（ウベ・ハラヤ）","ko":"우베 자색마 잼 (우베 할라야)"},"amount":60,"unitMetric":"g","unitUS":"2 oz","isKeyFlavor":true,"filipinoName":"Ube Halaya","filipinoPronunciation":"Oo-beh Hah-lah-yah"},{"id":"leche-flan-slice","name":{"zh-TW":"焦糖布丁切片 (Leche Flan)","en":"Leche Flan (Caramel Custard Slices)","fil":"Hiwa ng Leche Flan","ja":"カスタードプリン（レチェ・フラン）","ko":"캐러멜 커스터드 푸딩 슬라이스"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Leche Flan","filipinoPronunciation":"Leh-cheh Flan"},{"id":"sweetened-banana","name":{"zh-TW":"焦糖糖煮芭蕉丁 (Minatamis na Saging)","en":"Sweetened Saba Bananas (diced)","fil":"Minatamis na Saging","ja":"黒糖煮込みバナナ","ko":"달콤하게 졸인 사바 바나나"},"amount":60,"unitMetric":"g","unitUS":"2 oz","filipinoName":"Minatamis na Saging","filipinoPronunciation":"Mee-nah-tah-mees nah Sah-geeng"},{"id":"nata-de-coco","name":{"zh-TW":"晶瑩白椰果 (Nata de Coco)","en":"Nata de Coco (Coconut Gel Cubes)","fil":"Nata de Coco","ja":"ナタデココ","ko":"나타드코코"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","filipinoName":"Nata de Coco","filipinoPronunciation":"Nah-tah deh Koh-koh"},{"id":"macapuno","name":{"zh-TW":"糖漬椰子胚乳絲 (Macapuno Strings)","en":"Macapuno (Sweetened Coconut Sport)","fil":"Minatamis na Macapuno","ja":"マカプノ（ゼリー状ココナッツ）","ko":"마카푸노 코코넛 과육 절임"},"amount":40,"unitMetric":"g","unitUS":"1.4 oz","filipinoName":"Macapuno","filipinoPronunciation":"Mah-kah-poo-noh"},{"id":"pinipig","name":{"zh-TW":"酥脆烤青糯米粒 (Pinipig)","en":"Crispy Toasted Young Rice (Pinipig)","fil":"Pinipig","ja":"炒り青米（ピニピッグ）","ko":"바삭한 볶은 쌀과자 (피니피그)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"filipinoName":"Pinipig","filipinoPronunciation":"Pee-nee-peeg"},{"id":"ube-ice-cream","name":{"zh-TW":"紫薯冰淇淋球 (Sorbetes na Ube)","en":"Ube Ice Cream Scoop","fil":"Sorbetes na Ube","ja":"ウベアイスクリーム","ko":"우베 자색마 아이스크림 1스쿱"},"amount":2,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Sorbetes na Ube","filipinoPronunciation":"Sor-beh-tes nah Oo-beh"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"在高腳玻璃杯底堆疊繽紛配料","en":"Layer Sweet Ingredients in Tall Glass","fil":"Iayos ang mga Sahog sa Ilalim ng Matangkad na Baso","ja":"背の高いグラス底に彩り豊かな具材を重ねる","ko":"긴 유리잔 바닥에 다채로운 토핑 깔기"},"instruction":{"zh-TW":"準備兩個乾淨的大容量高腳玻璃杯或深碗。在杯底依次鋪入：糖漬芭蕉丁、晶瑩椰果（Nata de Coco）、椰子胚乳絲（Macapuno）、蜜紅豆、甜波羅蜜絲。五彩繽紛的斷層是經典視覺享受。","en":"Prepare two tall, wide clear glasses. Layer bottom with diced sweet Saba bananas, translucent nata de coco, macapuno coconut sport, sweet beans, and jackfruit strips. The visible layers of color create the signature rainbow look.","fil":"Maghanda ng dalawang matangkad na baso. Ilagay sa ilalim ang minatamis na saging, nata de coco, macapuno, minatamis na beans, at langka.","ja":"透明なパフェグラスを2つ用意します。底にバナナ甘煮、ナタデココ、マカプノ、小豆、パラミツ果肉を層になるように美しく重ねます。","ko":"투명한 유리잔 바닥에 조린 바나나, 나타드코코, 마카푸노, 단팥, 잭프루트를 층층이 예쁘게 깔아줍니다."},"durationSeconds":180,"image":"/images/ph/halo-halo-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"填入綿密刨冰並淋入濃醇三花淡奶","en":"Pack Shaved Ice & Drizzle Rich Evaporated Milk","fil":"Punuin ng Kayod na Yelo at Buhusan ng Gatas","ja":"削り氷をこんもり盛り、エバミルクをたっぷり注ぐ","ko":"고운 얼음을 소복이 담고 무가당 연유 듬뿍 붓기"},"instruction":{"zh-TW":"用手搖刨冰機或電動碎冰機磨出細膩如雪的冰晶，緊實地填滿玻璃杯直到杯口微隆起成圓頂雪丘狀。將 60ml 濃香的三花淡奶均勻淋在冰晶上，看著白雪緩緩吸飽乳香、融進底層。","en":"Pack finely shaved ice tightly into each glass, mounding gently into a snowy dome at the rim. Pour 60ml of rich evaporated milk evenly over the shaved ice, watching it saturate the ice and seep into the lower layers.","fil":"Lagyan ng pinong yelo hanggang mapuno ang baso. Ibuhos ang gatas na ebaporada sa ibabaw ng yelo.","ja":"細かく削った氷をグラスのフチまでこんもり盛り、ドーム状にします。上からエバミルクを回しかけ、氷全体にミルクを行き渡らせます。","ko":"곱게 간 얼음을 잔 위로 소복하게 채웁니다. 무가당 연유 60ml를 얼음 위에 골고루 끼얹어 얼음 사이사이로 우유가 스며들게 합니다."},"durationSeconds":120,"image":"/images/ph/halo-halo-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"冠上紫薯泥、焦糖布丁與冰淇淋球","en":"Crown with Ube Halaya, Leche Flan & Ube Ice Cream","fil":"Patungan ng Ube Halaya, Leche Flan at Sorbetes","ja":"ウベ餡、プリン、ウベアイスを冠のように飾る","ko":"우베 잼, 캐러멜 푸딩, 우베 아이스크림으로 화룡점정"},"instruction":{"zh-TW":"在刨冰雪頂的一側放上一大勺濃郁深紫的 Ube Halaya 紫薯泥，另一側平鋪一塊滑嫩金黃的 Leche Flan 焦糖布丁切片。中央挖上一大球天鵝絨般綿密的 Ube 紫薯冰淇淋，最後大氣撒上一大匙金黃香脆的烤青糯米粒（Pinipig）！插上長湯匙端上桌！","en":"On top of the shaved ice dome, place a generous spoonful of purple Ube Halaya jam on one side and a slice of golden caramel Leche Flan on the other. Crown the center with a giant scoop of artisanal Ube ice cream. Generously scatter crispy toasted Pinipig on top! Insert a long sundae spoon and serve!","fil":"Ilagay sa ibabaw ang ube halaya, isang hiwa ng leche flan, at isang scoop ng ube ice cream. Budburan ng malutong na pinipig sa ibabaw!","ja":"雪山の上にウベ紫芋ペーストとカスタードプリンをのせ、中央にウベアイスクリームを堂々と鎮座させます。仕上げに香ばしい炒り青米（ピニピッグ）を散らして完成です！","ko":"얼음 위에 우베 잼과 캐러멜 푸딩을 올리고, 가운데에 자색마(우베) 아이스크림 한 스쿱을 크게 얹습니다. 바삭한 피니피그 쌀 토핑을 뿌려 긴 스푼과 함께 서빙합니다."},"durationSeconds":120,"image":"/images/ph/halo-halo-step3.jpg"}],"troubleshooting":[{"id":"ice-melts-too-fast","problem":{"zh-TW":"還沒吃幾口，整杯冰就化成水了","en":"Shaved ice melts into water too quickly","fil":"Mabilis matunaw ang yelo sa baso","ja":"食べる前に氷がどんどん溶けて水っぽくなってしまう","ko":"먹기도 전에 얼음이 금방 녹아 물이 됨"},"cause":{"zh-TW":"底層配料溫度過高，或使用了常溫淡奶","en":"Ingredients or milk were warm/room temperature","fil":"Mainit ang mga minatamis na sahog o gatas","ja":"トッピングやミルクが常温のまま温かかったため","ko":"토핑이나 연유가 미지근한 상태에서 얼음을 올렸음"},"solution":{"zh-TW":"在組裝前，將紫薯泥、焦糖布丁、各類果凍配料以及淡奶全部放在冰箱充分冰鎮！冰涼透頂的配料能讓刨冰維持 15 分鐘堅挺脆涼。","en":"Chill ALL ingredients, glass cups, and evaporated milk in the fridge before assembling!","fil":"Palamigin muna ang lahat ng sangkap, baso, at gatas sa ref bago ihalo.","ja":"グラス、具材、ミルクに至るまで、事前に冷蔵庫でしっかり冷やしておくのが鉄則です。","ko":"유리잔과 모든 토핑, 연유를 조립 전 냉장고에 차갑게 보관했다가 사용하세요."}}],"proTips":[{"zh-TW":"【正宗菲律賓吃法】：先嚐一口頂層的純紫薯泥與焦糖布丁，感受極致甜濃；接著雙手握緊長湯匙，從玻璃杯底深處「大口用力攪拌（Halo-Halo）」，將雪花冰、淡奶、紫薯泥、果凍與布丁完全融為一體，變成紫粉色如泥漿般的濃稠奶昔，大口吸吮，才是靈魂所在！","en":"How Filipinos Eat It: First take one decadent bite of the flan and ube cream. Then grab your long spoon and STIR FURIOUSLY from the bottom until everything melts into a glorious purple creamy slush! Drink and spoon up the sweet magic!","fil":"Tamang Paraan ng Pagkain: Tikman muna ang leche flan, tapos ay haluin nang mabuti ang buong baso hanggang maging kulay ube ang buong yelo bago higupin.","ja":"本場の食べ方：まずプリンとアイスを一口味わったら、あとは底からスプーンで一心不乱に「混ぜこぜ（ハロハロ）」！全体がクリーミーな紫色になったところを一気にすするのが真のフィリピン流です。","ko":"현지인처럼 먹는 법: 먼저 푸딩과 아이스크림을 한 입 맛본 뒤, 긴 스푼으로 바닥부터 힘차게 비벼주세요! 연보랏빛 부드러운 셰이크 상태가 되었을 때 호로록 마시는 것이 최고의 묘미입니다."}]},{"country":"ph","id":"leche-flan","slug":"leche-flan","title":{"zh-TW":"菲式皇家金箔焦糖布丁 (Leche Flan)","en":"Velvety Filipino Caramel Custard (Leche Flan)","fil":"Makinis at Malinamnam na Leche Flan","ja":"本場極上レチェ・フラン（卵黄のみで作る濃厚キャラメルカスタード）","ko":"필리핀 황실의 맛 레체 플란 (노른자로 만든 진한 캐러멜 커스터드)"},"subtitle":{"zh-TW":"西班牙宮廷古典流派・純蛋黃濃縮奶香・如絲絹般綿密無氣孔・琥珀焦糖液緩緩流淌","en":"Pure Egg Yolks, Sweet Condensed & Evaporated Milk Baked to Silk with Amber Caramel","fil":"Espesyal na panghimagas sa llanera na makinis at walang butas-butas","ja":"気泡ゼロの驚異的ななめらかさ。琥珀色のほろ苦カラメルと濃厚な卵黄の至福","ko":"기포 없이 비단결처럼 부드러운 텍스처, 쌉싸름한 캐러멜 시럽의 완벽한 밸런스"},"tagline":{"zh-TW":"全亞洲最濃醇的重蛋黃布丁，每一口都在舌尖化作極致濃稠的焦糖奶香","en":"Richer, denser, and far more decadent than French crème caramel—a national obsession","fil":"Ang paboritong matamis sa Pasko at kapistahan na tunaw sa bawat subo","ja":"世界各国のプリンファンを虜にする究極の濃厚さ。一口で広がる至高の口溶け","ko":"일반 푸딩과는 차원이 다른 묵직함과 농축된 우유의 풍미로 사랑받는 필리핀의 자랑"},"heroImage":"/images/ph/leche-flan.jpg","difficulty":"medium","prepTimeMinutes":20,"cookTimeMinutes":45,"defaultServings":6,"caloriesPerServing":360,"category":"desserts","dietaryTags":["classic","vegetarian","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"西班牙殖民時期修道院與各大歷史莊園 (Spanish Colonial Era)","en":"Spanish Colonial convent kitchens (using egg yolks left over from masonry)","fil":"Kusina ng mga Prayle at Simbahan noong panahon ng Kastila","ja":"スペイン植民地時代の修道院（教会の石垣作りに卵白を使った余りから誕生）","ko":"스페인 식민지 시절 수도원 (성당 건축에 달걀 흰자를 쓰고 남은 노른자로 개발)"},"famousStreetMarkets":[{"zh-TW":"奎松市各老字號烘焙糕點坊","en":"Heritage bakeries of Quezon City & Bulacan","fil":"Bulacan at Quezon City","ja":"ブラカン州名物ベーカリー","ko":"불라칸 전통 베이커리 거리"},{"zh-TW":"全菲聖誕夜（Noche Buena）家家戶戶餐桌","en":"Noche Buena Christmas Eve Feast Tables","fil":"Noche Buena sa buong bansa","ja":"フィリピン全土のクリスマス祝宴","ko":"필리핀 크리스마스 이브 축제 식탁"}],"historyStory":{"zh-TW":"在西班牙統治時期，天主教神父在全菲建造石造大教堂時，利用數以百萬計的生雞蛋清混合石灰作為堅固的水泥黏著劑。為了不浪費海量的蛋黃，廚師與修女們將純蛋黃與煉乳、蒸餾淡奶混合，裝在傳統橢圓形鐵盒（Llanera）中蒸烤出極致奢華的 Leche Flan。它成了菲律賓各大家族跨年夜必備的壓軸皇冠！","en":"During the Spanish era, millions of egg whites were used as mortar binding to build historical coral stone churches. To avoid wasting mountains of egg yolks, convent bakers combined them with condensed and evaporated milk inside oval tin molds called \"Llaneras\". It became the crown jewel of Noche Buena Christmas feasts!","fil":"Noong panahon ng Kastila, ginamit ang puti ng itlog sa pagpapatayo ng mga simbahan. Ang natirang dilaw ng itlog ay ginawang napakasarap na leche flan sa llanera.","ja":"教会の石造りの壁を固めるモルタルとして卵白が大量に使われたため、残った大量の卵黄を活用して修道院で誕生した歴史的スイーツです。","ko":"식민지 시절 석조 성당을 지을 때 접착제로 흰자를 사용하면서 남은 수많은 노른자를 해결하기 위해 수녀원에서 만든 것에서 유래했습니다."},"filipinoScript":"Espesyal na Leche Flan","filipinoPhonetics":"Es-peh-syal nah Leh-cheh Flan","audioPronunciationText":"Pabili po ng isang buong llanera ng makinis na Leche Flan!"},"ingredients":[{"id":"egg-yolks","name":{"zh-TW":"純新鮮蛋黃 (徹底分離蛋白，極致濃稠)","en":"Egg Yolks only (separated cleanly)","fil":"Pula ng Itlog (Ihiwalay ang puti)","ja":"卵黄のみ（白身は完全に除く）","ko":"신선한 달걀 노른자만 (흰자 완전 분리)"},"amount":10,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Pula ng Itlog","filipinoPronunciation":"Poo-lah nang Eet-log"},{"id":"condensed-milk","name":{"zh-TW":"原味加糖煉乳 (Condensed Milk)","en":"Sweetened Condensed Milk","fil":"Gatas Kondensada","ja":"加糖練乳（コンデンスミルク）","ko":"가당 연유"},"amount":300,"unitMetric":"ml","unitUS":"1 can","isKeyFlavor":true,"filipinoName":"Gatas Kondensada","filipinoPronunciation":"Gah-tahs Kon-den-sah-dah"},{"id":"evaporated-milk","name":{"zh-TW":"無糖蒸餾淡奶 (Evaporated Milk)","en":"Evaporated Milk","fil":"Gatas Evaporada","ja":"無糖練乳（エバミルク）","ko":"무가당 연유 (에바포레이티드 밀크)"},"amount":300,"unitMetric":"ml","unitUS":"1 can","isKeyFlavor":true,"filipinoName":"Gatas Evaporada","filipinoPronunciation":"Gah-tahs Eh-vah-poh-rah-dah"},{"id":"granulated-sugar","name":{"zh-TW":"白砂糖 (熬煮焦糖液用)","en":"Granulated White Sugar (for golden caramel syrup)","fil":"Puting Asukal (Pang-arnibal)","ja":"白砂糖（カラメル用）","ko":"백설탕 (캐러멜 시럽용)"},"amount":100,"unitMetric":"g","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Asukal","filipinoPronunciation":"Ah-soo-kal"},{"id":"vanilla-calamansi","name":{"zh-TW":"純香草精與微量金桔皮屑 (去蛋腥增香)","en":"Pure Vanilla Extract & zest of 1 calamansi","fil":"Bainilya at balat ng kalamansi","ja":"バニラエッセンスとカラマンシー果皮すりおろし","ko":"바닐라 익스트랙 & 깔라만시 제스트 소량"},"amount":1,"unitMetric":"tsp","unitUS":"1 tsp","filipinoName":"Bainilya","filipinoPronunciation":"Bah-ee-neel-yah"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火熬煮琥珀金黃焦糖底","en":"Melt Caramel Directly in the Llanera / Pan","fil":"Tunawin ang Asukal para sa Arnibal","ja":"型（または小鍋）の中で砂糖を溶かしキャラメルを作る","ko":"틀에 설탕을 녹여 영롱한 앰버 캐러멜 만들기"},"instruction":{"zh-TW":"在傳統菲律賓橢圓烤模（Llanera）或平底耐熱模具中放入白糖與 1 大匙清水。放在微弱瓦斯小火上加熱（或在小奶鍋中熬煮），無須用鏟子攪動，只需輕輕搖晃模具，直到白糖完全融化化為誘人的清澈琥珀金黃色。關火，旋轉模具讓焦糖均勻鋪滿模底，靜置冷卻硬化。","en":"Place white sugar and 1 tbsp water directly into the bottom of an oval aluminum mold (Llanera) or small saucepan. Place over gentle low heat. Do NOT stir with a spoon; gently swirl the mold as sugar melts and browns into a gleaming clear amber caramel. Remove from heat and tilt mold so caramel coats the bottom. Let cool and harden.","fil":"Tunawin ang asukal sa llanera sa mahinang apoy hanggang maging kulay arnibal. Ikot ang llanera at palamigin hanggang tumigas.","ja":"焼き型（または小鍋）に砂糖と水大さじ1を入れ、弱火にかけます。混ぜずに型を揺すりながら加熱し、透き通った琥珀色のキャラメルになったら火を止め、底全体に行き渡らせて冷まします。","ko":"원형 또는 타원형 틀에 설탕과 물 1큰술을 넣고 약불에서 젓지 말고 팬을 돌려가며 끓입니다. 맑은 호박색 캐러멜이 되면 불을 끄고 바닥에 고루 펴준 뒤 식혀 굳힙니다."},"durationSeconds":300,"image":"/images/ph/leche-flan-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"輕柔混合蛋黃乳液，三道過篩去氣泡","en":"Gently Whisk Custard & Strain 3 Times","fil":"Haluin nang Dahan-dahan at Salain nang Tatlong Beses","ja":"卵黄とミルクを優しく混ぜ、3回濾して気泡をなくす","ko":"노른자와 우유를 거품 없이 섞고 3번 체에 거르기"},"instruction":{"zh-TW":"碗中放入 10 顆純蛋黃，加入煉乳、淡奶、香草精與微量金桔皮屑。用打蛋器【順同一方向輕柔慢攪，切忌打出氣泡！】。拿細密濾網將布丁液【連續過篩 3 次】，濾除所有未融蛋帶與微小氣孔。這是成就絲絹無孔質地的最關鍵秘訣！","en":"Gently whisk 10 egg yolks with condensed milk, evaporated milk, vanilla, and calamansi zest. [CRUCIAL: STIR GENTLY IN ONE DIRECTION WITHOUT WHIPPING AIR!]. Pour the custard through a fine-mesh strainer 3 TIMES to remove all chalaza and air bubbles. This guarantees mirror-smooth texture!","fil":"Dahan-dahang haluin ang 10 pula ng itlog, kondensada, evaporada, at bainilya. Salain sa pinong salaan nang TATLONG BESES upang maging makinis na parang sutla.","ja":"卵黄10個に練乳、エバミルク、バニラを合わせ、空気が入らないよう同一方向に静かに混ぜます。キメを整えるため【目の細かいザルで3回濾します】。気泡のない至高の舌触りが生まれます。","ko":"볼에 노른자 10개, 연유, 무가당 연유, 바닐라를 넣고 거품이 생기지 않도록 살살 저어줍니다. 알끈과 기포를 완벽히 없애기 위해 【고운 체에 3번 걸러줍니다】."},"durationSeconds":360,"image":"/images/ph/leche-flan-step2.jpg","crucialTips":{"zh-TW":"切忌像做蛋糕那樣快速打發！快速打入空氣會使烤出來的布丁充滿蜂窩孔洞。動作越溫柔，質地越像高級天鵝絨。","en":"Never whip vigorously! Aerating the mixture causes spongy, bubbly holes. Gentle sweeping strokes make it velvety and dense.","fil":"Huwag batihin nang mabilis upang hindi magkabula-bula sa loob pag naluto.","ja":"激しく泡立てないこと！空気が混ざるとスが入って蜂の巣状になってしまいます。優しく混ぜるのがシルクの舌触りの秘訣です。","ko":"휘핑기를 거세게 치대지 마세요! 공기가 들어가면 구웠을 때 구멍(기포)이 숭숭 뚫립니다. 부드럽게 원을 그리듯 저어주세요."}},{"stepNumber":3,"title":{"zh-TW":"鋁箔紙緊密密封，水浴蒸烤或冷卻脫模","en":"Seal with Foil, Steam / Water Bath Bake & Invert","fil":"Takpan ng Foil, I-steam at Palamigin Bago Baligtarin","ja":"アルミホイルで密閉し湯煎蒸し焼き、冷やして皿に返す","ko":"호일로 밀봉 후 중탕 찌기, 차게 식혀 뒤집기"},"instruction":{"zh-TW":"將過篩後的布丁液緩緩倒入焦糖模具中（九分滿）。表面用鋁箔紙【緊密包裹封口，防止蒸氣水珠滴落表面】。放入蒸鍋中火蒸 35-40 分鐘（筷子插中央乾淨拔出即可）。【或壓力鍋模式請參見切換】。取出常溫晾涼後，冷藏至少 4 小時。用薄刀沿邊緣劃一圈，倒扣在大圓盤上，琥珀焦糖液如瀑布傾瀉！","en":"Pour silky custard into the caramel-lined mold. Seal tightly with aluminum foil so water condensation does not drip onto the surface. Steam over medium heat for 35-40 mins until set (toothpick comes out clean). Refrigerate at least 4 hours. Run a thin knife along the edges and invert onto a lipped platter. The caramel sauce cascades down!","fil":"Takpan nang mahigpit ng aluminum foil ang llanera. I-steam nang 35-40 minuto. Palamigin sa ref nang 4 na oras bago itaob sa plato.","ja":"水滴が落ちないようアルミホイルでしっかりフタをし、中火の蒸し器で35〜40分蒸します。粗熱を取り冷蔵庫で4時間以上しっかり冷やします。ナイフで周囲を外し、お皿の上に一気にひっくり返すとキャラメルが美しく流れ出します！","ko":"틀에 반죽을 붓고 수증기가 떨어지지 않게 알루미늄 호일로 꼼꼼히 감쌉니다. 찜기에 35~40분간 쪄낸 후 냉장고에서 4시간 이상 굳힙니다. 칼로 가장자리를 분리해 접시에 뒤집어주면 완성!"},"durationSeconds":2400,"image":"/images/ph/leche-flan-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Steam / Manual Low Pressure for 14 mins (natural release)","instructionOverride":{"zh-TW":"壓力鍋模式：內膽放蒸架並加 250ml 水。包好鋁箔紙的布丁盒放蒸架上。選 Steam 或 Manual 低壓 14 分鐘，結束後自然洩壓 15 分鐘。比蒸鍋更均勻，出鍋完美如鏡面！","en":"Instant Pot Variation: Add 250ml water to inner pot with trivet. Place foil-covered llanera on trivet. Steam on Low Pressure for 14 mins, followed by 15 mins natural release. Mirror-like perfection every time!","fil":"Instant Pot: Maglagay ng 250ml tubig at patungan. Ilagay ang llanera at i-set sa Low Pressure nang 14 minuto, natural release 15 minuto.","ja":"電気圧力鍋設定：水250mlと蒸し台を入れ、ホイルを巻いた型を置きます。低圧で14分調理し、15分蒸らして減圧。蒸し器より安定して鏡面に仕上がります。","ko":"인스턴트팟 설정: 물 250ml와 찜망을 넣고 호일로 싼 틀을 올립니다. 저압 14분 조리 후 15분 자연 감압합니다."}}]}],"troubleshooting":[{"id":"bubbly-texture","problem":{"zh-TW":"切開後內部有許多蜂窩孔洞，口感粗糙","en":"Custard has ugly bubbles/holes and grainy texture","fil":"May mga butas-butas sa loob ng flan","ja":"すだち（気泡の穴）ができて口当たりがザラつく","ko":"단면에 구멍이 숭숭 뚫려 식감이 거칠음"},"cause":{"zh-TW":"蒸烤火候過大（水沸騰翻滾過猛），或過篩不夠徹底","en":"Steaming heat was too high, or mixture was whipped aggressively","fil":"Masyadong malakas ang apoy habang ini-steam","ja":"蒸す火力が強すぎて内部が沸騰してしまったため","ko":"찜기의 불이 너무 세서 반죽이 끓어올랐거나 덜 걸렀음"},"solution":{"zh-TW":"蒸煮時務必保持「中微火」，水面微微冒小泡即可，不可大滾；必須過篩 3 遍並用鋁箔紙緊密封住模口。","en":"Keep steam on gentle medium-low simmer. Never let water boil aggressively. Always strain 3 times and foil tightly.","fil":"Hinaan ang apoy sa katamtaman lamang at salain nang mabuti.","ja":"グラグラ沸騰させず、フツフツと静かに湯気が立つ中弱火を保ちます。アルミホイル密閉と3回濾しを徹底してください。","ko":"물이 요동치지 않게 중약불을 유지하고, 반드시 3번 체에 거르고 호일로 빈틈없이 감싸주세요."}}],"proTips":[{"zh-TW":"【金桔皮去腥點睛秘方】：在濃郁的純蛋黃與煉乳液中，磨入微量新鮮四季柑桔皮屑（Calamansi Zest），柑橘天然精油能完美消除生蛋黃的腥重，帶來優雅高貴的清爽後韻！","en":"Calamansi Zest Magic: Grate a whisper of fresh green calamansi lime zest into your yolk mix. The citrus oils neutralize egginess, imparting an aristocratic floral aroma!","fil":"Tip ng Kusinero: Maglagay ng kaunting gadgad na balat ng kalamansi upang mawala ang lansa ng itlog at maging mabango.","ja":"柑橘ピールの魔法：カラマンシー（またはスダチ）の皮をごく微量すりおろして加えると、濃厚な卵黄の生臭さが消え、爽やかな高級感が生まれます。","ko":"깔라만시 제스트 비법: 신선한 깔라만시 껍질을 아주 살짝 갈아 넣어보세요. 노른자 특유의 비린내를 완벽히 잡고 상큼한 귀족의 풍미를 더해줍니다."}]},{"country":"ph","id":"pancit-bihon","slug":"pancit-bihon","title":{"zh-TW":"長壽吉祥菲式炒米粉 (Pancit Bihon Guisado)","en":"Festive Filipino Stir-Fried Rice Vermicelli (Pancit Bihon)","fil":"Pancit Bihon Guisado (Pang-Haba ng Buhay)","ja":"本場パンシット・ビホン（長寿を祝うフィリピン風焼きビーフン）","ko":"필리핀식 잔치 볶음 쌀국수 판싯 비혼"},"subtitle":{"zh-TW":"生日慶典長壽象徵・吸飽雞高湯精華・鮮蝦五花肉高麗菜爆炒・四季桔靈魂點睛","en":"Celebration Staple Symbolizing Long Life: Rice Vermicelli Soaked in Rich Broth, Pork & Crisp Veggies","fil":"Tradisyunal na handa sa kaarawan na may hipon, baboy, repolyo at kalamansi","ja":"誕生日に欠かせない長寿のシンボル。鶏出汁の旨味を吸った麺にカラマンシーを搾って","ko":"장수를 기원하는 생일상 필수 메뉴, 진한 닭 육수를 머금은 쌀국수와 신선한 채소 볶음"},"tagline":{"zh-TW":"過生日絕不能切斷的幸運米粉！擠上新鮮金桔汁，鮮爽乾香無比","en":"Never cut the noodles—they represent long life! Finished with a zesty squeeze of calamansi","fil":"Bawal putulin ang noodles para sa mahabang buhay; mas masarap kapag may kalamansi","ja":"麺を切らずに食べるのが長寿の習わし。柑橘の酸味と香ばしい醤油の風味が抜群","ko":"장수를 위해 면을 절대 자르지 않는 전통! 새콤한 깔라만시를 둘러 먹으면 무한 흡입"},"heroImage":"/images/ph/pancit-bihon.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":15,"defaultServings":4,"caloriesPerServing":390,"category":"mains","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"岷倫洛華人街傳入並全菲普及 (Binondo Chinatown, Manila)","en":"Binondo Chinatown, Manila","fil":"Binondo at Buong Kapuluan","ja":"マニラ中華街（ビノンド）発祥・全国普及","ko":"마닐라 비논도 차이나타운"},"famousStreetMarkets":[{"zh-TW":"岷倫洛新春老街食檔","en":"Binondo Food Alleyways","fil":"Ongpin St., Binondo","ja":"ビノンド・オングピン通り","ko":"비논도 옹핀 거리"},{"zh-TW":"全菲各式家庭生日宴席","en":"Every Filipino birthday fiesta table","fil":"Handaan sa kaarawan","ja":"フィリピン全土の誕生日祝宴","ko":"필리핀 전역 생일 잔칫상"}],"historyStory":{"zh-TW":"Pancit 源自閩南語「便食」（Piān-ê-si̍t，意為快速方便的食物）。華人移民將炒米粉手藝傳給菲律賓人後，當地人將其昇華為生日慶典象徵「長壽（Haba ng buhay）」的吉祥菜餚。傳統習俗中炒米粉絕對不能用剪刀剪斷！每一盤熱騰騰出鍋的 Pancit，必定堆滿配料並附上切半的青金桔。","en":"Pancit stems from the Hokkien Chinese phrase \"pian-e-sit\" (convenient cooked food). Local Filipinos embraced it as an auspicious birthday dish symbolizing long life and prosperity. By tradition, you must NEVER cut the noodles while cooking or eating. Served with halved fresh calamansi to cut through the savory umami.","fil":"Galing sa salitang Hokkien na nangangahulugang lutong mabilis. Naging simbolo ng mahabang buhay sa kaarawan kaya bawal putulin ang noodles.","ja":"福建語の「便食（手軽な食事）」が語源。マニラに定着後、麺の長さが長寿を表すとして誕生日や祝い事の象徴的料理となりました。麺を切らないのが縁起担ぎの伝統です。","ko":"푸젠 방언의 \"간편한 음식\"에서 유래했으며, 국수의 긴 면발이 무병장수를 상징하여 생일 파티의 필수 전통 요리가 되었습니다. 조리할 때 면을 자르지 않는 것이 철칙입니다."},"filipinoScript":"Pancit Bihon Guisado","filipinoPhonetics":"Pahn-seet Bee-hon Gee-sah-doh","audioPronunciationText":"Pabili po ng isang bilao ng masarap na Pancit Bihon!"},"ingredients":[{"id":"bihon-noodles","name":{"zh-TW":"優質菲式米粉 (Bihon Rice Vermicelli)","en":"Filipino Bihon Rice Vermicelli","fil":"Bihon Noodles","ja":"フィリピン産 ビーフン（米粉麺）","ko":"비혼 쌀국수 면 (버미첼리)"},"amount":250,"unitMetric":"g","unitUS":"9 oz","isKeyFlavor":true,"filipinoName":"Bihon","filipinoPronunciation":"Bee-hon"},{"id":"chicken-shreds","name":{"zh-TW":"熟雞絲或五花肉絲","en":"Shredded Chicken Breast or Sliced Pork","fil":"Himay na Manok o Baboy","ja":"ほぐし鶏胸肉または豚肉細切り","ko":"찢은 닭가슴살 또는 얇게 썬 돼지고기"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","filipinoName":"Manok / Baboy","filipinoPronunciation":"Mah-nok / Bah-boy"},{"id":"shrimp","name":{"zh-TW":"鮮蝦仁 (開背去蝦線)","en":"Fresh Shrimps (Peeled & deveined)","fil":"Sariwang Hipon","ja":"むきエビ","ko":"손질한 칵테일 새우"},"amount":100,"unitMetric":"g","unitUS":"3.5 oz","filipinoName":"Hipon","filipinoPronunciation":"Hee-pon"},{"id":"cabbage","name":{"zh-TW":"高麗菜 (切粗絲)","en":"Green Cabbage (Shredded)","fil":"Repolyo","ja":"キャベツ（ざく切り）","ko":"양배추 (굵게 채 썰기)"},"amount":150,"unitMetric":"g","unitUS":"5.3 oz","filipinoName":"Repolyo","filipinoPronunciation":"Reh-pol-yoh"},{"id":"carrot","name":{"zh-TW":"胡蘿蔔 (切細絲)","en":"Carrot (Julienned)","fil":"Karot","ja":"人参（千切り）","ko":"당근 (채 썰기)"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Karot","filipinoPronunciation":"Kah-rot"},{"id":"snow-peas","name":{"zh-TW":"荷蘭豆 / 甜豆 (去老筋)","en":"Snow Peas / Snap Peas (Chicharo)","fil":"Chicharo","ja":"サヤエンドウ","ko":"스노우피 / 깍지완두"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","filipinoName":"Chicharo","filipinoPronunciation":"Chee-chah-roh"},{"id":"chicken-broth","name":{"zh-TW":"高鮮雞高湯 (煨煮米粉用)","en":"Rich Chicken Broth","fil":"Sabaw ng Manok","ja":"鶏ガラスープ","ko":"진한 닭 육수"},"amount":500,"unitMetric":"ml","unitUS":"2 cups","isKeyFlavor":true,"filipinoName":"Sabaw","filipinoPronunciation":"Sah-baw"},{"id":"soy-sauce","name":{"zh-TW":"純釀造醬油","en":"Soy Sauce (Toyo)","fil":"Toyo","ja":"醤油","ko":"간장"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"oyster-sauce","name":{"zh-TW":"蠔油","en":"Oyster Sauce","fil":"Oyster Sauce","ja":"オイスターソース","ko":"굴소스"},"amount":1.5,"unitMetric":"tbsp","unitUS":"1.5 tbsp","filipinoName":"Oyster Sauce","filipinoPronunciation":"Oyster Sauce"},{"id":"calamansi","name":{"zh-TW":"新鮮四季柑桔 (切半盛盤)","en":"Fresh Calamansi (Halved for serving)","fil":"Sariwang Kalamansi","ja":"カラマンシー（半分に切る）","ko":"신선한 깔라만시 (반으로 자름)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Kalamansi","filipinoPronunciation":"Kah-lah-mahn-see"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"熱鑊爆炒肉絲、蝦仁與爽脆蔬菜","en":"Sauté Aromatics, Meats & Vegetables","fil":"Igisa ang Bawang, Karne, Hipon at Gulay","ja":"肉、エビ、野菜を強火で香ばしく炒める","ko":"고기, 새우, 채소를 센 불에 볶아내기"},"instruction":{"zh-TW":"大炒鍋熱油，下蒜末與洋蔥絲爆香。加入五花肉絲、雞絲與鮮蝦仁大火翻炒至變色。下胡蘿蔔絲、荷蘭豆與高麗菜大火快炒 1.5 分鐘斷生。加入 2 大匙醬油與 1.5 大匙蠔油翻勻。盛出一半的炒蔬菜肉絲備用（留作最後蓋頂裝飾）。","en":"In a hot wok, sauté minced garlic and sliced onions. Add pork, shredded chicken, and shrimp; stir-fry over high heat until browned. Toss in carrots, snow peas, and cabbage for 1.5 mins until tender-crisp. Season with soy sauce and oyster sauce. Scoop out half of the sautéed toppings and set aside for the topping garnish.","fil":"Painitin ang mantika sa kawali, igisa ang bawang at sibuyas. Ilagay ang baboy, manok, at hipon. Ihalo ang gulay at toyo. Itabi ang kalahati para sa ibabaw.","ja":"中華鍋に油を熱し、ニンニクと玉ねぎを炒めます。豚肉、鶏肉、エビを加え強火で炒め、人参、キャベツ、スナップエンドウをサッと炒め合わせます。醤油とオイスターソースで味付けし、具材の半分を仕上げのトッピング用に取り分けておきます。","ko":"팬에 마늘과 양파를 볶다가 고기와 새우를 넣어 볶습니다. 당근, 완두, 양배추를 넣고 간장과 굴소스로 간합니다. 토핑용으로 고명 절반을 따로 덜어둡니다."},"durationSeconds":240,"image":"/images/ph/pancit-bihon-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"注入熱雞高湯煮沸，下米粉吸飽湯汁","en":"Pour Broth & Simmer Bihon until Liquid Absorbs","fil":"Ibuhos ang Sabaw at Ilagay ang Bihon Noodles","ja":"スープを注ぎ、ビーフンに旨味を吸わせる","ko":"닭 육수를 붓고 끓여 쌀국수에 국물 스며들게 하기"},"instruction":{"zh-TW":"鍋中剩餘的蔬菜底料中倒入 500ml 鮮熱雞高湯，大火煮沸。將乾米粉【直接放入滾湯中（無須提前泡軟！）】，用筷子不斷翻動按壓，讓米粉如海綿般在 3-4 分鐘內將濃郁鮮美的雞高湯完全吸飽收乾！","en":"Pour 500ml of hot chicken broth into the pan with the remaining veggies. Bring to rolling boil. Add dry bihon noodles [NO NEED TO PRE-SOAK!]. Use tongs/chopsticks to submerge and toss constantly for 3-4 mins until noodles absorb ALL the savory broth and swell tender.","fil":"Ibuhos ang 500ml sabaw ng manok sa kawali. Kapag kumukulo na, ilagay ang tuyong bihon (hindi na kailangang ibabad). Haluin hanggang masipsip ang sabaw.","ja":"鍋に残った具材に熱い鶏スープ500mlを注ぎ沸騰させます。乾燥ビーフンを【水戻しせず直接投入！】。箸でスープに沈めながら3〜4分混ぜ、麺にスープの旨味を一滴残らず吸わせます。","ko":"냄비에 뜨거운 닭 육수 500ml를 붓고 끓입니다. 마른 비혼 쌀국수를 【불리지 않고 바로 넣어】 국물이 완전히 흡수될 때까지 3~4분간 저어줍니다."},"durationSeconds":240,"image":"/images/ph/pancit-bihon-step2.jpg","crucialTips":{"zh-TW":"乾米粉直接下滾湯煮，能最大限度吸收雞高湯與蔬菜精華；若事先泡水，米粉吸滿白水就無法吸收醬汁了！","en":"Never soak bihon in cold water first! Adding dry noodles forces them to drink the savory chicken broth instead of plain water.","fil":"Huwag ibabad sa tubig ang bihon bago lutuin upang sabaw ng manok ang kanyang masipsip.","ja":"ビーフンを事前に水に浸さないこと！乾いたままスープに入れることで、鶏出汁の旨味だけを凝縮して吸い込みます。","ko":"면을 미리 찬물에 불리지 마세요! 마른 상태로 넣어야 맹물이 아닌 맛있는 닭 육수를 고스란히 머금습니다."}},{"stepNumber":3,"title":{"zh-TW":"大火翻勻收乾，擺上頂層配料與金桔","en":"Toss Dry over High Heat & Garnish with Calamansi","fil":"Haluin at Ipatong ang Gulay at Sariwang Kalamansi","ja":"強火で水分を飛ばし、具材と柑橘を盛り付ける","ko":"센 불에 수분을 날리고 고명과 깔라만시 얹어 완성"},"instruction":{"zh-TW":"湯汁收乾後轉大火翻炒 1 分鐘逼出鑊氣。關火盛入大圓盤中，將剛才預留的一半鮮蝦、肉絲與翠綠蔬菜鋪在最頂層。四周擺上切半的四季柑桔（Calamansi）。食用前親手擠上果汁拌勻，鮮香撲鼻！","en":"Toss over high heat for 1 min to achieve wok-hei aroma. Transfer to a large serving platter, arrange the reserved colorful toppings on top, and flank with halved fresh calamansi limes. Squeeze citrus juice generously right before digging in!","fil":"Haluin nang mabilis sa malakas na apoy. Ilagay sa bilao o malaking plato, ipatong ang natirang sahog sa ibabaw at palamutian ng kalamansi.","ja":"水分が飛んだら強火で1分煽って香ばしさを引き出します。大皿に盛り、取り分けておいた具材を上に飾り、カラマンシーを添えます。果汁をたっぷり絞ってお召し上がりください！","ko":"국물이 다 졸아들면 센 불에 1분간 볶아 불향을 입힙니다. 접시에 담고 덜어둔 고명을 올린 뒤 깔라만시를 둘러줍니다. 즙을 짜서 곁들여 드세요!"},"durationSeconds":120,"image":"/images/ph/pancit-bihon-step3.jpg"}],"troubleshooting":[{"id":"mushy-noodles","problem":{"zh-TW":"米粉糊成一團或斷碎軟爛","en":"Noodles become mushy, soggy, and break into fragments","fil":"Nalabsak at nadurog ang bihon","ja":"ビーフンがドロドロに柔らかくなりすぎて切れてしまう","ko":"국수가 떡지고 뚝뚝 끊어지며 물러짐"},"cause":{"zh-TW":"高湯加太多，或事先把米粉泡水太久導致吸水過量","en":"Too much broth or noodles were pre-soaked for too long","fil":"Napasobra sa sabaw o nababad sa tubig ang noodles","ja":"スープの量が多すぎたか、茹ですぎが原因","ko":"육수 양이 너무 많았거나 조리 시간이 길었음"},"solution":{"zh-TW":"250g 乾米粉精準搭配 500ml 高湯；米粉吸飽湯水後立即轉大火翻炒收乾，切忌久燜。","en":"Follow strict ratio: 250g dry bihon to 500ml broth. Toss on high heat as soon as liquid is absorbed.","fil":"Tamang sukad ng sabaw (500ml sa 250g na bihon).","ja":"乾麺250gに対しスープ500mlの黄金比を守り、水分を吸ったら強火でサッと炒り上げます。","ko":"마른 면 250g당 육수 500ml 비율을 지키고, 국물이 졸아들면 즉시 센 불에 볶아 수분을 날려주세요."}}],"proTips":[{"zh-TW":"【長壽祝福不切麵】：在菲律賓文化中，端上桌的炒米粉代表祝福主人與壽星「長命百歲」，因此烹飪與夾取時絕對不要剪斷麵條，整根吸吮最幸運！","en":"Do Not Cut the Strands: Long noodles equal a long, prosperous life! Always serve strands intact to honor this ancient and joyous Filipino birthday tradition.","fil":"Huwag gupitin ang noodles upang maging mahaba ang buhay ng may kaarawan.","ja":"麺を切らない掟：長い麺は長寿の証。お祝いの席ではハサミで切らず、長いまま盛り付けてツルツルといただくのが縁起物です。","ko":"면을 자르지 마세요: 긴 면발은 긴 수명과 복을 의미합니다. 절대 면을 가위로 자르지 말고 길게 드시는 것이 전통입니다."}]},{"country":"ph","id":"turon","slug":"turon","title":{"zh-TW":"焦糖香蕉波羅蜜炸春捲 (Turon)","en":"Crispy Caramelized Banana Spring Rolls (Turon)","fil":"Turon na may Saging Saba at Langka","ja":"本場トゥロン（サババナナとパラミツの焦がし黒糖揚げ春巻き）","ko":"바삭한 캐러멜 바나나 튀김 춘권 투론 (Turon)"},"subtitle":{"zh-TW":"街頭最銷魂下午茶・糖漬芭蕉與濃香波羅蜜・外層薄脆琉璃焦糖外殼","en":"The Ultimate Afternoon Street Snack: Ripe Saba Bananas & Sweet Jackfruit in Glass-Brittle Caramel Crust","fil":"Paboritong meryenda sa hapon na may malutong na arnibal sa labas at matamis na saba sa loob","ja":"外側はパリパリの琥珀色カラメル！中は熱々とろけるバナナと芳醇なジャックフルーツ","ko":"겉은 탕후루처럼 파삭한 캐러멜 크러스트, 속은 부드럽고 달콤한 바나나와 잭프루트"},"tagline":{"zh-TW":"一口咬下如玻璃糖衣般碎裂爆脆，內餡軟糯熱燙、果香四溢的國民甜點","en":"Shatteringly crisp sugar glaze outside, molten sweet banana inside","fil":"Napakalutong ng bawat kagat, lalong masarap kapag may kasamang sorbetes","ja":"屋台の甘い香りに誘われる国民的おやつ。一口かじればカリッと心地よい音が響きます","ko":"한 입 베어 물면 바삭한 설탕 코팅이 와삭 부서지는 필리핀 대표 길거리 간식"},"heroImage":"/images/ph/turon.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":12,"defaultServings":4,"caloriesPerServing":280,"category":"desserts","dietaryTags":["classic","vegetarian","vegan"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"全菲律賓城鄉街巷流動手推車 (Street Cart Merienda)","en":"Across the Philippine archipelago as a classic 3 PM Merienda snack","fil":"Lahat ng Kanto sa Pilipinas (Paboritong Meryenda)","ja":"フィリピン全土の街角スナック（3時のミリエンダ＝おやつ）","ko":"필리핀 전역 길거리 간식 (오후 3시 메리엔다 간식)"},"famousStreetMarkets":[{"zh-TW":"馬尼拉大學周邊路邊攤車","en":"University belt street carts, Manila","fil":"U-Belt Maynila","ja":"マニラ大学街屋台","ko":"마닐라 대학가 길거리 카트"},{"zh-TW":"奎阿坡市場小吃攤","en":"Quiapo afternoon merienda stalls","fil":"Quiapo sa hapon","ja":"キアポ午後屋台","ko":"퀴아포 오후 간식 노점"}],"historyStory":{"zh-TW":"Turon（在某些地區也稱 Lumpiang Saging）起源於菲律賓盛產芭蕉的鄉村社區。種植農民將過剩的料理芭蕉（Saba）切片，裹上紅糖，包進薄春捲皮中油炸，並在起鍋前將紅糖直接撒入滾油，使糖漿瞬間焦糖化並緊緊吸附在春捲皮外層，形成如琥珀琉璃般的脆殼。加入金黃波羅蜜絲（Langka）更成為奢華升級版！","en":"Born in rural Philippine communities with abundant plantain groves, farming families rolled sliced Saba bananas in brown sugar, wrapped them in spring roll skins, and fried them. The brilliant street vendor innovation was melting brown sugar straight into the hot oil so it forms a candy-shell glass glaze on the outside!","fil":"Nagsimula sa mga probinsya kung saan marami ang saging na saba. Paboritong meryenda ng mga Pilipino na pinatamis ng asukal na pula at pinalamanan ng langka.","ja":"バナナ農村の知恵から生まれた国民的おやつ。油の中に直接黒糖を投入して外側に飴状のパリパリコーティングを施すのが屋台秘伝の技法です。","ko":"사바 바나나가 풍부한 시골에서 시작된 간식으로, 튀김기름에 흑설탕을 직접 넣어 춘권피 겉면에 바삭한 유리알 캐러멜 코팅을 입히는 것이 특징입니다."},"filipinoScript":"Turon na may Langka","filipinoPhonetics":"Too-ron nah may Lang-kah","audioPronunciationText":"Manong, pabili po ng apat na bagong pritong mainit na Turon!"},"ingredients":[{"id":"saba-bananas","name":{"zh-TW":"菲律賓料理芭蕉 (Saba Plantains，縱向對半剖開)","en":"Saba Bananas / Plantains (Sliced lengthwise in half)","fil":"Saging na Saba (Hati sa gitna)","ja":"サババナナ（フィリピン産調理用バナナ、縦半分に切る）","ko":"사바 바나나 (플랜틴, 세로로 반 가름)"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Saging na Saba","filipinoPronunciation":"Sah-geeng nang Sah-bah"},{"id":"jackfruit","name":{"zh-TW":"熟甜波羅蜜絲 (Langka)","en":"Ripe Sweet Jackfruit strips (Langka)","fil":"Minatamis na Langka","ja":"ジャックフルーツ果肉（細切り）","ko":"달콤한 잭프루트 (채 썬 것)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"filipinoName":"Langka","filipinoPronunciation":"Lang-kah"},{"id":"brown-sugar","name":{"zh-TW":"黑糖或二砂糖 (裹香蕉與焦糖脆殼用)","en":"Dark Brown Sugar (for dusting and caramel glaze)","fil":"Pulang Asukal","ja":"黒糖または三温糖","ko":"흑설탕 (바나나 버무림 및 캐러멜용)"},"amount":100,"unitMetric":"g","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Asukal na Pula","filipinoPronunciation":"Ah-soo-kal nah Poo-lah"},{"id":"spring-roll-wrappers","name":{"zh-TW":"薄春捲皮","en":"Spring Roll / Lumpia Wrappers","fil":"Pabalat ng Lumpia","ja":"春巻きの皮","ko":"춘권피"},"amount":8,"unitMetric":"sheet","unitUS":"sheet","filipinoName":"Pabalat ng Lumpia","filipinoPronunciation":"Pah-bah-laht nang Loom-pyah"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"芭蕉裹滿黑糖並鋪上金黃波羅蜜","en":"Dredge Bananas in Sugar & Top with Jackfruit","fil":"Pagulungin ang Saging sa Asukal at Lagyan ng Langka","ja":"バナナに黒糖をまぶし、パラミツを添える","ko":"바나나에 흑설탕을 듬뿍 묻히고 잭프루트 얹기"},"instruction":{"zh-TW":"將成熟微甜的 Saba 芭蕉縱向對剖成兩半。盤中倒入黑糖，將每一片芭蕉在黑糖中翻滾裹上一層厚厚的糖衣。取一張春捲皮，放上一片裹糖芭蕉，在芭蕉上方鋪入 2-3 條金黃甜波羅蜜絲（Langka）。","en":"Cut ripe Saba bananas in half lengthwise. Roll each banana slice generously in brown sugar until completely coated. Place one sugar-dusted banana slice onto a spring roll wrapper, and arrange 2-3 strips of fragrant sweet jackfruit (langka) on top.","fil":"Hatiin ang saging sa gitna. Pagulungin sa pulang asukal. Ilagay sa pabalat ng lumpia at patungan ng 2-3 pirasong langka.","ja":"サババナナを縦半分に切ります。黒糖を全体にたっぷりまぶします。春巻きの皮の中央に置き、上に細切りのパラミツ（ジャックフルーツ）を2〜3本のせます。","ko":"사바 바나나를 세로로 반 자릅니다. 흑설탕 위에 굴려 설탕옷을 입힌 뒤, 춘권피 위에 올리고 그 위에 향긋한 잭프루트 2~3줄을 얹어줍니다."},"durationSeconds":180,"image":"/images/ph/turon-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"緊密捲起春捲皮封口","en":"Wrap Firmly & Seal Edges with Water","fil":"Balutin nang Mahigpit at I-seal Gamit ang Tubig","ja":"端を折り込んでしっかり巻き、水で糊付けする","ko":"단단히 말아서 물로 끝부분 붙이기"},"instruction":{"zh-TW":"將春捲皮底端往上折包住芭蕉，兩側向內折緊，緊密向前滾捲成工整的扁長方形春捲。封口處抹上少許清水黏合。重複完成所有香蕉捲。","en":"Fold the bottom edge over the banana, tuck in both left and right sides tightly, and roll forward snugly into a neat envelope roll. Dab the final edge with water to seal firmly.","fil":"Irolyo nang mahigpit ang pabalat, itiklop ang magkabilang gilid, at lagyan ng kaunting tubig sa dulo para sumara.","ja":"下から折り上げ、両端をたたんでキツネ色に揚がるよう隙間なく巻き上げます。巻き終わりに水を塗って密着させます。","ko":"아랫부분을 접어 올리고 양옆을 접은 뒤 단단하게 말아줍니다. 끝부분에 물을 발라 풀리지 않게 봉합합니다."},"durationSeconds":240,"image":"/images/ph/turon-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"油鍋爆香焦糖，滾上琉璃脆糖衣或氣炸","en":"Deep Fry with Floating Caramel or Air Fry","fil":"Iprito at Pahiran ng Tunaw na Asukal sa Mantika","ja":"油の中に黒糖を入れて揚げ、表面にカラメルをまとわせる","ko":"기름에 설탕을 녹여 튀기며 바삭한 캐러멜 옷 입히기"},"instruction":{"zh-TW":"【街頭傳奇焦糖法】中火熱油鍋至 170°C，下香蕉捲炸 2 分鐘。關鍵時刻來了！【在油鍋周圍撒入 2 大匙黑糖】。黑糖遇熱油會融化浮在油面上，此時用筷子不斷滾動香蕉捲，讓漂浮的熔融黑糖均勻附著在外皮上！炸至春捲金黃、焦糖發脆即可夾出，放在防黏網架上晾涼。【氣炸鍋模式請參見切換】。","en":"Traditional Street Caramel Technique: Heat oil to 170°C (340°F). Fry rolls for 2 mins. NOW THE SECRET: Sprinkle 2 tbsp brown sugar directly into the hot oil! As the sugar melts and floats, roll the turon continuously so the molten caramel clings to the outside shell. Transfer to a rack to harden into a brittle candy shell!","fil":"Iprito ang turon nang 2 minuto. Budburan ng 2 kutsaritang asukal na pula ang mantika habang nagpiprito para dumikit ang arnibal sa balat.","ja":"【屋台秘伝の技】油を170℃に熱し2分揚げます。ここで【油の中に直接黒糖大さじ2を投入！】。溶けて浮き上がってきたカラメルを絡めるように転がしながら揚げ、飴状の皮に仕上げます。網の上で冷ますとパリパリに固まります。","ko":"【노점 비법】 170도 기름에 2분간 튀긴 뒤, 【기름 속에 흑설탕 2큰술을 솔솔 뿌립니다】! 녹아 떠오른 캐러멜에 춘권을 굴려 겉면에 달콤한 탕후루 코팅을 입혀줍니다."},"durationSeconds":300,"image":"/images/ph/turon-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 195°C (385°F) for 8-10 mins (Brush with oil & melted brown sugar)","instructionOverride":{"zh-TW":"氣炸鍋模式：將香蕉捲表面刷上一層油，再刷上一層厚厚的黑糖水（或滾一層黑糖粒）。放入氣炸鍋 195°C 氣炸 8-10 分鐘，中途翻面，外皮焦糖融化硬脆，內餡軟甜融化！","en":"Air Fryer Variation: Generously brush rolls with cooking oil, then brush with thick brown sugar syrup or roll in brown sugar. Air fry at 195°C (385°F) for 8-10 mins, turning halfway, until bubbling, golden, and brittle.","fil":"Paraan sa Air Fryer: Pahiran ng mantika at pulang asukal. I-air fry sa 195°C nang 8-10 minuto hanggang lumutong.","ja":"ノンフライヤー設定：表面に油を塗り、黒糖シロップ（または黒糖）をまぶして195℃で8〜10分加熱。カラメルがカリッと仕上がります。","ko":"에어프라이어 설정: 표면에 오일을 바르고 흑설탕 시럽을 덧바른 뒤 195°C에서 8~10분간 구워 바삭한 캐러멜 옷을 완성합니다."}}]}],"troubleshooting":[{"id":"soggy-crust","problem":{"zh-TW":"出鍋後外皮迅速回軟，焦糖黏糊不脆","en":"Caramel remains sticky and crust turns soggy quickly","fil":"Malagkit at hindi naging malutong ang balat","ja":"揚げた後にすぐ皮がシナシナになってカリッとしない","ko":"튀긴 후 껍질이 금방 눅눅해지고 바삭하지 않음"},"cause":{"zh-TW":"出鍋後直接重疊堆在吸油紙上，熱水氣悶軟了外皮","en":"Piled on top of each other over paper towels, trapping steam","fil":"Pinagpatong-patong habang mainit kaya nagpawis","ja":"揚げたてをペーパーの上に重ねて置き、湯気で湿気てしまったため","ko":"뜨거운 상태에서 키친타월 위에 겹쳐 쌓아 수증기가 갇혔음"},"solution":{"zh-TW":"出鍋後切記不要用廚房紙巾平放重疊！必須單獨立在金屬冷卻網架上分開擺放，通風 2 分鐘後焦糖就會瞬間冷卻硬化如玻璃！","en":"Never pile turon on paper towels! Place them separately on a wire cooling rack so hot air escapes and the caramel crystallizes into glass.","fil":"Patuyuin sa wire rack nang nakahiwalay upang tumigas ang arnibal.","ja":"ペーパーには置かず、網の上に重ならないよう立てて冷まします。空気に触れると2分でガラスのようにパリッと固まります。","ko":"키친타월에 겹쳐두지 말고 식힘망 위에 따로따로 올려두세요. 2분만 한 김 식히면 유리알처럼 딱딱하게 굳습니다."}}],"proTips":[{"zh-TW":"【冰火交融奢華吃法】：剛出鍋還燙口的酥脆 Turon 橫切成兩段，盤中挖上一大球冰涼透頂的香草或紫薯冰淇淋（Turon a la Mode），淋上一點海鹽焦糖醬，冰與火在口中交融，是五星級飯店下午茶極致之作！","en":"Turon à la Mode: Serve scorching hot, freshly fried turon alongside a massive scoop of cold vanilla or ube ice cream. The temperature contrast between molten caramel and frosty ice cream is pure bliss!","fil":"Turon a la Mode: Napakasarap kapag ipinares ang mainit na turon sa malamig na sorbetes na ube o vanilla!","ja":"トゥロン・ア・ラ・モード：揚げたてアツアツのトゥロンに、冷たいウベアイス（またはバニラアイス）を添えて。熱さと冷たさのコントラストが絶品です！","ko":"투론 아 라 모드: 갓 튀겨 뜨거운 투론 옆에 차가운 우베나 바닐라 아이스크림을 곁들여보세요. 입안에서 펼쳐지는 온냉의 조화가 예술입니다."}]},{"country":"ph","id":"taho","slug":"taho","title":{"zh-TW":"馬尼拉清晨黑糖珍珠豆花 (Warm Taho)","en":"Warm Silken Tofu with Arnibal Syrup & Sago Pearls (Taho)","fil":"Mainit na Taho na may Arnibal at Sago","ja":"本場温かいタホ（黒糖シロップとタピオカのフィリピン風出来立て豆花）","ko":"필리핀 아침의 소울 푸드 따뜻한 타호 (흑당 시럽 타피오카 순두부)"},"subtitle":{"zh-TW":"清晨小巷悠揚叫賣聲・極致嫩滑溫熱豆花・琥珀黑糖蜜與Ｑ彈西米露","en":"The Iconic Street Call of Manila Mornings: Steaming Silken Tofu, Warm Caramel Arnibal & Chewy Sago","fil":"Boses ng magtataho tuwing umaga: \"Taho-ooo!\" na may matamis na arnibal at malambot na sago","ja":"マニラの朝を告げる「タホー！」の掛け声。温かいおぼろ豆腐に黒糖蜜が絡む癒しの味","ko":"골목길을 깨우는 \"타호~!\" 외침. 부드러운 온두부에 달콤한 흑당 시럽과 쫄깃한 사고 펄"},"tagline":{"zh-TW":"挑著扁擔的豆花老爹走遍街頭，捧上一杯暖手暖胃的極致香甜晨光","en":"Hawked from iconic silver aluminum buckets across every Philippine neighborhood at dawn","fil":"Paboritong almusal at meryenda ng mga bata at matanda sa kalsada","ja":"天秤棒を担いだ行商人が売る出来立ての温もり。フィリピン人の朝に欠かせない一杯","ko":"은색 통을 멘 행상 아저씨가 건네는 따스한 아침의 선물, 영혼을 달래주는 달콤함"},"heroImage":"/images/ph/taho.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":15,"defaultServings":2,"caloriesPerServing":210,"category":"desserts","dietaryTags":["classic","vegetarian","vegan","glutenFree"],"supportedCookware":["traditional"],"culture":{"originRegion":{"zh-TW":"馬尼拉老城區與全菲律賓清晨街巷 (Dawn Street Hawkers)","en":"Street corners across the entire Philippine archipelago at dawn","fil":"Bawat Barangay sa Pilipinas tuwing umaga","ja":"フィリピン全土の早朝ストリート","ko":"필리핀 전역 아침 골목길"},"famousStreetMarkets":[{"zh-TW":"馬尼拉黎剎公園晨光街邊","en":"Rizal Park Morning Walk, Manila","fil":"Luneta Park sa umaga","ja":"マニラ・リサール公園","ko":"마닐라 리잘 공원 아침 산책길"},{"zh-TW":"碧瑤市草莓豆花街區 (Baguio Strawberry Taho)","en":"Baguio City Heritage Strawberry Taho Stalls","fil":"Baguio City (Strawberry Taho)","ja":"バギオ市ストロベリー・タホ","ko":"바기오 시티 딸기 타호 거리"}],"historyStory":{"zh-TW":"Taho 源自閩南語的「豆花」（Tāu-hue）。數個世紀前傳入馬尼拉後，演變為極具特色的街頭型態：小販（Magtataho）肩挑一根竹扁擔，兩頭各掛一個圓柱形亮銀色鋁桶，一桶裝著滾燙極嫩的豆腐腦，另一桶裝著煮透的黑色木薯小珍珠（Sago）與深黑濃醇的黑糖蜜（Arnibal）。隨著一聲高亢悠揚的「Taho-ooo!」，居民紛紛帶著馬克杯下樓購買。","en":"Derived from Hokkien \"Tāu-hue\" (soy curd), the Filipino Magtataho (taho peddler) carries two large aluminum tins balanced on a bamboo yoke across his shoulders. One bucket holds steaming silken tofu, while the other holds chewy sago pearls and warm caramelized dark brown sugar syrup (Arnibal). The vendor’s iconic baritone cry of \"Taho-ooo!\" is the sound of Philippine sunrise.","fil":"Galing sa salitang Hokkien na \"tau-hue\". Kilala ang magtataho na may dalang dalawang balde sa pingga habang sumisigaw ng \"Taho!\" sa bawat kanto.","ja":"福建の「豆花（トウファ）」がルーツ。天秤棒の両端にシルバーのバケツを提げ、「タホー！」と朗々と叫びながら歩く行商人は、フィリピンの朝を象徴する詩情あふれる光景です。","ko":"푸젠성 \"두화(豆花)\"에서 시작된 음식으로, 은색 원통 두 개를 멘 행상 아저씨가 \"타호~!\"라고 외치면 집집마다 컵을 들고나와 따끈한 두부를 받아먹는 정겨운 풍경입니다."},"filipinoScript":"Mainit na Taho","filipinoPhonetics":"Mah-ee-neet nah Tah-hoh","audioPronunciationText":"Kuya Magtataho, pabili po ng isang malaking baso ng mainit na Taho!"},"ingredients":[{"id":"silken-tofu","name":{"zh-TW":"超嫩純豆腐花或嫩豆腐 (微波或隔水蒸熱)","en":"Fresh Silken Tofu (steamed warm)","fil":"Malambot na Tokwa (Silken Tofu)","ja":"絹ごし豆腐または出来立ておぼろ豆腐（温める）","ko":"부드러운 순두부 또는 연두부 (따뜻하게 데움)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Tofu / Tokwa","filipinoPronunciation":"Toh-foo"},{"id":"dark-brown-sugar","name":{"zh-TW":"深黑紅糖或黑糖 (Muscovado / Dark Brown Sugar)","en":"Dark Muscovado / Dark Brown Sugar","fil":"Pulang Asukal (Muscovado)","ja":"黒糖またはモスコバド糖（未精製黒糖）","ko":"다크 머스코바도 흑설탕"},"amount":150,"unitMetric":"g","unitUS":"0.75 cup","isKeyFlavor":true,"filipinoName":"Muscovado","filipinoPronunciation":"Moos-koh-vah-doh"},{"id":"pandan-leaf","name":{"zh-TW":"新鮮香蘭葉 (打結，熬煮黑糖蜜香氣靈魂)","en":"Fresh Pandan Leaf (Knotted for syrup infusion)","fil":"Dahon ng Pandan","ja":"パンダンリーフ（結び目を作る）","ko":"판단 잎 (묶어서 시럽에 향 내기)"},"amount":1,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Dahon ng Pandan","filipinoPronunciation":"Dah-hon nang Pahn-dahn"},{"id":"sago-pearls","name":{"zh-TW":"小粒西米露 / 珍珠 (煮透至半透明Ｑ彈)","en":"Small Sago / Tapioca Pearls (Cooked tender)","fil":"Sago Pearls","ja":"小粒タピオカパール（透明に茹でる）","ko":"작은 사고 펄 / 타피오카 (투명하게 삶은 것)"},"amount":80,"unitMetric":"g","unitUS":"2.8 oz","isKeyFlavor":true,"filipinoName":"Sago","filipinoPronunciation":"Sah-goh"},{"id":"water-for-syrup","name":{"zh-TW":"清水 (煮黑糖蜜)","en":"Water (for Arnibal brown syrup)","fil":"Tubig para sa Arnibal","ja":"水（黒糖シロップ用）","ko":"물 (시럽용)"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","filipinoName":"Tubig","filipinoPronunciation":"Too-beeg"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火細熬香蘭黑糖蜜 (Arnibal)","en":"Simmer Aromatic Pandan Brown Sugar Syrup (Arnibal)","fil":"Lutuin ang Mabangong Arnibal na may Pandan","ja":"パンダン香る黒糖シロップ（アルニバル）を作る","ko":"향긋한 판단 흑당 시럽(아르니발) 졸이기"},"instruction":{"zh-TW":"小奶鍋中倒入黑糖與 120ml 清水，放入洗淨打結的香蘭葉。小火慢熬約 6-8 分鐘，輕輕攪拌讓黑糖完全融化，糖漿變濃稠油亮，散發出深邃的焦糖與香蘭芬芳。關火夾出香蘭葉，黑糖蜜保溫備用。","en":"In a small saucepan, combine dark brown/muscovado sugar, water, and knotted pandan leaf. Simmer gently over medium-low heat for 6-8 mins until sugar dissolves into a glossy, fragrant amber syrup (Arnibal). Discard pandan leaf and keep warm.","fil":"Pakuluan ang asukal na pula, tubig, at dahon ng pandan nang 6-8 minuto sa mahinang apoy hanggang maging malapot na arnibal.","ja":"小鍋に黒糖、水、結んだパンダンリーフを入れ、弱火で6〜8分加熱。黒糖が溶けてツヤのあるシロップになったら葉を取り出します。","ko":"냄비에 흑설탕, 물, 묶은 판단 잎을 넣고 약불에서 6~8분간 끓여 윤기 흐르는 흑당 시럽을 완성합니다."},"durationSeconds":480,"image":"/images/ph/taho-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"溫熱嫩豆腐花並瀝乾水氣","en":"Steam Warm Silken Tofu & Drain Liquid","fil":"Painitin ang Tokwa sa Pasingawan","ja":"絹ごし豆腐を蒸して温め、余分な水気を切る","ko":"순두부를 따뜻하게 찌고 수분 빼기"},"instruction":{"zh-TW":"將新鮮嫩豆腐或盒裝超嫩豆腐移入碗中，隔水蒸 5-8 分鐘（或用微波爐中火溫熱 1.5 分鐘）。倒掉蒸出多餘的清水，保持豆腐溫熱軟嫩。","en":"Steam silken tofu in a heatproof dish for 5-8 mins (or microwave gently on medium power for 1.5 mins) until hot. Gently drain any excess standing water.","fil":"Pasingawan ang tokwa nang 5-8 minuto hanggang uminit. Itapon ang labis na tubig.","ja":"絹豆腐を耐熱皿にのせ、蒸し器で5〜8分温めます（電子レンジで1分半でも可）。出た水分は優しく捨てます。","ko":"순두부를 그릇에 담아 찜기에 5~8분간 쪄서 따끈하게 데웁니다. 배어 나온 물은 살짝 따라 버립니다."},"durationSeconds":360,"image":"/images/ph/taho-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"神級手法片豆花，澆淋黑糖蜜與西米露","en":"Skim Thin Flakes, Pour Arnibal & Sago","fil":"Hiwain nang Maninipis at Lagyan ng Arnibal at Sago","ja":"薄くすくい取り、黒糖蜜とタピオカをたっぷり注ぐ","ko":"숟가락으로 얇게 포 뜨듯 떠 담고 시럽과 펄 붓기"},"instruction":{"zh-TW":"仿效路邊豆花老爹的手法：用一把大平金屬勺，沿著溫熱豆腐表面【輕輕片出一層層薄如花瓣的滑嫩豆花】，舀入玻璃杯中。在頂層淋上 2-3 大匙熱騰騰的濃香黑糖蜜，再鋪上兩大勺晶瑩剔透的Ｑ彈西米露。拿小勺子趁熱大口舀著吃！","en":"Mimic the street vendor’s artistry: using a flat metal spoon, skim paper-thin layers of steaming silken tofu and layer them into clear glasses. Drizzle generously with 2-3 tbsp of warm dark Arnibal syrup and spoon glistening sago pearls on top. Eat warm with a spoon or drink straight from the cup!","fil":"Gamit ang kutsara, hiwain nang manipis ang tokwa at ilagay sa baso. Buhusan ng mainit na arnibal at sago bago higupin!","ja":"平らなスプーンで豆腐の表面を花びらのように薄く削ぎ取ってグラスに入れます。熱々の黒糖蜜を回しかけ、タピオカをトッピング。スプーンで混ぜながら温かいうちにいただきます！","ko":"납작한 스푼으로 순두부를 꽃잎처럼 얇게 포 떠서 잔에 담습니다. 따뜻한 흑당 시럽 3큰술을 두르고 쫄깃한 사고 펄을 얹어 따스하게 즐깁니다."},"durationSeconds":120,"image":"/images/ph/taho-step3.jpg"}],"troubleshooting":[{"id":"watery-tofu","problem":{"zh-TW":"黑糖蜜淋上去後立刻被多餘水分稀釋，變得清淡如水","en":"Arnibal syrup dilutes into thin brown water","fil":"Naging matabang ang arnibal dahil sa tubig ng tokwa","ja":"豆腐から水分が出て黒糖シロップが薄まってしまう","ko":"두부의 수분 때문에 흑당 시럽이 묽어져 밍밍함"},"cause":{"zh-TW":"豆腐加熱後未徹底倒掉滲出的多餘水分","en":"Did not drain excess liquid released from steaming tofu","fil":"Hindi naitapon ang tubig na lumabas sa tokwa","ja":"温めた豆腐から出た水分をしっかり捨てなかったため","ko":"두부를 데운 뒤 스며 나온 물기를 따라내지 않았음"},"solution":{"zh-TW":"片豆花前，務必將碗傾斜，用湯匙擋住豆腐，把蒸出來的白水倒得乾乾淨淨；黑糖蜜熬濃稠一些，才能附著在豆腐表面。","en":"Tilt the dish and thoroughly pour off all released liquid before scooping. Simmer your Arnibal until thick and glossy.","fil":"Itapon ang tubig ng tokwa bago ilagay sa baso.","ja":"器を傾けて豆腐から出た水分を完全に捨ててから盛り付けます。シロップも少し煮詰めてとろみをつけると絡みが良くなります。","ko":"두부를 뜨기 전 그릇을 기울여 나온 물을 말끔히 버리고, 시럽을 진하게 졸여주세요."}}],"proTips":[{"zh-TW":"【碧瑤草莓豆花驚喜】：在菲律賓避暑勝地碧瑤市（Baguio），小販會在黑糖蜜中加入大量新鮮高山草莓果泥熬製成「Strawberry Taho」，粉嫩果香酸甜交織，若有新鮮草莓不妨試試這款傳奇變奏！","en":"Baguio Strawberry Twist: In the mountain cool of Baguio City, vendors infuse the syrup with fresh mountain strawberries. Stir in 2 tbsp fresh strawberry puree for Baguio’s world-famous Strawberry Taho!","fil":"Tip sa Baguio: Maglagay ng sariwang strawberry jam o syrup para sa tanyag na Strawberry Taho ng Baguio City.","ja":"バギオの苺タホ変奏曲：高原都市バギオでは黒糖のかわりにフレッシュな苺ジャムシロップをかける「ストロベリー・タホ」が大人気です！","ko":"바기오 딸기 타호: 고산 휴양지 바기오에서는 흑당 대신 생딸기 퓌레 시럽을 넣어 만든 \"딸기 타호\"가 명물입니다. 딸기잼을 더해 상큼하게 즐겨보세요."}]},{"country":"ph","id":"arroz-caldo","slug":"arroz-caldo","title":{"zh-TW":"暖胃薑香土雞稠粥 (Arroz Caldo)","en":"Gingery Chicken Rice Porridge (Arroz Caldo)","fil":"Arroz Caldo na may Manok at Bawang","ja":"本場アロス・カルド（黄金にんにくと生姜が香るフィリピン鶏粥）","ko":"황금 마늘과 생강 향 가득한 필리핀 닭죽 아로스 칼도 (Arroz Caldo)"},"subtitle":{"zh-TW":"西班牙命名的暖心國粥・老薑麻油土雞慢火熬糜・滿滿黃金蒜酥與四季柑","en":"Soul-Warming Comfort: Jasmine & Glutinous Rice Simmered with Ginger, Chicken, Toasted Garlic & Egg","fil":"Pampainit sa tag-ulan na may maraming toasted garlic, itlog, at kalamansi","ja":"雨の日や朝食に染み渡る極上の温もり。香ばしいフライドガーリックと柑橘を添えて","ko":"비 오는 날과 아침을 따스하게 채워주는 소울 푸드, 바삭한 마늘 플레이크와 삶은 달걀"},"tagline":{"zh-TW":"雨季與生病時最渴望的一碗溫柔，一口吃下生薑的辛香與蒜酥的酥脆","en":"The ultimate comfort bowl for rainy mornings and recovering spirits","fil":"Gamot sa lagnat at pampalakas ng katawan na laging lutong-bahay","ja":"生姜のポカポカ感とカリカリにんにくの芳ばしさ。一口で身体の芯から温まる魔法の粥","ko":"원기 회복과 감기 예방에 으뜸인 영양 닭죽, 은은한 생강 향과 상큼한 깔라만시의 조화"},"heroImage":"/images/ph/arroz-caldo.jpg","difficulty":"easy","prepTimeMinutes":15,"cookTimeMinutes":35,"defaultServings":4,"caloriesPerServing":350,"category":"soups","dietaryTags":["classic","glutenFree"],"supportedCookware":["traditional","instantPot"],"culture":{"originRegion":{"zh-TW":"西西里與華人潮州廣東魚生雞粥在馬尼拉的融合 (Filipino-Chinese-Spanish Heritage)","en":"Crossroads of Chinese Congee and Spanish nomenclature in colonial Manila","fil":"Maynila at Katagalugan","ja":"マニラ発祥（中華の白粥文化とスペイン語名の融合）","ko":"마닐라 (중국 광둥식 죽과 스페인 명칭이 결합된 역사적 음식)"},"famousStreetMarkets":[{"zh-TW":"奎阿坡清晨 Lugawan 粥攤","en":"Quiapo morning Lugawan street stalls","fil":"Lugawan sa Quiapo","ja":"キアポ朝粥屋台","ko":"퀴아포 아침 죽 노점"},{"zh-TW":"馬尼拉夜市街頭 Gotohan 宵夜檔","en":"24/7 Gotohan & Lugawan joints, Manila","fil":"Gotohan sa kanto","ja":"24時間営業のお粥スタンド","ko":"마닐라 24시간 죽 전문 식당"}],"historyStory":{"zh-TW":"菲律賓本土本就有傳統白米煮粥（Lugaw）的習俗。華人移民將廣東雞粥（Chicken Congee）引進馬尼拉後，西班牙殖民者因喜愛這道暖胃美食，為其取了西語名字「Arroz Caldo」（字面意為「熱湯米飯」）。菲律賓人巧妙加入本土老薑、紅木籽天然微黃色澤、炸至金黃脆香的大蒜碎（Toasted Garlic）與四季柑桔汁，誕生了這道舉世無雙的療癒暖心熱粥！","en":"While indigenous Filipinos ate plain rice porridge called \"Lugaw\", Chinese immigrants introduced ginger chicken congee. Spanish colonizers fell in love with it and christened it \"Arroz Caldo\" (literally \"broth rice\"). Filipinos elevated it with generous julienned ginger, safflower/annatto for a gentle golden hue, mountain of toasted garlic bits, and a spritz of fresh calamansi.","fil":"Galing sa pinaghalong lugaw ng mga Tsino at pangalang Kastila. Kilala sa saganang luya, kasubha (safflower), at maraming toasted garlic.","ja":"中華系の生姜鶏粥にスペイン人が「アロス・カルド（温かいスープ飯）」と名付け、フィリピン風に大量のガーリックフライと柑橘、サフラン（またはベニバナ）の黄色い彩りを加えて完成させました。","ko":"중국식 닭죽에 스페인어로 \"따뜻한 국밥\"이란 뜻의 이름을 붙였으며, 필리핀식으로 생강을 듬뿍 넣고 황금 마늘 후레이크와 깔라만시를 곁들여 먹습니다."},"filipinoScript":"Arroz Caldo na may Manok","filipinoPhonetics":"Ah-ros Kahl-doh nah may Mah-nok","audioPronunciationText":"Pabili po ng mainit na Arroz Caldo na may maraming toasted garlic at itlog!"},"ingredients":[{"id":"chicken-cuts","name":{"zh-TW":"帶骨雞腿塊 (切小塊，熬出甘美雞湯)","en":"Bone-in Chicken Thighs (Chopped into bite-sized pieces)","fil":"Hita ng Manok","ja":"骨付き鶏もも肉（一口大ぶつ切り）","ko":"토막 닭다리살 (뼈 있는 것)"},"amount":400,"unitMetric":"g","unitUS":"14 oz","isKeyFlavor":true,"filipinoName":"Manok","filipinoPronunciation":"Mah-nok"},{"id":"glutinous-jasmine-rice","name":{"zh-TW":"糯米與茉莉香米 (1:1 混搭，兼具黏糯稠度與米香)","en":"Glutinous Rice + Jasmine Rice (1:1 mix for perfect texture)","fil":"Malagkit at Regular na Bigas","ja":"もち米とうるち米のブレンド（1:1）","ko":"찹쌀과 멥쌀 (1:1 혼합으로 쫀득하고 부드러운 식감)"},"amount":150,"unitMetric":"g","unitUS":"0.75 cup","isKeyFlavor":true,"filipinoName":"Malagkit","filipinoPronunciation":"Mah-lahg-keet"},{"id":"ginger","name":{"zh-TW":"新鮮老薑 (去皮切大量粗絲，暖胃精華)","en":"Fresh Ginger (Julienned generously)","fil":"Maraming Luya","ja":"生姜（たっぷりの千切り）","ko":"신선한 생강 (굵게 채 썬 것 듬뿍)"},"amount":50,"unitMetric":"g","unitUS":"1.8 oz","isKeyFlavor":true,"filipinoName":"Luya","filipinoPronunciation":"Loo-yah"},{"id":"garlic-crispy","name":{"zh-TW":"大蒜末 (慢火慢炸成黃金蒜酥)","en":"Garlic (Minced & fried into crispy golden bits)","fil":"Toasted Garlic (Bawang)","ja":"フライドガーリック（こんがりキツネ色に炒める）","ko":"다진 마늘 (바삭하게 튀겨 골든 갈릭 플레이크 만들기)"},"amount":8,"unitMetric":"clove","unitUS":"clove","isKeyFlavor":true,"filipinoName":"Bawang","filipinoPronunciation":"Bah-wang"},{"id":"patis","name":{"zh-TW":"菲律賓純魚露 (Patis)","en":"Fish Sauce (Patis)","fil":"Patis","ja":"魚醤（パティス）","ko":"피시소스 (파티스)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Patis","filipinoPronunciation":"Pah-tees"},{"id":"water-broth","name":{"zh-TW":"清水或雞高湯","en":"Water or Chicken Stock","fil":"Tubig o Sabaw","ja":"水または鶏ガラスープ","ko":"물 또는 닭 육수"},"amount":1200,"unitMetric":"ml","unitUS":"5 cups","filipinoName":"Tubig","filipinoPronunciation":"Too-beeg"},{"id":"boiled-eggs","name":{"zh-TW":"水煮蛋 (對半剖開作為配料)","en":"Hard-boiled Eggs (Halved)","fil":"Nilagang Itlog","ja":"ゆで卵（半分に切る）","ko":"삶은 달걀 (반 가름)"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Nilagang Itlog","filipinoPronunciation":"Nee-lah-gahng Eet-log"},{"id":"calamansi-scallions","name":{"zh-TW":"新鮮四季柑桔與青蔥花","en":"Fresh Calamansi & Chopped Scallions","fil":"Kalamansi at Dahon ng Sibuyas","ja":"カラマンシーと小口ねぎ","ko":"깔라만시와 송송 썬 파"},"amount":4,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Kalamansi","filipinoPronunciation":"Kah-lah-mahn-see"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火炸出招牌黃金香脆蒜酥","en":"Fry Minced Garlic into Crunchy Golden Bits","fil":"Iprito ang Bawang Hanggang Maging Toasted Garlic","ja":"弱火でにんにくを炒め、黄金色のガーリックチップを作る","ko":"약불에 마늘을 볶아 황금빛 바삭한 갈릭 후레이크 만들기"},"instruction":{"zh-TW":"深鍋中倒入 3 大匙油，冷油下入細蒜末，轉中小火慢炸。不斷攪動讓蒜末受熱均勻，直到變成金黃香脆（切記不要炸焦）。迅速用漏勺撈出蒜酥瀝油備用，鍋中留下的就是香氣逼人的「黃金大蒜油」！","en":"Add 3 tbsp oil into a deep pot. Add minced garlic to cool oil and cook gently over medium-low heat, stirring constantly until golden brown and crispy (do not burn!). Scoop out the crispy garlic bits onto paper towels. Keep the fragrant garlic oil in the pot!","fil":"Painitin ang mantika at dahan-dahang iprito ang bawang sa mahinang apoy hanggang maging toasted. Itabi ang bawang ngunit iwan ang mantika sa kaldero.","ja":"鍋に油大さじ3と刻みニンニクを入れ、弱火でじっくり炒めます。キツネ色でカリカリになったらニンニクをすくい出して油を切り、鍋には香ばしいガーリックオイルを残します。","ko":"냄비에 기름 3큰술과 다진 마늘을 넣고 약불에서 타지 않게 저어가며 노릇하게 튀깁니다. 바삭해진 마늘 칩은 건져내고, 냄비에는 마늘 기름을 남겨둡니다."},"durationSeconds":240,"image":"/images/ph/arroz-caldo-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"大蒜油煸炒生薑絲、雞肉與米粒","en":"Sauté Ginger, Chicken & Rice in Garlic Oil","fil":"Igisa ang Luya, Manok, at Bigas sa Mantika ng Bawang","ja":"ガーリックオイルで生姜、鶏肉、米を炒める","ko":"마늘 기름에 채 썬 생강, 닭고기, 쌀을 볶기"},"instruction":{"zh-TW":"利用鍋中留下的蒜油，中大火爆香大量生薑絲與洋蔥丁約 1 分鐘，直到生薑辛香四溢。加入雞腿肉塊翻炒至肉色發白，調入 2 大匙魚露（Patis）。倒入淘洗瀝乾的糯米與香米，翻炒 1.5 分鐘讓每顆米粒裹上一層金黃蒜油與雞油。","en":"In the reserved garlic oil, sauté the mounds of ginger matchsticks and onions for 1 min until aromatic. Add chicken pieces and sear until opaque. Season with 2 tbsp fish sauce. Add drained rice and stir-fry for 1.5 mins until glistening with fragrant chicken fat.","fil":"Igisa ang maraming luya at sibuyas sa mantika ng bawang. Ilagay ang manok at patis. Ihalo ang bigas nang 1-2 minuto.","ja":"残ったガーリックオイルで千切り生姜と玉ねぎを強火で炒め、鶏肉を加えて炒め合わせます。魚醤大さじ2を加え、洗った米を投入して全体に油が回るまで炒めます。","ko":"마늘 기름에 채 썬 생강을 듬뿍 넣고 볶다가 닭고기를 넣어 볶습니다. 피시소스를 넣고 쌀을 넣어 기름에 1분간 고소하게 볶아줍니다."},"durationSeconds":240,"image":"/images/ph/arroz-caldo-step2.jpg"},{"stepNumber":3,"title":{"zh-TW":"加高湯慢火熬煮成綿密稠粥，盛盤撒蒜酥","en":"Simmer into Silky Porridge & Garnish Generously","fil":"Pakuluan Hanggang Lumapot at Lagyan ng Sahog sa Ibabaw","ja":"スープを注いでとろとろに煮込み、トッピングを飾る","ko":"육수를 붓고 푹 끓여 부드러운 죽으로 완성 후 고명 얹기"},"instruction":{"zh-TW":"倒入 1200ml 清水或雞高湯，大火煮滾後轉小火。加蓋微掩慢熬 20-25 分鐘，期間每隔幾分鐘順鍋底攪拌防止米粒黏底，直到米粒爆開、湯汁呈現濃郁綿滑的白金稠粥（若喜歡偏黃色澤可加微量紅木油或薑黃）。大碗盛出，擺上半顆水煮蛋、撒上堆成小山的黃金蒜酥、青蔥花，旁邊放上切半金桔，擠汁拌食！","en":"Pour in 1200ml water or chicken broth, bring to a boil, then turn to low heat. Partially cover and simmer for 20-25 mins, stirring occasionally to prevent sticking, until the rice grains bloom into a rich, silky porridge. Ladle into deep bowls, top with boiled egg halves, heaps of crispy toasted garlic, fresh green onions, and fresh calamansi limes!","fil":"Ibuhos ang 1200ml tubig o sabaw. Hinaan ang apoy at pakuluan nang 20-25 minuto habang hinahalo. Ihain sa mangkok na may nilagang itlog, maraming toasted garlic, dahon ng sibuyas, at kalamansi.","ja":"水（またはスープ）1200mlを注ぎ、沸騰したら弱火にして底が焦げ付かないよう時々混ぜながら20〜25分煮込みます。お米が花開いてトロトロになったら器に盛り、ゆで卵、山盛りのフライドガーリック、ネギをのせ、カラマンシーを搾って完成！","ko":"물 1200ml를 붓고 끓으면 약불로 줄여 눋지 않게 저어가며 20~25분간 푹 끓입니다. 죽이 뽀얗고 걸쭉해지면 그릇에 담고 삶은 달걀, 듬뿍 올린 마늘 플레이크, 파, 깔라만시를 얹어냅니다."},"durationSeconds":1500,"image":"/images/ph/arroz-caldo-step3.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Porridge Setting for 20 mins (natural release)","instructionOverride":{"zh-TW":"壓力鍋模式：用 Sauté 檔炸蒜酥並煸炒生薑、雞肉與生米。注入 1000ml 水，選 Porridge 檔高壓 20 分鐘，自然洩壓 15 分鐘。開蓋攪拌，米粒完全化糜，超級香濃省心！","en":"Instant Pot Variation: Use Sauté mode to fry garlic, then sauté ginger, chicken, and rice. Add 1000ml water, seal, and cook on Porridge mode (High Pressure) for 20 mins with 15 mins natural release. Velvety congee in one touch!","fil":"Instant Pot: Gamitin ang Sauté mode para sa bawang, luya, at manok. Ilagay ang 1000ml tubig at i-set sa Porridge mode nang 20 minuto.","ja":"電気圧力鍋設定：Sautéモードでニンニクと生姜、鶏肉、米を炒め、水1000mlを加えPorridgeモードで20分加圧後、15分蒸らして減圧。驚くほどなめらかなお粥が完成します。","ko":"인스턴트팟 설정: 볶음 모드로 마늘과 생강, 닭고기, 쌀을 볶고 물 1000ml를 붓습니다. 죽(Porridge) 모드로 20분 조리 후 15분 자연 감압합니다."}}]}],"troubleshooting":[{"id":"too-thick","problem":{"zh-TW":"粥放涼後變得太過濃稠厚重，像米糊一塊塊","en":"Porridge thickens into dense solid paste after resting","fil":"Naging sobrang lapot at nanigas ang arroz caldo","ja":"冷めるとお粥が固まりすぎてボテボテになってしまう","ko":"시간이 지나면서 죽이 너무 뻑뻑하게 굳음"},"cause":{"zh-TW":"糯米吸水性極強，靜置過程中持續膨脹","en":"Glutinous rice continually drinks moisture as starch cools","fil":"Mabilis sumipsip ng sabaw ang malagkit na bigas","ja":"もち米のでんぷんが冷めるにつれて水分を吸い尽くすため","ko":"찹쌀의 전분 성분이 식으면서 수분을 모두 흡수함"},"solution":{"zh-TW":"吃之前倒入半碗熱雞高湯或熱水，用小火微沸攪拌 1 分鐘，立刻恢復絲絨般順滑質地。","en":"Stir in 1/2 cup boiling water or warm chicken stock over low heat for 1 minute before serving.","fil":"Magdagdag ng kaunting mainit na sabaw o tubig habang pinapainit.","ja":"食べる直前に熱いスープかお湯を半カップ足し、弱火で1分かき混ぜると滑らかさが蘇ります。","ko":"드실 때 따뜻한 육수나 물 반 컵을 붓고 1분간 저어가며 데워주면 부드러움이 살아납니다."}}],"proTips":[{"zh-TW":"【老薑量加倍與現擠金桔】：正宗 Arroz Caldo 的靈魂在於「生薑不能省」！大量的生薑絲在熱粥中燉透，辛香完全釋入湯糜；碗邊擠入 2 顆四季柑（Calamansi），果酸瞬間解開肉脂，讓整碗粥變得無比清雅鮮活！","en":"The Golden Duo: Never be shy with ginger—the sharper the ginger warmth, the more restorative the porridge. Always finish with 2 freshly squeezed calamansi limes to electrify the savory chicken broth!","fil":"Tip ng Kusinero: Damihan ang luya at huwag kalimutang pigain ang kalamansi bago higupin ang sabaw.","ja":"生姜と柑橘の相乗効果：生姜はケチらずたっぷり千切りを入れるのが本場流。そして食べる直前にカラマンシー果汁を絞ることで、重たい鶏粥が驚くほど軽やかで爽快な味へと昇華します！","ko":"황금 비결: 생강을 아끼지 말고 듬뿍 넣어야 깊은 맛이 납니다. 드시기 직전 신선한 깔라만시를 2개 짜 넣으면 닭죽의 느끼함이 사라지고 놀랍도록 상쾌해집니다."}]},{"country":"ph","id":"crispy-pata","slug":"crispy-pata","title":{"zh-TW":"金黃爆脆菲式炸大蹄膀 (Crispy Pata)","en":"Crispy Deep-Fried Pork Knuckle (Crispy Pata)","fil":"Malutong na Crispy Pata","ja":"本場クリスピー・パタ（フィリピン風豚すね肉の黄金カリカリ揚げ）","ko":"겉바속촉 끝판왕 필리핀식 튀긴 족발 크리스피 파타 (Crispy Pata)"},"subtitle":{"zh-TW":"菲律賓大菜鎮桌之寶・外皮如爆米花般酥脆破裂・骨肉酥爛多汁・蒜辣醋汁絕配","en":"The Grand King of Filipino Banquets: Blistered Shattering Skin & Fall-Apart Tender Pork with Spiced Soya-Vinegar Dip","fil":"Bida sa bawat inuman at handaan na may sobrang lutong na balat at malambot na laman","ja":"フィリピン大宴会の花形料理！弾けるようにクリスピーな皮と、ジューシーにとろける肉","ko":"필리핀 대형 축제의 하이라이트! 크래커처럼 바삭한 껍질과 촉촉하게 녹아내리는 육즙"},"tagline":{"zh-TW":"先香料慢燉、風乾後高溫爆炸，咔嚓一聲脆響震撼全場的終極肉食狂歡","en":"Simmered in aromatics, thoroughly dried, and deep-fried to astronomical crunch","fil":"Paboritong pulutan na kapag kinagat ay maririnig ang tunog ng lutong","ja":"ハーブで煮込み、乾燥させてから揚げる伝統技法。パリッという音が部屋中に響きます","ko":"향신채로 푹 삶은 뒤 바싹 말려 튀겨내는 필리핀 정통 명물 요리, 극강의 바삭함"},"heroImage":"/images/ph/crispy-pata.jpg","difficulty":"hard","prepTimeMinutes":30,"cookTimeMinutes":60,"defaultServings":6,"caloriesPerServing":680,"category":"sizzling","dietaryTags":["classic"],"supportedCookware":["traditional","airFryer","instantPot"],"culture":{"originRegion":{"zh-TW":"卡洛奧坎市 Barrio Fiesta 餐廳 (Caloocan, Metro Manila, 1950s)","en":"Invented in the 1950s by Rodolfo Ongpauco at Barrio Fiesta, Caloocan","fil":"Inimbento sa Barrio Fiesta sa Caloocan noong 1950s","ja":"1950年代にマニラ近郊カローカン市の名店バリオ・フィエスタで誕生","ko":"1950년대 마닐라 칼로오칸의 유명 레스토랑 바리오 피에스타에서 개발"},"famousStreetMarkets":[{"zh-TW":"馬尼拉湯都 Ugbo 深夜排檔","en":"Ugbo Food Strip, Tondo","fil":"Ugbo St., Tondo Maynila","ja":"マニラ・トンド地区屋台街","ko":"마닐라 톤도 우그보 야시장"},{"zh-TW":"全菲各大 Barrio Fiesta 老字號","en":"Barrio Fiesta Heritage Restaurants","fil":"Barrio Fiesta Restaurants","ja":"バリオ・フィエスタ各店","ko":"바리오 피에스타 본점"}],"historyStory":{"zh-TW":"1950年代，馬尼拉卡洛奧坎市 Barrio Fiesta 餐廳創辦人之子 Rodolfo Ongpauco，看到廚房裡被丟棄的大量豬蹄膀（Pata），靈機一動將其先放入大鍋加入洋蔥、蒜瓣、月桂葉慢燉至軟爛，冷藏風乾後丟進大油鍋炸製。沒想到豬皮在高溫油中瞬間爆裂起密集氣泡，酥脆如薄脆餅乾，骨肉多汁滑嫩，從此成為轟動全國的菲律賓頂級國菜！","en":"In the 1950s, Rodolfo Ongpauco—son of the founders of Barrio Fiesta in Caloocan—experimented with surplus pig knuckles. He boiled the knuckle tender with bay leaves, star anise, garlic and peppercorns, dried it in the fridge, and deep-fried it until the skin puffed into millions of brittle blisters. It revolutionized Filipino party food forever!","fil":"Inimbento ni Rodolfo Ongpauco noong dekada 50 gamit ang tinapong pata ng baboy. Pinasikat sa Barrio Fiesta at naging pambansang paborito sa salo-salo.","ja":"1950年代にバリオ・フィエスタの息子ロドルフォが余った豚すね肉を煮込んで乾燥させ、強火で揚げたところ、皮が奇跡的なカリカリ食感になり爆発的人気メニューとなりました。","ko":"1950년대 바리오 피에스타 창업주의 아들이 남은 돼지 족발을 향신료와 삶아 바싹 말린 뒤 튀겨내어, 크래커처럼 바삭한 껍질을 가진 혁명적인 요리로 탄생시켰습니다."},"filipinoScript":"Crispy Pata na Baboy","filipinoPhonetics":"Krees-pee Pah-tah nah Bah-boy","audioPronunciationText":"Isang buong malutong na Crispy Pata po at maraming sawsawan na Toyomansi!"},"ingredients":[{"id":"pork-knuckle","name":{"zh-TW":"整隻帶皮豬前蹄或後蹄膀 (Pork Shank/Hock)","en":"Whole Pork Hock / Knuckle (Skin-on)","fil":"Buong Pata ng Baboy","ja":"皮付き豚すね肉（豚足・ホック丸ごと1本）","ko":"통 돼지 장족/앞다리 족발 (껍질 있는 것)"},"amount":1400,"unitMetric":"g","unitUS":"3 lb","isKeyFlavor":true,"filipinoName":"Pata ng Baboy","filipinoPronunciation":"Pah-tah nang Bah-boy"},{"id":"bay-leaves","name":{"zh-TW":"乾燥月桂葉","en":"Dried Bay Leaves","fil":"Dahon ng Laurel","ja":"ローリエ","ko":"월계수 잎"},"amount":5,"unitMetric":"piece","unitUS":"piece","filipinoName":"Dahon ng Laurel","filipinoPronunciation":"Dah-hon nang Lah-oo-rel"},{"id":"star-anise","name":{"zh-TW":"八角茴香 (燉煮去腥增香)","en":"Star Anise","fil":"Star Anise","ja":"八角（スターアニス）","ko":"팔각"},"amount":2,"unitMetric":"piece","unitUS":"piece","filipinoName":"Star Anise","filipinoPronunciation":"Star Anise"},{"id":"garlic-onion","name":{"zh-TW":"整頭大蒜與洋蔥塊","en":"Whole Head Garlic & 1 Onion (for broth)","fil":"Bawang at Sibuyas","ja":"丸ごとにんにくと玉ねぎ","ko":"통마늘 1통과 양파 1개"},"amount":1,"unitMetric":"piece","unitUS":"piece","filipinoName":"Bawang at Sibuyas","filipinoPronunciation":"Bah-wang at See-boo-yas"},{"id":"peppercorns","name":{"zh-TW":"整顆原粒黑胡椒","en":"Whole Black Peppercorns","fil":"Pamintang Buo","ja":"粒黒胡椒","ko":"통흑후추"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","filipinoName":"Paminta","filipinoPronunciation":"Pah-meen-tah"},{"id":"coarse-salt","name":{"zh-TW":"粗海鹽 (抹皮與燉肉用)","en":"Coarse Sea Salt (for boiling & rubbing skin)","fil":"Asin","ja":"粗塩","ko":"굵은 천일염"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Asin","filipinoPronunciation":"Ah-seen"},{"id":"cane-vinegar-dip","name":{"zh-TW":"甘蔗醋與醬油蒜辣沾醬 (Toyomansi-Suka Dip)","en":"Cane Vinegar, Soy Sauce, Calamansi, Garlic & Chili Dip","fil":"Toyo, Suka, Kalamansi, Bawang at Sili (Toyomansi)","ja":"サトウキビ酢・醤油・カラマンシー・ニンニク唐辛子ダレ","ko":"사탕수수 식초, 간장, 깔라만시, 마늘, 고추 특제 디핑 소스"},"amount":120,"unitMetric":"ml","unitUS":"0.5 cup","isKeyFlavor":true,"filipinoName":"Toyomansi Suka","filipinoPronunciation":"Toh-yoh-mahn-see Soo-kah"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"香料水大火慢燉蹄膀至骨肉軟嫩","en":"Simmer Pork Hock with Aromatics until Tender","fil":"Pakuluan ang Pata Kasama ang mga Pampalasa","ja":"香辛野菜と共に豚すね肉を柔らかくなるまで煮込む","ko":"향신료를 넣고 족발을 푹 삶아 부드럽게 만들기"},"instruction":{"zh-TW":"大深鍋中放入洗淨刮除雜毛的整隻豬蹄膀，加清水完全淹沒蹄膀。加入拍扁大蒜、切塊洋蔥、月桂葉、八角、黑胡椒粒與 2 大匙鹽。大火煮沸撈淨浮沫，轉小火加蓋慢燉 1 小時 15 分鐘至 1.5 小時（或使用壓力鍋 35 分鐘），直到筷子能輕易穿透外皮與蹄筋，撈出。","en":"Place the whole cleaned pork knuckle into a large stockpot, submerge in water. Add crushed garlic, onion quarters, bay leaves, star anise, peppercorns, and 2 tbsp salt. Bring to a rapid boil and skim scum. Cover and simmer gently for 75-90 mins (or 35 mins in Instant Pot) until fork-tender but intact. Lift out carefully.","fil":"Pakuluan ang pata sa tubig kasama ang bawang, sibuyas, dahon ng laurel, star anise, paminta, at asin nang 1.5 oras hanggang lumambot nang husto.","ja":"大鍋に豚すね肉を入れ、たっぷりの水、ニンニク、玉ねぎ、ローリエ、八角、黒胡椒、塩を加えます。沸騰させてアクを取り、フタをして弱火で75〜90分（圧力鍋なら35分）皮が柔らかくなるまで煮込みます。","ko":"냄비에 족발과 물을 넉넉히 붓고 마늘, 양파, 월계수 잎, 팔각, 통후추, 소금을 넣습니다. 끓어오르면 거품을 걷어내고 뚜껑 덮어 약불에서 75~90분간(압력솥 35분) 푹 삶아 건져냅니다."},"durationSeconds":5400,"image":"/images/ph/crispy-pata-step1.jpg","cookwareVariations":[{"cookware":"instantPot","tempAndSetting":"Instant Pot: Meat/Stew High Pressure for 35 mins (natural release)","instructionOverride":{"zh-TW":"壓力鍋模式：蹄膀加 1000ml 水與全部香料，蓋上閥門選 Meat/Stew 高壓 35 分鐘，自然洩壓 15 分鐘。肉質酥爛多汁，省下大把時間！","en":"Instant Pot Variation: Add knuckle with 1000ml water and aromatics. Cook on High Pressure for 35 mins, then natural release for 15 mins. Perfect tenderness without hours of simmering!","fil":"Instant Pot: Ilagay ang pata at 1000ml tubig. I-set sa Meat/Stew High Pressure nang 35 minuto.","ja":"電気圧力鍋設定：肉と水1000ml、調味料を入れ高圧で35分加圧後、15分蒸らして減圧します。肉が信じられないほど柔らかくなります。","ko":"인스턴트팟 설정: 족발과 물 1000ml, 향신료를 넣고 고압 35분 조리 후 15분 자연 감압합니다."}}]},{"stepNumber":2,"title":{"zh-TW":"戳洞抹鹽，放冰箱冷藏風乾（極致脆皮秘訣！）","en":"Prick Skin, Rub Salt & Chill Dry in Fridge (The Crunch Secret!)","fil":"Tusukin ang Balat, Lagyan ng Asin at Patuyuin sa Ref","ja":"皮に無数の穴を開け、塩を揉み込み冷蔵庫で乾燥させる","ko":"껍질에 포크로 구멍을 숭숭 내고 소금 발라 냉장고에 말리기 (핵심 비법!)"},"instruction":{"zh-TW":"【關鍵秘訣】：撈出的蹄膀用廚房紙巾徹底擦乾。拿叉子或尖籤在豬皮表面【密集戳出無數微小細孔（不要戳穿到肉）】。在表皮薄薄抹上一層鹽與少許白醋。將蹄膀放在網架上，【放入冰箱冷藏不加蓋風乾至少 4-6 小時或隔夜】。冷風會讓豬皮水分完全蒸發抽乾，呈現皮革般緊繃乾爽狀態！","en":"CRUCIAL CRISP SECRET: Pat hot knuckle completely dry. Using a fork or skewer, poke hundreds of tiny holes across the skin (pricking skin only, not into the deep meat). Rub with a light layer of salt and 1 tbsp vinegar. Place uncovered on a wire rack in the fridge for at least 4-6 hours or overnight. The chilled circulating air completely dehydrates the skin into parchment!","fil":"Patuyuin ang pata gamit ang paper towel. Tusukin ng tinidor ang balat nang maraming beses. Lagyan ng asin at suka, at patuyuin sa ref nang walang takip nang magdamag.","ja":"【最大の秘訣】ペーパーで水分を徹底的に拭き取ります。フォークで皮全体に【無数の小さな穴を開けます】。塩少々と酢を薄く塗り、ラップをせずに冷蔵庫で一晩（最低4時間）風乾させます。皮がカサカサに乾くことで、揚げた時に爆発的なカリカリ感を生みます！","ko":"【바삭함의 비결】 족발 물기를 꼼꼼히 닦고 포크로 껍질 전체에 수백 개의 미세한 구멍을 냅니다. 식초 1큰술과 소금을 얇게 바른 뒤 랩을 씌우지 않고 냉장고에 하룻밤(최소 4시간) 바싹 말립니다."},"durationSeconds":14400,"image":"/images/ph/crispy-pata-step2.jpg","crucialTips":{"zh-TW":"如果豬皮還留有濕氣直接下鍋，不僅不會爆皮，還會劇烈噴油引發危險！徹底風乾的豬皮下鍋才會像米香般膨脹爆脆。","en":"Wet skin causes violent oil splattering and stays leathery. Fully dehydrated skin puffs into crispy glass blisters instantly!","fil":"Mapanganib magprito kapag basa ang balat dahil puputok ang mantika. Kailangang tuyong-tuyo.","ja":"水分が残っていると激しく油がはねて危険な上、皮が硬くなってしまいます。完全に乾かすことが成功への絶対条件です。","ko":"물기가 남은 상태로 튀기면 기름이 사방으로 튀어 위험하며 껍질이 질겨집니다. 표면이 완전히 건조해야 바삭하게 부풉니다."}},{"stepNumber":3,"title":{"zh-TW":"高溫爆炸至金黃爆皮起泡，切塊蘸蒜辣醋","en":"Deep Fry to Blistered Gold or Air Fry to Perfection","fil":"Iprito Hanggang Pumutok ang Balat o I-Air Fry","ja":"高温で揚げて皮を気泡状に弾けさせる（またはエアフライ）","ko":"고온에 튀겨 껍질을 바삭하게 부풀리기 (또는 에어프라이어)"},"instruction":{"zh-TW":"【深鍋油炸法】深鍋倒油燒至 190°C。小心將風乾的蹄膀滑入油鍋，【立即蓋上鍋蓋防油濺！】。保持中大火炸 8-10 分鐘，翻面再炸 8 分鐘，直到整隻蹄膀外皮金黃、起滿細密白色脆泡。撈出立在架上瀝油 5 分鐘。拿大菜刀斬成大塊，外皮咔嚓脆響，配上由甘蔗醋、醬油、金桔、拍扁大蒜與小辣椒調成的專屬 Toyomansi 沾醬！","en":"Traditional Fry: Heat deep oil to 190°C (375°F). Lower dried pork carefully into the oil and IMMEDIATELY COVER WITH LID to contain splatter! Fry 8-10 mins per side until the entire skin erupts into a sea of crispy golden blisters. Rest vertically on a rack for 5 mins. Chop with a cleaver and serve with spiced toyomansi-vinegar dip!","fil":"Iprito sa mainit na mantika (190°C) nang 8-10 minuto bawat gilid. Takpan ang kawali para hindi mapilantikan ng mantika. Hiwain at isawsaw sa toyo-mansi na may suka at sili!","ja":"油を190℃に熱し、肉を静かに入れ【すぐにフタをして油はねを防ぎます！】。両面を8〜10分ずつ揚げ、皮全体が白くプツプツと膨らんだら取り出します。包丁で豪快に切り分け、特製ピリ辛柑橘酢醤油ダレにつけてどうぞ！","ko":"기름을 190도로 달군 뒤 족발을 넣고 【즉시 뚜껑을 덮어 기름 튐을 방지합니다!】 앞뒤로 8~10분씩 튀겨 껍질이 하얗게 부풀어 오르면 건져냅니다. 칼로 큼직하게 썰어 매콤한 토요만시 식초장에 찍어 드세요!"},"durationSeconds":900,"image":"/images/ph/crispy-pata-step3.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 200°C (395°F) for 25-30 mins (zero mess!)","instructionOverride":{"zh-TW":"氣炸鍋模式（居家強烈推薦！）：將風乾的蹄膀表面均勻刷上薄油。放入氣炸籃以 200°C 氣炸 15 分鐘，翻面再刷油氣炸 12-15 分鐘。豬皮在高溫熱風下瘋狂爆出黃金水泡，完全不噴油、廚房乾乾淨淨，酥脆度與油炸一模一樣！","en":"Air Fryer Variation (Home Game-Changer!): Brush the dehydrated pork skin lightly with cooking oil. Place in basket. Air fry at 200°C (395°F) for 15 mins, flip, brush oil, and air fry for another 12-15 mins. The skin erupts into thousands of airy blisters with ZERO grease splatter in your kitchen!","fil":"Paraan sa Air Fryer: Pahiran ng mantika ang tuyong balat. I-air fry sa 200°C nang 15 minuto, baligtarin at i-air fry pa nang 12-15 minuto. Walang talsik ng mantika at kasing lutong ng prito!","ja":"ノンフライヤー設定（家庭に超オススメ！）：風乾させた皮に油を薄く塗り、200℃で15分加熱。裏返して油を塗りさらに12〜15分加熱します。油はねの心配ゼロで、お店レベルのカリカリ爆ぜ皮が再現できます！","ko":"에어프라이어 설정 (가정용 강력 추천!): 말린 족발 껍질에 오일을 바르고 200°C에서 15분 굽습니다. 뒤집어서 오일을 바르고 12~15분간 더 구워주면 기름 튐 전혀 없이 식당 수준의 바삭한 껍질이 완성됩니다!"}}]}],"troubleshooting":[{"id":"skin-hard-like-rock","problem":{"zh-TW":"豬皮炸後堅硬如石，咬不動甚至嗑牙","en":"Pork skin is rock-hard and chewy instead of airy and crispy","fil":"Matigas na parang bato ang balat, hindi malutong","ja":"皮がカチコチに硬くて噛み切れない","ko":"껍질이 바삭하지 않고 돌처럼 딱딱해서 씹기 힘듦"},"cause":{"zh-TW":"第一階段水煮時間不足（豬皮未煮透軟化），或油溫過低導致皮炸乾脫水成了皮革","en":"Did not boil long enough to gelatinize collagen, or frying oil was too cold","fil":"Kulang sa kulo ang pata kaya matigas pa ang balat bago iprito","ja":"下茹で時間が足りずコラーゲンが柔らかくなっていなかったか、油の温度が低すぎたため","ko":"첫 번째 삶는 시간이 부족해 껍질이 덜 물렀거나 튀김 온도가 낮았음"},"solution":{"zh-TW":"水煮或壓力鍋燉煮時，務必確保筷子能輕鬆插透厚皮；且油炸/氣炸必須在 190-200°C 高溫瞬間將皮內水分膨脹炸出爆泡。","en":"Boil until fork-tender so collagen softens completely. Fry or air-fry at 200°C high heat so the skin expands instantaneously.","fil":"Siguraduhing malambot na ang balat bago patuyuin at iprito sa napakainit na mantika.","ja":"下茹での際、箸がスッと通るまで柔らかく煮ること。そして200℃の高温で一気に気泡を爆ぜさせることが重要です。","ko":"젓가락이 껍질을 부드럽게 뚫고 들어갈 때까지 삶아주고, 200도 고온에서 순식간에 껍질을 팽창시켜 튀겨주세요."}}],"proTips":[{"zh-TW":"【老饕配搭】：剛炸好的熱騰騰 Crispy Pata，一定要配上一碗加了大量生蒜末、碎朝天椒與新鮮四季柑橘汁的甘蔗黑醬油（Toyomansi）。將酸辣醬汁澆在酥皮肥肉上，酸爽解膩，一口接一口停不下來！","en":"The Divine Toyomansi Dip: Never eat Crispy Pata without its soulmate dipping bowl: dark soy sauce, cane vinegar, lots of minced raw garlic, crushed bird’s eye chilies, and 3 squeezed calamansi limes. The fiery tartness balances the rich pork crunch impeccably!","fil":"Tip ng Kusinero: Huwag kakalimutan ang sawsawan na toyo, suka, maraming bawang, sili, at kalamansi para sa balanseng sarap.","ja":"秘伝のつけダレ：カリカリの熱々パタには、サトウキビ酢と醤油、たっぷりの生ニンニク、唐辛子、カラマンシー果汁を合わせた特製ダレが必須。濃厚な脂を爽快に流してくれます！","ko":"소울메이트 토요만시 소스: 간장과 식초, 다진 생마늘, 청양고추, 깔라만시를 듬뿍 넣은 전용 소스를 꼭 곁들이세요. 기름진 바삭함을 상큼하게 잡아주어 물리지 않고 계속 들어갑니다."}]},{"country":"ph","id":"fish-balls","slug":"fish-balls","title":{"zh-TW":"街頭手推車炸魚丸與五香卷 (Fish Balls & Kikiam)","en":"Street Cart Fish Balls & Kikiam with Manong’s Sauce","fil":"Street Food Fish Balls at Kikiam na may Manong Sauce","ja":"本場屋台の揚げフィッシュボール＆キキアム（秘伝マノンソース）","ko":"필리핀 길거리 수레 어묵 튀김 & 키키암 (마농 특제 소스)"},"subtitle":{"zh-TW":"馬尼拉街頭靈魂推車小吃・扁平炸魚丸五香肉卷・濃稠甜辣黑糖老爹醬汁","en":"The King of Manila Street Carts: Crispy Flat Fish Balls, Kikiam & the Legendary Brown Starch Sauce","fil":"Ang paboritong tuhog-tuhog sa kanto kasama ang masarap na matamis at maanghang na sawsawan","ja":"放課後や仕事帰りに串で刺して食べる青春の味。甘辛いとろみダレにたっぷり浸して","ko":"하굣길과 퇴근길의 추억, 꼬치로 직접 건져 먹는 바삭한 어묵과 달콤매콤 특제 전분 소스"},"tagline":{"zh-TW":"用長竹籤在沸騰大平底鍋中自己戳丸子，浸進玻璃罐醬汁裡才是正宗街頭吃法","en":"The ultimate interactive street ritual: poke your skewers straight into the vendor’s wok!","fil":"Tusok-tusok sa kawali at sawsaw sa garapon—ang tunay na tatak ng kanto sa Pilipinas","ja":"屋台の大鍋から自分で串で刺して取る「トゥソク・トゥソク（串刺し）」の楽しさ","ko":"끓는 팬에서 꼬치로 직접 건져내어 유리병 소스에 푹 담가 먹는 필리핀만의 길거리 문화"},"heroImage":"/images/ph/fish-balls.jpg","difficulty":"easy","prepTimeMinutes":10,"cookTimeMinutes":10,"defaultServings":3,"caloriesPerServing":240,"category":"streetFood","dietaryTags":["classic","pescatarian"],"supportedCookware":["traditional","airFryer"],"culture":{"originRegion":{"zh-TW":"大馬尼拉所有學校門口與十字路口手推車 (Street Corners of Manila)","en":"Every street corner, church plaza, and school gate across the Philippines","fil":"Bawat Kanto at Tabi ng Paaralan sa Pilipinas","ja":"フィリピン全土の学校前や駅前の手押し車屋台","ko":"필리핀 전역의 학교 앞과 골목길 리어카 노점"},"famousStreetMarkets":[{"zh-TW":"德拉薩大學與聖托馬斯大學美食街","en":"Taft Avenue & UST Food Alleys, Manila","fil":"Taft Avenue at España Maynila","ja":"マニラ大学街タフト通り","ko":"마닐라 타프트 애비뉴 대학가"},{"zh-TW":"奎阿坡 Carriedo 街角手推車","en":"Carriedo street pushcarts, Quiapo","fil":"Carriedo St., Quiapo","ja":"キアポ・カリエド通り","ko":"퀴아포 카리에도 노점"}],"historyStory":{"zh-TW":"菲律賓的炸魚丸（Fish Balls）與閩南潮汕魚丸不同，是壓得扁平圓形、油炸後迅速膨脹隨後微凹的特殊口感。販賣的小販被親切稱為「Manong（老爹）」。食客拿著長竹籤，圍著滾燙的大平底油鍋自行戳取熟透漂浮的魚丸與五香卷（Kikiam），再將整串丸子放進老爹特調的褐色甜辣澱粉醬（Manong Sauce）與辣洋蔥白醋罐中蘸透，這是每個菲律賓人最深刻的集體童年回憶！","en":"Unlike spherical Chinese fish balls, Filipino street fish balls are flattened discs that puff up dramatically when dropped into hot oil and collapse slightly as they crisp. The vendor is affectionately called \"Manong\". Customers perform the \"Tusok-Tusok\" ritual—poking their own skewers into the communal wok and dipping them into giant glass jars of sweet-spicy brown sauce and spiced vinegar!","fil":"Ang fish ball at kikiam ang pinakatanyag na street food sa Pilipinas. Ang \"tusok-tusok\" sa kawali ni Manong at pagsawsaw sa matamis at maanghang na sarsa ang paboritong bonding ng magkakaibigan.","ja":"中華系の魚団子が現地で平たい形に進化。油に入れるとプクッと膨らみ、屋台のおじさん（マノン）の秘伝ダレにつけて食べる「トゥソク・トゥソク（串刺し）」はフィリピン人にとっての青春の味です。","ko":"중국식 어묵이 필리핀에서 납작한 디스크 모양으로 변형된 것. 튀기면 통통하게 부풀어 오르며, 꼬치로 직접 찔러 건진 뒤 마농 특제 브라운 소스에 푹 적셔 먹는 전통이 있습니다."},"filipinoScript":"Fish Balls at Kikiam na may Manong Sauce","filipinoPhonetics":"Fish Balls aht Kee-kyam nah may Mah-nong Sauce","audioPronunciationText":"Manong, magkano po ang isang tuhog ng fish balls at kikiam?"},"ingredients":[{"id":"street-fish-balls","name":{"zh-TW":"菲式扁平街頭炸魚丸 (扁圓形)","en":"Philippine Flat Fish Balls (frozen/chilled pack)","fil":"Fish Balls (Pang-kanto)","ja":"フィリピン風平たいフィッシュボール","ko":"필리핀식 납작 어묵 볼"},"amount":20,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Fish Balls","filipinoPronunciation":"Fish Balls"},{"id":"kikiam","name":{"zh-TW":"街頭五香香腸卷 (Kikiam，源自五香肉卷)","en":"Street-Style Kikiam (Five-Spice Sausage Rolls)","fil":"Kikiam","ja":"キキアム（五香粉香るすり身ソーセージ）","ko":"키키암 (오향 가미 수제 어묵 소시지)"},"amount":10,"unitMetric":"piece","unitUS":"piece","isKeyFlavor":true,"filipinoName":"Kikiam","filipinoPronunciation":"Kee-kyam"},{"id":"brown-sugar-sauce","name":{"zh-TW":"黑糖或紅糖 (Manong 秘醬基底)","en":"Brown Sugar (for Manong Sweet Sauce)","fil":"Pulang Asukal","ja":"黒糖（タレ用）","ko":"흑설탕 (마농 소스용)"},"amount":60,"unitMetric":"g","unitUS":"0.33 cup","isKeyFlavor":true,"filipinoName":"Asukal","filipinoPronunciation":"Ah-soo-kal"},{"id":"soy-sauce","name":{"zh-TW":"純釀醬油","en":"Soy Sauce","fil":"Toyo","ja":"醤油","ko":"간장"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","filipinoName":"Toyo","filipinoPronunciation":"Toh-yoh"},{"id":"cornstarch-sauce","name":{"zh-TW":"玉米粉 (煮出如絲滑膠質的厚稠度)","en":"Cornstarch (slurry for thick glassy texture)","fil":"Cornstarch","ja":"コーンスターチ（濃厚なとろみ用）","ko":"옥수수 전분 (걸쭉한 농도용)"},"amount":2,"unitMetric":"tbsp","unitUS":"2 tbsp","isKeyFlavor":true,"filipinoName":"Cornstarch","filipinoPronunciation":"Corn-starch"},{"id":"garlic-onion-sauce","name":{"zh-TW":"大蒜末、洋蔥碎與紅辣椒圈","en":"Minced Garlic, Onion & Fresh Chilies (for sauce)","fil":"Bawang, Sibuyas, at Siling Labuyo","ja":"みじん切りニンニク、玉ねぎ、唐辛子","ko":"다진 마늘, 양파, 썬 청양고추"},"amount":1,"unitMetric":"tbsp","unitUS":"1 tbsp","filipinoName":"Bawang at Sili","filipinoPronunciation":"Bah-wang aht See-lee"},{"id":"water","name":{"zh-TW":"清水 (煮醬汁用)","en":"Water (for sauce)","fil":"Tubig","ja":"水","ko":"물"},"amount":250,"unitMetric":"ml","unitUS":"1 cup","filipinoName":"Tubig","filipinoPronunciation":"Too-beeg"}],"steps":[{"stepNumber":1,"title":{"zh-TW":"慢火熬煮街頭靈魂「老爹黑糖甜辣濃醬」","en":"Simmer Famous Street Manong Brown Sauce","fil":"Lutuin ang Matamis at Maanghang na Sawsawan ni Manong","ja":"屋台名物「マノン・ブラウンソース（甘辛とろみダレ）」を作る","ko":"전설의 길거리 마농 브라운 소스 졸이기"},"instruction":{"zh-TW":"小鍋中倒入 250ml 清水、黑糖、2 大匙醬油、蒜末、洋蔥碎與剪碎的朝天椒。將玉米粉加少許冷水調勻，邊攪拌邊倒入鍋中。小火加熱不斷慢攪，直到醬汁沸騰、透明稠亮如琥珀色濃糖漿，關火盛入大玻璃罐中放涼。甜、鹹、辛、香，完美還原街頭攤車風味！","en":"In a saucepan, combine water, brown sugar, soy sauce, minced garlic, chopped onion, and chilies. Whisk cornstarch with 3 tbsp water into a slurry, then stir into the pot. Cook over medium-low heat, stirring constantly until bubbling into a thick, glossy mahogany sauce. Pour into a glass jar. Authentic Manong sauce is born!","fil":"Pagsamahin ang tubig, pulang asukal, toyo, bawang, sibuyas, sili, at cornstarch slurry. Pakuluan sa mahinang apoy habang hinahalo hanggang lumapot nang husto.","ja":"小鍋に水、黒糖、醤油、ニンニク、玉ねぎ、唐辛子を合わせます。水溶きコーンスターチを回し入れ、中弱火で混ぜながら艶やかなとろみがつくまで煮詰めます。ガラス瓶に移して完成。","ko":"냄비에 물, 흑설탕, 간장, 마늘, 양파, 고추를 넣고 끓입니다. 전분물을 둘러 넣고 약불에서 주걱으로 저어가며 윤기 나는 걸쭉한 소스로 졸여줍니다."},"durationSeconds":300,"image":"/images/ph/fish-balls-step1.jpg"},{"stepNumber":2,"title":{"zh-TW":"油鍋慢炸魚丸與五香卷，膨脹起脆皮","en":"Deep Fry or Air Fry until Puffy & Golden","fil":"Iprito ang Fish Balls at Kikiam Hanggang Lumobo at Lumutong","ja":"魚団子とキキアムをプクッと膨らむまで揚げる（またはエアフライ）","ko":"어묵과 키키암을 통통하게 부풀 때까지 튀기기"},"instruction":{"zh-TW":"平底油鍋燒熱油至 175°C，下入扁魚丸與 Kikiam。魚丸下鍋後會在熱油中迅速膨脹鼓起成金黃圓球（約 2.5-3 分鐘），外皮變得薄脆硬挺。撈出瀝油。【氣炸鍋模式請參見切換】。","en":"Heat oil in a skillet to 175°C (350°F). Slide in flat fish balls and kikiam. Watch the fish balls puff up dramatically into spheres and turn golden brown with a crispy skin (2.5-3 mins). Drain on wire rack.","fil":"Iprito ang fish balls at kikiam sa mainit na mantika nang 2-3 minuto hanggang lumobo at maging kulay ginto.","ja":"175℃に熱した油にフィッシュボールとキキアムを入れます。丸くプクプクと膨らみ、表面がキツネ色でカリッとなるまで2.5〜3分揚げます。","ko":"175도 기름에 납작 어묵과 키키암을 넣습니다. 2~3분간 튀기면 통통하게 공처럼 부풀어 오르며 바삭해집니다."},"durationSeconds":180,"image":"/images/ph/fish-balls-step2.jpg","cookwareVariations":[{"cookware":"airFryer","tempAndSetting":"Air Fryer: 195°C (385°F) for 6-8 mins (shake halfway)","instructionOverride":{"zh-TW":"氣炸鍋模式：將魚丸與 Kikiam 噴上一層薄油放入氣炸籃，以 195°C 氣炸 6-8 分鐘，中途搖晃炸籃一次，出鍋外脆內彈，完全不油膩！","en":"Air Fryer Variation: Spray fish balls and kikiam lightly with oil. Air fry at 195°C (385°F) for 6-8 mins, shaking basket halfway through, until puffed and crisp!","fil":"Paraan sa Air Fryer: I-spray ng mantika at i-air fry sa 195°C nang 6-8 minuto, alugin sa kalahati.","ja":"ノンフライヤー設定：油をスプレーし、195℃で6〜8分加熱。途中で一度バスケットを振って均一に膨らませます。","ko":"에어프라이어 설정: 오일을 살짝 뿌리고 195°C에서 6~8분간 중간에 흔들어주며 바삭하게 조리합니다."}}]},{"stepNumber":3,"title":{"zh-TW":"竹籤串起，深情浸裹特調醬汁大快朵頤","en":"Skewer & Dip Deep into Manong’s Sauce","fil":"Ituhog sa Kawayan at Isawsaw sa Sarsa","ja":"竹串に刺し、秘伝タレにどっぷり浸して味わう","ko":"꼬치에 꿰어 마농 소스에 푹 적셔 먹기"},"instruction":{"zh-TW":"拿長竹籤將炸好的扁魚丸與 Kikiam 一串串戳起（每串約 4-5 顆）。整串直接插進老爹特調黑糖甜辣醬罐中，旋轉裹滿濃稠琥珀糖漿，接著依喜好在隔壁蒜辣洋蔥白醋罐中點蘸一下，一口咬下外脆內Ｑ，酸甜辣鹹在舌尖狂歡！","en":"Skewer 4-5 balls onto long bamboo sticks. Plunge the skewer deep into your jar of thick Manong sauce, twisting so the glossy caramel coats every sphere. Tap lightly in the spiced vinegar jar next door, and experience Manila street bliss in every bite!","fil":"Tuhugin ng 4-5 piraso sa patpat ng kawayan. Isawsaw nang sagana sa garapon ng sarsa ni Manong bago isubo!","ja":"竹串に4〜5個刺します。マノン特製ソースの瓶にどっぷりと浸し、隣のピリ辛酢に少しチョンとつけます。カリッとモチモチの食感と甘酸っぱいタレが口いっぱいに広がります！","ko":"긴 대나무 꼬치에 4~5개씩 꿰어줍니다. 묵직한 마농 소스 병에 깊숙이 담가 소스를 듬뿍 묻히고, 매콤한 식초에 살짝 찍어 한입 가득 즐기세요!"},"durationSeconds":60,"image":"/images/ph/fish-balls-step3.jpg"}],"troubleshooting":[{"id":"sauce-too-watery","problem":{"zh-TW":"醬汁太稀薄，無法掛在炸好的魚丸表面","en":"Sauce is watery and runs off the balls instead of clinging","fil":"Masyadong malabnaw ang sarsa at hindi kumakapit sa fish balls","ja":"ソースがサラサラすぎて魚団子に絡まない","ko":"소스가 너무 묽어서 어묵 표면에 묻지 않고 흘러내림"},"cause":{"zh-TW":"玉米澱粉水比例不足，或加熱時間太短未徹底糊化沸騰","en":"Insufficient cornstarch or did not bring to a full boil to activate starch","fil":"Kulang sa cornstarch o hindi nakulo nang husto","ja":"コーンスターチが足りないか、沸騰させてとろみを引き出さなかったため","ko":"전분 양이 부족했거나 충분히 끓여 호화시키지 않았음"},"solution":{"zh-TW":"補調 1 茶匙玉米粉加少許水，倒回小鍋中微沸攪拌 1 分鐘，直到醬汁呈現如蜂蜜般濃稠透亮。","en":"Add 1 more tsp of cornstarch slurry and simmer for 1 minute until sauce thickens like syrup.","fil":"Magdagdag ng kaunting tinunaw na cornstarch at pakuluan pa nang 1 minuto.","ja":"水溶きコーンスターチ小さじ1を足し、弱火で1分加熱するとトロリと濃密なタレになります。","ko":"전분물 1작은술을 더 넣고 1분간 저어가며 끓여 시럽처럼 농도를 잡아주세요."}}],"proTips":[{"zh-TW":"【老街老爹醬汁秘訣】：路邊小販的大罐醬汁之所以無比誘人，是因為蒜碎、洋蔥碎與朝天椒在溫熱的黑糖醬油中浸泡了一整天，所有辛香全部溶進了甜漿中。在家做可以提前半天熬好放涼，風味更上一層樓！","en":"The Secret of Aging Sauce: Street cart sauce tastes unbelievable because the raw garlic, onion, and crushed chilies steep in the warm sweet soy syrup for hours. Make your sauce a few hours ahead for maximum depth of flavor!","fil":"Lihim ni Manong: Mas masarap ang sarsa kapag nababad ang bawang at sili sa arnibal nang ilang oras.","ja":"マノン秘伝の熟成：屋台のタレが美味しいのは、ニンニクや唐辛子が甘辛ダレに何時間も漬かってエキスが溶け出しているから。数時間前に作っておくと格段に美味しくなります！","ko":"마농 소스의 숙성 비결: 마늘과 양파, 고추가 달콤한 흑당 간장 소스에 몇 시간 동안 푹 우러나야 깊은 맛이 납니다. 몇 시간 전 미리 만들어 두시면 최고의 맛을 냅니다."}]}];
